/**
 * Funcion generica para crear objeto HTMLResponse para AJAX
 */
function objetoAjax() {
    var xmlhttp = false;
    try {
        xmlhttp = new ActiveXObject("Msxml2.XMLHTTP");
    } catch (e) {
        try {
            xmlhttp = new ActiveXObject("Microsoft.XMLHTTP");
        } catch (E) {
            xmlhttp = false;
        }
    }

    if (!xmlhttp && typeof XMLHttpRequest != 'undefined') {
        xmlhttp = new XMLHttpRequest();
    }
    return xmlhttp;
}

/**
 * Funcion que inicializa ciertas variables
*/
function init(flag_protect) {
    $('body').dblclick(function (e) {
        e.preventDefault();
        e.stopImmediatePropagation();
    });

    if (informeProcess == 1) {
        setTimeout(init, 300000, false);
        return;
    }

    /*if (isRequestActive) {
        console.log("Petición bloqueada, Vamos a Reintentar.");
        setTimeout(init, RETRY_DELAY, flag_protect);
        return;
    }*/

    var url = "../common/chequea_notificaciones.php";
    var ajax = objetoAjax();

    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            isRequestActive = false;
            if (ajax.status == 200) {
                if (flag_protect) {
                    esperaRespuesta(false);
                }
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);
                    if (jsonData.estado == 1) {
                        showDialog(jsonData.mensaje);
                    } else if (jsonData.estado == 2) {
                        showDialog(jsonData.mensaje);
                        flag_echar = true;
                    } else {
                        if (jsonData.notificaciones) {
                            showNotificacionesIcon(true);
                            verNotificaciones();
                        } else if (muestra_indicadores) {
                            activaIndicadores();
                        }

                        $(function () {
                            $.datepicker.setDefaults($.datepicker.regional[idiomaNavegador]);
                            $("#fecha_inicio_puestos").datepicker({
                                firstDay: 1,
                                dateFormat: "dd-mm-yy"
                            });
                        });
                    }
                    setTimeout(init, 300000, false);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            } else {
                showDialog("Error: " + ajax.status);
            }
        }
    };

    isRequestActive = true;
    esperaRespuesta(flag_protect);
    ajax.send(null);
}

/**
 * Funcion de logout
 */
function logout() {
    if (watchID != null) {
        navigator.geolocation.clearWatch(watchID);
        watchID = null;
    }
    window.location = '../inc/salir.php';
}

/**
 * Funcion de logoutQuick
 */
function logoutQuick() {
    if (watchID != null) {
        navigator.geolocation.clearWatch(watchID);
        watchID = null;
    }
    window.location = '../inc/salirQuick.php';
}

/**
 * Funcion para la validacion de string en JS
*/
function escapeHTML(str) {
    return str.replace(/[&<>"'\/]/g, function (char) {
        switch (char) {
            case '&':
                return '&amp;';
            case '<':
                return '&lt;';
            case '>':
                return '&gt;';
            case '"':
                return '&quot;';
            case "'":
                return '&#39;';
            case '/':
                return '&#x2F;';
            default:
                return char;
        }
    });
}



/**
 * Funcion que detecta Enter para lanzar formulario
 */
function checkEnter(e) {
    tecla = (document.all) ? e.keyCode : e.which;
    if (tecla == 13) {
        var formulario = document.getElementById("login_form");
        formhash(formulario, formulario.password);
    }
}

/**
 * Funcion que cambia el formulario de entrada por uno de recuerdo de contraseña
 *
 */
function reminder(formulario, flagMobile) {
    if (formulario != null) {
        var url = "";
        var ajax = objetoAjax();;
        url = "./common/formulario_olvido.php?mob=" + flagMobile;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                        } else {
                            var arrDiv = document.getElementsByTagName('div');
                            for (var i = 0; i < arrDiv.length; i++) {
                                if (arrDiv[i].classList.contains("block01")) {
                                    arrDiv[i].innerHTML = arr_aux[1];
                                    if (flagMobile != 1) {
                                        arrDiv[i].style.marginTop = "100px";
                                    }
                                }
                            }
                            var arrH1 = document.getElementsByTagName('h1');
                            arrH1[0].style.display = "block";
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                }
                else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        ajax.send(null);
    }
}

/**
 * Funcion que chequea y envia un email con la contraseña cambiada
 *
 */
function sendPass(formulario) {
    if (formulario != null) {
        var usuario = formulario.usuario;
        var email = formulario.email;

        if (usuario.value != "" && email.value != "") {
            var url = "";
            var ajax = objetoAjax();

            var formData = new FormData();
            formData.append('us', usuario.value);
            formData.append('ml', email.value);

            var url = "";
            var ajax = objetoAjax();

            url = "./common/envio_mail_olvido.php";
            ajax.open("POST", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 1) {
                                showDialog(arr_aux[1]);
                            } else {
                                showDialog(arr_aux[1]);
                                flag_recarga = true;
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    }
                    else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            ajax.send(formData);
            esperaRespuesta(true);
        }
    }
}

/**
 * Funcion que cambia el contenido del menu por el submenu
 *
 */
function showSubMenu(elemento, menu_opcion) {

    tab_activo = null;
    if (elemento != null) {
        elemento.className = "activo";
        menu_activo = elemento;
    }

    $('body').click(function (e) {
        e.preventDefault();
        e.stopImmediatePropagation(); //charles ma is right about that, but stopPropagation isn't also needed
    });

    if (!isNaN(menu_opcion) || menu_opcion < 0 || menu_opcion > 9) {
        var url = "";
        var ajax = objetoAjax();;
        url = "../common/gen_submenu.php?op=" + menu_opcion;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            document.getElementById("submenu").innerHTML = arr_aux[1];
                            document.getElementById("subminimenu").innerHTML = arr_aux[2];
                            if (menu_activo != null) {
                                var elements = document.getElementsByTagName('li');

                                for (var i = 0; i < elements.length; i++) {
                                    if (elements[i].className.indexOf("activo") >= 0 && menu_activo != elements[i]) {
                                        elements[i].classList.remove('activo');
                                    }
                                }
                            }
                            if (muestra_indicadores == true) {
                                activaIndicadores();
                            }
                            $('body').unbind();
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                }
                else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        esperaRespuesta(true);
        ajax.send(null);
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion que evita que salga constantemente el aviso de las cookies
 *
 */
function cierraCookies() {
    var url = '../common/check_cookies.php';
    var ajax2 = objetoAjax();
    ajax2.open("GET", url, true);
    ajax2.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=ISO-8859-1');
    ajax2.onreadystatechange = function () {
        if (ajax2.readyState == 4) {
            if (ajax2.status == 200) {
                var html_txt = ajax2.responseText;
                if (html_txt != "") {
                    var arr_aux = html_txt.split("|");
                    if (arr_aux[0] != 0) {
                        showDialog(arr_aux[1]);
                    } else {
                        document.getElementById("cookies").style.display = "none";
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax2.status == 404) {
                showDialog(error404);
            }
            else if (ajax2.status != 0) {
                showDialog("Error:" + ajax2.status);
            }
        }
    };
    ajax2.send(null);
}

/**
 * Funcion que chequea todos los checkbox de la tabla de resultados
 *
 */
function checkAll() {
    var id_suiche = 0;
    var arrInput = document.getElementsByTagName('input');
    for (var i = 0; i < arrInput.length; i++) {
        if (arrInput[i].type == 'checkbox' && (arrInput[i].name == 'id' || arrInput[i].name == 'empleado_id' || arrInput[i].name == 'plan_id' || arrInput[i].name == 'centro_id')) {
            arrInput[i].checked = true;
            idSeleccionadas.push(arrInput[i].value);
        } else if (arrInput[i].type == 'checkbox' && (arrInput[i].name == 'id_encuesta' || arrInput[i].name == 'id_empleado' || arrInput[i].name == 'id_informe_empleado')) {
            arrInput[i].checked = true;
            var id_suiche = 2;
        }
    }
    if (id_suiche != 0) {
        SelectNumeroEncuestas(null, null, id_suiche);
    }
    toggleAccionMultiple(null);
}

