/**
 * Funcion que recarga la lista de Departamentos
 *
 */
function reloadDepartamentos(selectBox, menu_opcion, submenu_opcion) {
    if (selectBox != null) {
        var centros_id = selectBox.options[selectBox.selectedIndex].value;
        var departamentosSelect = document.getElementById("id_departamentos");
        var texto = departamentosSelect.options[0].text;
        departamentosSelect.options.length = 0;
        departamentosSelect.options[0] = new Option(texto, "");
        if (document.getElementById("id_empleados") != null) {
            empleadosSelect = document.getElementById("id_empleados");
            texto = empleadosSelect.options[0].text;
            empleadosSelect.options.length = 0;
            empleadosSelect.options[0] = new Option(texto, "");
        }
        planesSelect = document.getElementById("id_planes");
        if (planesSelect != null) {
            texto = planesSelect.options[0].text;
            planesSelect.options.length = 0;
            planesSelect.options[0] = new Option(texto, "");
        }
        if (document.getElementById("body_tabla_empleados_rec_facial") != null) {
            body_tabla_empleados_rec_facial = document.getElementById("body_tabla_empleados_rec_facial");
            body_tabla_empleados_rec_facial.innerHTML = "";
        }
        if (document.getElementById("body_empleados_disponibles") != null) {
            var bodyEmpleadosDisponibles = document.getElementById("body_empleados_disponibles");
            bodyEmpleadosDisponibles.innerHTML = "";
        }
        if (centros_id != "") {
            var url = "";
            var ajax = objetoAjax();
            url = "../common/recarga_departamentos.php?op=" + menu_opcion + "&sub=" + submenu_opcion + "&id=" + centros_id;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);

                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                var arr_departamentos = jsonData.departamentos;
                                var arr_idDepartamentos = jsonData.id_departamentos;
                                var arr_planes = jsonData.planes;
                                var html_body_tabla_empleados_rec_facial = jsonData.html_body_tabla_empleados_rec_facial;
                                var html_body_tabla_proyectos = jsonData.html_body_tabla_proyectos;

                                if (departamentosSelect != null) {
                                    for (var key in arr_idDepartamentos) {
                                        if (arr_idDepartamentos.hasOwnProperty(key) && /^0$|^[1-9]\d*$/.test(key) && key <= 4294967294) {
                                            departamentosSelect.options[departamentosSelect.options.length] = new Option(arr_departamentos[key], arr_idDepartamentos[key]);
                                        }
                                    }
                                }
                                if (planesSelect != null) {
                                    for (var key in arr_planes) {
                                        if (arr_planes.hasOwnProperty(key) && /^0$|^[1-9]\d*$/.test(key) && key <= 4294967294) {
                                            planesSelect.options[planesSelect.options.length] = new Option(arr_planes[key], key);
                                        }
                                    }
                                }
                                var fechaCambioCentro = document.getElementById("fecha_cambio_centro");
                                if (fechaCambioCentro != null) {
                                    fechaCambioCentro.parentNode.classList.remove("oculto");
                                }
                                if (typeof body_tabla_empleados_rec_facial != "undefined") {
                                    body_tabla_empleados_rec_facial.innerHTML = html_body_tabla_empleados_rec_facial;
                                }

                                var tableBodyEmpleados = document.getElementById("listado");
                                if (tableBodyEmpleados != null) {
                                    reloadListaEmpleados(selectBox, menu_opcion, submenu_opcion);
                                }
                                if (typeof bodyEmpleadosDisponibles != 'undefined') {
                                    bodyEmpleadosDisponibles.innerHTML = html_body_tabla_proyectos;
                                    const bodyTablaEmpleadosAsignados = document.getElementById('body_empleados_asignados');
                                    if (bodyTablaEmpleadosAsignados != null) {
                                        ocultarFilasCoincidentes(bodyEmpleadosDisponibles, bodyTablaEmpleadosAsignados);
                                    }
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    }
                    else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion que recarga la lista de Empleados
 *
 */
function reloadEmpleados(menu_opcion, submenu_opcion, selectBox) {
    if (selectBox != null) {
        var departamentos_id = selectBox.options[selectBox.selectedIndex].value;
        if (document.getElementById("id_empleados") != null) {
            var empleadosSelect = document.getElementById("id_empleados");
            texto = empleadosSelect.options[0].text;
            empleadosSelect.options.length = 0;
            empleadosSelect.options[0] = new Option(texto, "");
        }
        if (document.getElementById("body_tabla_empleados_rec_facial") != null) {
            body_tabla_empleados_rec_facial = document.getElementById("body_tabla_empleados_rec_facial");
            body_tabla_empleados_rec_facial.innerHTML = "";
        }
        if (document.getElementById("body_empleados_disponibles") != null) {
            var bodyEmpleadosDisponibles = document.getElementById("body_empleados_disponibles");
            bodyEmpleadosDisponibles.innerHTML = "";
        }
        if (departamentos_id != "") {
            var url = "";
            var ajax = objetoAjax();;
            url = "../common/recarga_empleados.php?op=" + menu_opcion + "&sub=" + submenu_opcion + "&id=" + departamentos_id;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);

                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                var arr_empleados = jsonData.empleados;
                                var html_body_tabla_empleados_rec_facial = jsonData.html_body_tabla_empleados_rec_facial;
                                var html_body_tabla_proyectos = jsonData.html_body_tabla_proyectos;

                                if (empleadosSelect != null) {
                                    for (var key in arr_empleados) {
                                        if (arr_empleados.hasOwnProperty(key) && /^0$|^[1-9]\d*$/.test(key) && key <= 4294967294) {
                                            empleadosSelect.options[empleadosSelect.options.length] = new Option(arr_empleados[key], key);
                                        }
                                    }
                                }
                                if (typeof body_tabla_empleados_rec_facial != 'undefined') {
                                    body_tabla_empleados_rec_facial.innerHTML = html_body_tabla_empleados_rec_facial;
                                }
                                if (typeof bodyEmpleadosDisponibles != 'undefined') {
                                    bodyEmpleadosDisponibles.innerHTML = html_body_tabla_proyectos;
                                    const bodyTablaEmpleadosAsignados = document.getElementById('body_empleados_asignados');
                                    if (bodyTablaEmpleadosAsignados != null) {
                                        ocultarFilasCoincidentes(bodyEmpleadosDisponibles, bodyTablaEmpleadosAsignados);
                                    }
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    }
                    else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion que recarga la lista de Departamentos
 *
 */
function reloadListaEmpleados(selectBox, menu_opcion, submenu_opcion) {
    if (selectBox != null) {
        var centros_id = selectBox.options[selectBox.selectedIndex].value;

        if (centros_id != "") {
            var url = "";
            var ajax = objetoAjax();;
            url = "../common/recarga_lista_empleados.php?id=" + centros_id + "&op=" + menu_opcion + "&sub=" + submenu_opcion;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);

                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                var arr_empleados = jsonData.lista_empleados;
                                var tableBodyEmpleados = document.getElementById("listado");
                                if (tableBodyEmpleados != null) {
                                    tableBodyEmpleados.innerHTML = "";
                                    for (var key in arr_empleados) {
                                        if (arr_empleados.hasOwnProperty(key) && /^0$|^[1-9]\d*$/.test(key) && key <= 4294967294) {
                                            var fila = document.createElement("tr");
                                            var celdaInput = document.createElement("td");
                                            var inputCheck = document.createElement("input");
                                            inputCheck.type = "checkbox";
                                            inputCheck.name = "empleado_id";
                                            inputCheck.value = key;
                                            celdaInput.appendChild(inputCheck);
                                            fila.appendChild(celdaInput);
                                            var celdaNombre = document.createElement("td");
                                            celdaNombre.innerHTML = arr_empleados[key];
                                            fila.appendChild(celdaNombre);
                                            tableBodyEmpleados.appendChild(fila);
                                        }
                                    }
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    }
                    else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}

