/**
 * Funcion que recarga la lista de Provincias
 *
 */
function reloadPoblaciones(selectBox) {
    if (selectBox != null) {

        // Municipios Aqui
        var CodPais = document.getElementById("id_paises").value;
        if (CodPais == paisVenezuela) {
            var municipiosSelect = document.getElementById("municipio");
            var texto = municipiosSelect.options[0].text;
            municipiosSelect.options.length = 0;
            municipiosSelect.options[0] = new Option(texto, "");

            //hacer una condicional donde si municipioSelect tiene la propiedad disabled, se le quite
            if (municipiosSelect.hasAttribute("disabled")) {
                municipiosSelect.removeAttribute("disabled");
            }

            var poblacionSelect = document.getElementById("poblacion");
            //hacer una condicional donde si municipioSelect tiene la propiedad disabled, se le quite
            if (poblacionSelect.hasAttribute("disabled")) {
                poblacionSelect.removeAttribute("disabled");
            }
        } else {
            var poblacionSelect = document.getElementById("poblacion");
            //hacer una condicional donde si municipioSelect tiene la propiedad disabled, se le quite
            if (poblacionSelect != null && poblacionSelect.hasAttribute("disabled")) {
                poblacionSelect.removeAttribute("disabled");
            }
        }

        var provincias_id = selectBox.options[selectBox.selectedIndex].value;
        var poblacionesSelect = document.getElementById("poblacion");
        var texto = poblacionesSelect.options[0].text;
        poblacionesSelect.options.length = 0;
        poblacionesSelect.options[0] = new Option(texto, "");

        var codigosPostalesSelect = document.getElementById("id_codpostal");
        var texto = codigosPostalesSelect.options[0].text;
        codigosPostalesSelect.options.length = 0;
        codigosPostalesSelect.options[0] = new Option(texto, "");
        if (provincias_id != "") {
            var url = "";
            var ajax = objetoAjax();;
            url = "../common/recarga_poblaciones.php?id=" + provincias_id;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 1) {
                                showDialog(arr_aux[1]);
                            } else if (arr_aux[0] == 2) {
                                showDialog(arr_aux[1]);
                                flag_echar = true;
                            } else {
                                //Municipios Aqui
                                if (CodPais == paisVenezuela) {
                                    var arr_selects = arr_aux[1].split("#");
                                    var arr_datosmupo = arr_selects[0].split(";");
                                    var arr_codigos_postales = arr_selects[1].split(";");
                                    var arr_municipios = [];
                                    for (var ind = 0; ind <= (arr_datosmupo.length - 1); ind++) {
                                        var arr_pobla_mun = arr_datosmupo[ind].split("**");
                                        municipiosSelect.options[municipiosSelect.options.length] = new Option(arr_pobla_mun[0], arr_datosmupo[ind]);
                                        arr_municipios.push(arr_pobla_mun[1]);
                                    }

                                    let municipioslimpio = arr_municipios.filter((item, index) => {
                                        return arr_municipios.indexOf(item) === index;
                                    });

                                    for (var ind = 0; ind <= (municipioslimpio.length - 1); ind++) {
                                        poblacionesSelect.options[poblacionesSelect.options.length] = new Option(municipioslimpio[ind], municipioslimpio[ind]);
                                    }

                                    for (var ind = 0; ind <= (arr_codigos_postales.length - 1); ind++) {
                                        codigosPostalesSelect.options[codigosPostalesSelect.options.length] = new Option(arr_codigos_postales[ind].split(",")[1], arr_codigos_postales[ind].split(",")[0]);
                                    }
                                } else {
                                    var arr_selects = arr_aux[1].split("#");
                                    var arr_poblaciones = arr_selects[0].split(";");
                                    var arr_codigos_postales = arr_selects[1].split(";");

                                    for (var ind = 0; ind <= (arr_poblaciones.length - 1); ind++) {
                                        poblacionesSelect.options[poblacionesSelect.options.length] = new Option(arr_poblaciones[ind], arr_poblaciones[ind]);
                                    }
                                    for (var ind = 0; ind <= (arr_codigos_postales.length - 1); ind++) {
                                        codigosPostalesSelect.options[codigosPostalesSelect.options.length] = new Option(arr_codigos_postales[ind].split(",")[1], arr_codigos_postales[ind].split(",")[0]);
                                    }
                                }

                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}


