/**
 * Funcion que recarga la lista de Años de Imputación de un Horario Permiso.
 *
 */
function reloadImputaciones(idHorarioPermiso) {
    //if(selectBox != null){
    let selectBox = document.getElementById('imputacion');
    let texto = selectBox.options[0].text;
    selectBox.options.length = 0;
    selectBox.options[0] = new Option(texto, "");

    if (idHorarioPermiso != "") {
        var url = "";
        var ajax = objetoAjax();;
        url = "../common/recarga_imputaciones.php?id=" + idHorarioPermiso;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            //Do nothing
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            var arrImputaciones = arr_aux[1].split(";");
                            for (var ind = 0; ind <= (arrImputaciones.length - 1); ind++) {
                                selectBox.options[selectBox.options.length] = new Option(arrImputaciones[ind].split(",")[1], arrImputaciones[ind].split(",")[0]);
                            }
                            if (arr_aux[2] == 1) {
                                //Si la validacion anterior es correcta requiero esconder el input con id="fecha_inicio" y id="fecha_fin" y mostrar el input con id="fecha_inicio_sercorp" y id="fecha_fin_sercorp"
                                document.getElementById("fecha_inicio").style.display = "none";
                                document.getElementById("fecha_fin").style.display = "none";
                                document.getElementById("fecha_inicio_sercorp").style.display = "block";
                                document.getElementById("fecha_fin_sercorp").style.display = "block";
                            } else {
                                //Si la validacion anterior es incorrecta requiero esconder el input con id="fecha_inicio_sercorp" y id="fecha_fin_sercorp" y mostrar el input con id="fecha_inicio" y id="fecha_fin"
                                document.getElementById("fecha_inicio_sercorp").style.display = "none";
                                document.getElementById("fecha_fin_sercorp").style.display = "none";
                                document.getElementById("fecha_inicio").style.display = "block";
                                document.getElementById("fecha_fin").style.display = "block";
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        esperaRespuesta(true);
        ajax.send(null);
    }
    // }else{
    //     showDialog(invalidOption);
    // }
}

