/**
 * Funcion que reloadGrupoHoras de omie para sacar estadisticas
 *
 */
function reloadGrupoHorasSolHoras(menu_opcion, submenu_opcion) {

    var fecha = document.getElementsByName("fecha_ini")[0].value;
    var idEmpleado = document.getElementsByName("id_empleados")[0].value;

    if (fecha != null && !isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        if (idEmpleado != "") {
            var url = "";
            var ajax = objetoAjax();
            url = "../common/recarga_horas_grupo_solicitud_horas.php?id=" + idEmpleado + "&op=" + menu_opcion + "&sub=" + submenu_opcion + "&fecha=" + fecha;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);
                            if (jsonData.status == 1) {
                                showDialog(jsonData.mensaje);

                            } else if (jsonData.status == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else {
                                var message = "<b>Entrada:</b> " + jsonData.entrada +
                                    "<br><b>Salida:</b> " + jsonData.salida +
                                    "<br><b>Teóricas:</b> " + jsonData.teoricas +
                                    "<br><b>Trabajadas:</b> " + jsonData.trabajadas +
                                    "<br><b>Presencia:</b> " + jsonData.presencia +
                                    "<br><b>Exceso Defecto Día:</b> " + jsonData.exceso_defecto_dia +
                                    "<br><b>Exceso Defecto Mes:</b> " + jsonData.exceso_defecto_mes +
                                    "<br><b>Exceso Defecto Año:</b> " + jsonData.exceso_defecto_year;
                                showDialog(message);

                            }
                        } else {

                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        } else {
            showDialog(invalidOptionEmpleado);
        }

    } else {
        showDialog(invalidOption);
    }

}


