/**
 * Funcion que replica los valores de un día para confeccionar un horario
 *
 */
function replicarHorario(fila, selectReplicar, turno = 0) {
    var namesinputs = ["inicio_tramo_", "fin_tramo_", "flex_inicio_", "flex_fin_"];
    var nameTramoComida = "tramo_comida";
    var idFilaOriginal = selectReplicar.value;
    var idFilaDestino = fila;
    if (turno == 0) {

        //var numTramos = 6;
        var numTramos = 6;

        var elementoOrigen;
        var elementoDestino;

        //TRAMOS DEL 1 AL 6
        for (indtramo = 1; indtramo <= numTramos; indtramo++) {

            for (jdxnames = 0; jdxnames < namesinputs.length; jdxnames++) {
                elementoOrigen = document.getElementById(namesinputs[jdxnames] + indtramo + "-" + idFilaOriginal);
                elementoDestino = document.getElementById(namesinputs[jdxnames] + indtramo + "-" + idFilaDestino);

                if (jdxnames < 2) {
                    elementoDestino.value = elementoOrigen.value;
                } else {
                    elementoDestino.checked = elementoOrigen.checked;
                }
            }
        }

        //AHORA TOCA TRAMO COMIDA
        elementoOrigen = document.getElementById(nameTramoComida + "-" + idFilaOriginal);
        elementoDestino = document.getElementById(nameTramoComida + "-" + idFilaDestino);
        elementoDestino.value = elementoOrigen.value;

        //RECALCULO DE HORAS TOTALES
        calculaTiempo(fila, turno);
    }
}

