/**
 * Funcion que envia mails de recordatorio a encuestas no realizadas
 *
 */
function enviaNotificacion(menu_opcion, submenu_opcion, msj, accion, idElemento, filtro, msjInicial, asunto) {
    var listaNotificar = document.getElementById("lista_empleados");
    if (listaNotificar != null) {
        if (msj != "") {
            if (msjInicial != null && msjInicial != "") {
                showDialog(msjInicial + "<br>" + mensaje_enviar_notificaciones);
            } else {
                showDialog(mensaje_enviar_notificaciones);
            }
            var formData = new FormData();
            formData.append('ids', listaNotificar.value);
            formData.append('msj', msj);
            if (asunto != null && asunto != "") {
                formData.append('subj', asunto);
            }
            var url = "";
            var ajax = objetoAjax();
            url = "../common/enviar_notificaciones.php";
            ajax.open("POST", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 2) {
                                var jsonData = JSON.parse(arr_aux[1]);
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else {
                                var jsonData = JSON.parse(arr_aux[1]);
                                showDialog(jsonData.mensaje, false);
                                if (accion != null && accion != undefined) {
                                    limpiarFiltros(menu_opcion, submenu_opcion, accion, filtro, idElemento);
                                } else {
                                    limpiarFiltros(menu_opcion, submenu_opcion, accionLista, null);
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        esperaRespuesta(false);
                        showDialog(error404);
                    }
                    else if (ajax.status != 0) {
                        esperaRespuesta(false);
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            ajax.send(formData);
            //ajax.send(null);
            esperaRespuesta(true);
        } else if (msjInicial != null && msjInicial != "") {
            showDialog(msjInicial);
            if (accion != null && accion != undefined) {
                limpiarFiltros(menu_opcion, submenu_opcion, accion, filtro, idElemento);
            } else {
                limpiarFiltros(menu_opcion, submenu_opcion, accionLista, null);
            }
        } else {
            if (accion != null && accion != undefined) {
                limpiarFiltros(menu_opcion, submenu_opcion, accion, filtro, idElemento);
            } else {
                limpiarFiltros(menu_opcion, submenu_opcion, accionLista, null);
            }
        }
    } else {
        limpiarFiltros(menu_opcion, submenu_opcion, accionLista, null);
    }
}

/**
 * Funcion que envia mails de recordatorio a multiples solicitudes
 *
 */
function enviaNotificacionMultiple(menu_opcion, submenu_opcion, solicitudes, errores) {

    if (solicitudes != null) {
        var numeroSol = solicitudes.length;
        var msjInicial = "";
        var arrEmpleados = new Array();
        var arrMsjNot = new Array();
        for (var i = 0; i < numeroSol; i++) {
            msjInicial += solicitudes[i].mensaje + "<br>";
            arrEmpleados.push(solicitudes[i].lista_empleados);
            arrMsjNot.push(solicitudes[i].mensaje_notificacion);
        }
        var numeroErr = errores.length;
        for (var i = 0; i < numeroErr; i++) {
            msjInicial += errores[i] + "<br>";
        }
        if (msjInicial != null && msjInicial != "") {
            showDialog(msjInicial + "<br>" + mensaje_enviar_notificaciones);
        } else {
            showDialog(mensaje_enviar_notificaciones);
        }
        var formData = new FormData();
        formData.append('empleados', JSON.stringify(arrEmpleados));
        formData.append('mensajes', JSON.stringify(arrMsjNot));
        var url = "";
        url = "../common/enviar_notificaciones_multiple.php";
        var ajax = objetoAjax();
        ajax.open("POST", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 2) {
                            var jsonData = JSON.parse(arr_aux[1]);
                            showDialog(jsonData.mensaje);
                            flag_echar = true;
                        } else {
                            var jsonData = JSON.parse(arr_aux[1]);
                            var mensaje = jsonData.mensaje;
                            if (numeroErr > 0) {
                                mensaje += "<br>" + mensaje_error_solicitudes_multiples
                                for (var i = 0; i < numeroErr; i++) {
                                    mensaje += "<br>" + errores[i];
                                }
                            }
                            showDialog(mensaje, false);
                            limpiarFiltros(menu_opcion, submenu_opcion, accionLista, null);
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    esperaRespuesta(false);
                    showDialog(error404);
                } else if (ajax.status != 0) {
                    esperaRespuesta(false);
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        ajax.send(formData);
        //ajax.send(null);
        esperaRespuesta(true);
    } else {
        limpiarFiltros(menu_opcion, submenu_opcion, accionLista, null);
    }
}

