                //Fechas
                var inputFechaInicio = document.getElementById("fecha_inicio_sindicato");
                var inputFechaFin = document.getElementById("fecha_fin_sindicato");
                if (inputFechaInicio != null && inputFechaInicio.value !== "" && inputFechaFin != null && inputFechaFin.value !== "") {
                    var partesInicio = inputFechaInicio.value.split("-");
                    var partesFin = inputFechaFin.value.split("-");

                    var fechaInicio = new Date(partesInicio[2], partesInicio[1] - 1, partesInicio[0]); // Y, M-1, D
                    var fechaFin = new Date(partesFin[2], partesFin[1] - 1, partesFin[0]);
                    var hoy = new Date();

                    fechaInicio.setHours(0, 0, 0, 0);
                    fechaFin.setHours(0, 0, 0, 0);
                    hoy.setHours(0, 0, 0, 0);

                    if (fechaFin < hoy) {
                        showDialog(mensaje_error_fecha_no_vigente);
                        return;
                    }

                    if (fechaInicio < hoy) {
                        showDialog(mensaje_error_fecha_inicio_no_vigente);
                        return;
                    }

                    if (fechaInicio > fechaFin) {
                        showDialog(mensaje_error_fechas_erroneas);
                        return;
                    }

                    formData.append(inputFechaInicio.name, inputFechaInicio.value);
                    formData.append(inputFechaFin.name, inputFechaFin.value);

                } else {
                    showDialog(mensaje_error_fecha_no_valido);
                    return;
                }

