/**
 * Funcion que envia contenido de firma con evidencias
 *
 */
function showfirma(texto, param1, param2) {
    esperaRespuesta(true);
    $.ajax({
        method: "GET",
        url: "../common/save_evidencias_firma.php",
        data: { id: param1, num: param2 },
        success: function (datas) {
            const data = datas.trim();
            if (data == true) {
                showDialog(noServicioFirma);
                esperaRespuesta(false);
            } else if (data == 'NOPDF') {
                showDialog(texto);
                esperaRespuesta(false);
            } else if (data == 'ERROR_SERVICE') {
                showDialog('No posees este Servicio Activo, Contacta con el Administrador de Sistemas');
                esperaRespuesta(false);
            } else {
                $('.tabla').append(data);
                $('#formfirma').submit();
            }
        },
        error: function (jqXHR, textStatus, errorThrown) {
            // Aquí puedes manejar los errores
            if (textStatus === 'error' || textStatus === 'timeout') {
                // Aquí puedes manejar el error de conexión
                console.log('La conexión se perdió: ' + textStatus);
            }
            console.log(jqXHR);
            console.log(textStatus);
            console.log(errorThrown);
            esperaRespuesta(false);
        },
        complete: function (jqXHR, textStatus) {
            // Aquí puedes manejar los errores
            console.log(jqXHR);
            console.log(textStatus);
            esperaRespuesta(false);
        }
    });
}

