/**
 * Funcion que genera el contenido en HTML de un dialogo
 *
 */
function genContenidoDialogo(texto, titulo) {
    var divElement = document.createElement('div');
    var anchorElement = document.createElement('a');
    anchorElement.innerHTML = 'X';
    anchorElement.title = 'Close';
    anchorElement.className = 'close';
    anchorElement.onclick = function () {
        hideDialog();
        if (flag_echar == true) {
            window.location = "../inc/salir.php";
            flag_echar = false;
        } else if (flag_recarga == true) {
            window.location.reload();
            flag_recarga = false;
        }
    };
    var h2Element = document.createElement('h2');
    if (titulo != null && titulo != "") {
        h2Element.innerHTML = titulo;
    } else {
        h2Element.innerHTML = aviso;
    }
    var pElement = document.createElement('p');
    pElement.innerHTML = texto;
    divElement.appendChild(anchorElement);
    divElement.appendChild(h2Element);
    divElement.appendChild(pElement);
    return divElement;
}


/**
 * Funcion que genera el contenido para modificar hora (fichajes)
 *
 */
function genContenidoVentana(contenido, idFichaje) {
    var divElement = document.createElement('div');
    divElement.className = 'ventana-update';
    var anchorElement = document.createElement('a');
    anchorElement.innerHTML = 'X';
    anchorElement.title = 'Close';
    anchorElement.className = 'close';
    anchorElement.onclick = function () {
        cierraVentana(idFichaje);
        if (flag_echar == true) {
            window.location = "../inc/salir.php";
            flag_echar = false;
        } else if (flag_recarga == true) {
            window.location.reload();
            flag_recarga = false;
        }
    };

    var tdHora = document.getElementById('hora-' + idFichaje);
    var coordTd = tdHora.getBoundingClientRect();
    var margen = coordTd.top - 63;

    divElement.style.marginTop = margen + 'px';

    var pElement = document.createElement('div');
    pElement.innerHTML = contenido;
    divElement.appendChild(anchorElement);
    divElement.appendChild(pElement);
    return divElement;
}


