/**
 * Funcion que muestra la ventana de notificaciones
 *
 */
function verNotificaciones() {
    if (proceso_activo == 0) {

        var url = "";
        var ajax = objetoAjax();
        url = "../common/get_notificaciones.php";
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            if (muestra_indicadores == true) {
                                activaIndicadores();
                            }
                            var caja = document.getElementById('viewNotificaciones');
                            if (caja != null) {
                                hideNotificaciones();
                                var notificaciones = JSON.parse(arr_aux[1]);
                                var divElement = document.createElement('div');
                                var anchorElement = document.createElement('a');
                                anchorElement.innerHTML = 'X';
                                anchorElement.title = 'Close';
                                anchorElement.className = 'close_not';
                                anchorElement.onclick = function () {
                                    hideNotificaciones();
                                };
                                var h2Element = document.createElement('h2');
                                h2Element.innerHTML = texto_notificaciones;
                                divElement.appendChild(anchorElement);
                                if (notificaciones.length > 1) {
                                    var anchorElement2 = document.createElement('a');
                                    anchorElement2.innerHTML = mensaje_marcar_todo;
                                    anchorElement2.title = 'All';
                                    anchorElement2.className = 'mark_all';
                                    anchorElement2.onclick = function () {
                                        limpiaNotificaciones();
                                    };
                                    divElement.appendChild(anchorElement2);
                                }
                                divElement.appendChild(h2Element);
                                for (var i = 0; i < notificaciones.length; i++) {
                                    var pElement = document.createElement('p');
                                    var texto = '';
                                    if (notificaciones[i].mencodigoctephp != null) {
                                        texto = notificaciones[i].mencodigoctephp;
                                    } else if (notificaciones[i].codigoctephp != null) {
                                        texto = notificaciones[i].codigoctephp;
                                    } else if (notificaciones[i].mensaje != null) {
                                        texto = notificaciones[i].mensaje;
                                    }
                                    pElement.innerHTML = texto;
                                    pElement.id = notificaciones[i].id;
                                    pElement.onclick = function (evt) {
                                        hideNotificaciones();
                                        irANotificacion(evt.currentTarget.id);
                                    };
                                    divElement.appendChild(pElement);
                                }
                                caja.appendChild(divElement);
                                caja.style.opacity = 1;
                                caja.style.pointerEvents = "auto";
                            }

                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        esperaRespuesta(true);
        ajax.send(null);
    }
}

