/**
 * Funcion que la ventana de Eventos
 *
 */
function verEvento(menu_opcion, submenu_opcion, idEventos) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && !isNaN(idEventos)) {
        var url = "";
        var ajax = objetoAjax();
        url = "../common/get_evento.php?op=" + menu_opcion + "&sub=" + submenu_opcion + "&id=" + idEventos;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            var caja = document.getElementById('viewEventos');
                            if (caja != null) {
                                hideEventos();
                                var agenda = JSON.parse(arr_aux[1]);
                                var divElement = document.createElement('div');
                                var anchorElement = document.createElement('a');
                                anchorElement.innerHTML = 'X';
                                anchorElement.title = 'Close';
                                anchorElement.className = 'close_not';
                                anchorElement.onclick = function () {
                                    hideEventos();
                                };
                                var h2Element = document.createElement('h2');
                                h2Element.innerHTML = agenda.titulo;
                                divElement.appendChild(anchorElement);
                                divElement.appendChild(h2Element);
                                //Linea de Calendario
                                var pElement = document.createElement('p');

                                var bElement = document.createElement('b');
                                bElement.innerHTML = agenda.calendario;
                                bElement.style.float = "left";
                                bElement.style.lineHeight = "40px";
                                pElement.appendChild(bElement);

                                var spanElement = document.createElement("span");
                                spanElement.innerHTML = "&nbsp";
                                spanElement.style.float = "left";
                                spanElement.style.width = "20px";
                                spanElement.style.height = "20px";
                                spanElement.style.borderRadius = "50%";
                                spanElement.style.margin = "10px 20px";
                                spanElement.classList.add("relleno" + agenda.estilo);
                                pElement.appendChild(spanElement);

                                divElement.appendChild(pElement);

                                //Linea de Inicio y Fin
                                pElement = document.createElement('p');
                                pElement.innerHTML = agenda.inicio + " - " + agenda.fin;
                                divElement.appendChild(pElement);

                                //Linea URL
                                if (agenda.url != null && agenda.url != "") {
                                    if (agenda.url.indexOf("http") <= -1) {
                                        agenda.url = "http://" + agenda.url;
                                    }
                                    pElement = document.createElement('p');
                                    pElement.innerHTML = agenda.url;
                                    pElement.style.cursor = "pointer";
                                    pElement.onclick = function (evt) {
                                        window.open(agenda.url);
                                    };
                                    divElement.appendChild(pElement);
                                }

                                //Notas
                                if (agenda.notas != null && agenda.notas != "") {
                                    pElement = document.createElement('p');
                                    pElement.innerHTML = agenda.notas;
                                    divElement.appendChild(pElement);
                                }

                                caja.appendChild(divElement);
                                caja.style.opacity = 1;
                                caja.style.pointerEvents = "auto";
                            }

                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        esperaRespuesta(true);
        ajax.send(null);
    } else {
        showDialog(invalidOption);
    }
}

