/**
 * Funcion que va al modulo que genero la notificacion
 *
 */
function irANotificacion(id) {
    var url = "";
    var ajax = objetoAjax();
    url = "../common/go_notificaciones.php?id=" + id;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var arr_aux = html_txt.split("|");
                    if (arr_aux[0] == 1) {
                        showDialog(arr_aux[1]);
                    } else if (arr_aux[0] == 2) {
                        showDialog(arr_aux[1]);
                        flag_echar = true;
                    } else {
                        var notificacion = JSON.parse(arr_aux[1]);
                        var seccion_id = 0;
                        var elemento_id = 0;
                        if (notificacion.seccion_id != null && notificacion.elemento_id != null) {
                            seccion_id = notificacion.seccion_id;
                            elemento_id = notificacion.elemento_id;
                        } else if (notificacion.seccion_emp_id != null && notificacion.elemento_emp_id != null) {
                            seccion_id = notificacion.seccion_emp_id;
                            elemento_id = notificacion.elemento_emp_id;
                        }
                        if (notificacion.operacion == "INFORMDOWN") {
                            window.open(notificacion.mensaje);
                        } else if (seccion_id != 0 && elemento_id != 0) {
                            irAContenido(menu_activo, seccion_id, elemento_id);
                        }

                        showNotificacionesIcon(notificacion.icono);
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            } else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status);
            }
        }
    };
    esperaRespuesta(true);
    ajax.send(null);
}

/**
 * Funcion que va al modulo que genero la notificacion
 *
 */
function showNotificacionesIcon(flag) {
    var notificaciones = document.getElementsByClassName("notificaciones");
    for (var i = 0; i < notificaciones.length; i++) {
        if (flag == true) {
            notificaciones[i].style.display = "block";
        } else {
            notificaciones[i].style.display = "none";
        }
    }
}

