/**
 * Funcion que finaliza la fecha y la hora de la visita multiple
 *
 */
function finalizarVisitasMultiple(menu_opcion, submenu_opcion) {
    var arrIdElementos = new Array();
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var arrInput = document.getElementsByTagName('input');
        for (var i = 0; i < arrInput.length; i++) {
            if (arrInput[i].type == 'checkbox' && arrInput[i].name == 'id' && arrInput[i].checked == true) {
                arrIdElementos.push(arrInput[i].value);
            }
        }

        if (arrIdElementos.length > 0) {
            var url = "../common/get_finalizar_visitas_multiple.php";
            var ajax = objetoAjax();
            ajax.open("POST", url, true);
            ajax.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");

            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 1) {
                                showDialog(arr_aux[1], 1);
                            } else if (arr_aux[0] == 2) {
                                showDialog(arr_aux[1], 2);
                                flag_echar = true;
                            } else {
                                showDialog(arr_aux[1]);
                                irAContenido(menu_activo, menu_opcion, submenu_opcion);
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404, 1);
                        esperaRespuesta(false);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status, 1);
                        esperaRespuesta(false);
                    }
                }
            };

            ajax.send("ids=" + btoa(JSON.stringify(arrIdElementos)));
            esperaRespuesta(true);

            // Reset arrays and UI
            arrIdElementos = new Array();
            idSeleccionadas = new Array();
            toggleAccionMultiple(null);
        } else {
            showDialog("Por favor, seleccione al menos una visita para finalizar");
        }
    } else {
        showDialog(invalidOption);
    }
}

