/**
 * Funcion que guarda un nuevo documento de contrata
 *
 */
function guardaDocContrata(menu_opcion, submenu_opcion) {
    if (!isNaN(menu_opcion) && menu_opcion >= 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var formulario = document.getElementById("nuevo_elemento");
        var longitudFormulario = formulario.elements.length;
        var formData = new FormData();
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        var re = /^\w+$/;
        //var re2 = /(?=.*\d)(?=.*[a-z])(?=.*[A-Z]).{6,}/;
        for (var i = 0; i <= (longitudFormulario - 1); i++) {
            if (formulario.elements[i].required == true && formulario.elements[i].value == "") {
                showDialog(mensaje_faltan_campos);
                formulario.elements[i].classList.add("requerido");
                return false;
            } else if (formulario.elements[i].name == "name" && !re.test(formulario.elements[i].value)) {
                showDialog(formulario.elements[i].name + mensaje_error_caracteres);
                return false;
            }
            if (formulario.elements[i].type != 'file') {
                if (formulario.elements[i].type == "checkbox") {
                    if (formulario.elements[i].checked == true) {
                        formData.append(formulario.elements[i].name, formulario.elements[i].value);
                    }
                } else {
                    formData.append(formulario.elements[i].name, formulario.elements[i].value);
                }
            } else if (formulario.elements[i].value != '') {
                var files = formulario.elements[i].files;
                formData.append(formulario.elements[i].name, files[0], files[0].name);
            }
        }
        var url = "";
        var ajax = objetoAjax();;
        url = "../common/save_documento_contratas.php";
        ajax.open("POST", url, true);
        //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            showDialog(arr_aux[1]);
                            if (menu_opcion == 0 && submenu_opcion == 0) {
                                window.location.reload();
                            } else {
                                irAContenido(menu_activo, menu_opcion, submenu_opcion);
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion que comprueba si una empresa es autonomo
 *
 */
function checkAutonomo(selectBox) {
    if (selectBox != null) {
        var idEmpresas = selectBox.options[selectBox.selectedIndex].value;
        if (idEmpresas != "") {
            var url = "";
            var ajax = objetoAjax();;
            url = "../common/chequea_autonomo.php?id=" + idEmpresas;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);

                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                var flagAutonomo = jsonData.autonomo;
                                if (flagAutonomo == true) {
                                    var arrAutonomos = document.getElementsByClassName('conjuntos_autonomos');
                                    for (var i = 0; i < arrAutonomos.length; i++) {
                                        arrAutonomos[i].style.display = "block";
                                    }
                                    var arrEmpresa = document.getElementsByClassName('conjuntos_empresa');
                                    for (var i = 0; i < arrEmpresa.length; i++) {
                                        arrEmpresa[i].style.display = "none";
                                    }
                                    var arrEmpleados = document.getElementsByClassName('conjuntos_empleados');
                                    for (var i = 0; i < arrEmpleados.length; i++) {
                                        arrEmpleados[i].style.display = "none";
                                    }
                                } else {
                                    var arrAutonomos = document.getElementsByClassName('conjuntos_autonomos');
                                    for (var i = 0; i < arrAutonomos.length; i++) {
                                        arrAutonomos[i].style.display = "none";
                                    }
                                    var arrEmpresa = document.getElementsByClassName('conjuntos_empresa');
                                    for (var i = 0; i < arrEmpresa.length; i++) {
                                        arrEmpresa[i].style.display = "block";
                                    }
                                    var arrEmpleados = document.getElementsByClassName('conjuntos_empleados');
                                    for (var i = 0; i < arrEmpleados.length; i++) {
                                        arrEmpleados[i].style.display = "block";
                                    }
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}

/**
* Funcion que comprueba los modelos de documentos compliance de una empresa
*
*/
function checkModelosCompliance(menu_opcion, submenu_opcion, selectBox) {
    if (selectBox != null) {
        var idEmpresas = selectBox.options[selectBox.selectedIndex].value;
        if (idEmpresas != "") {
            var url = "";
            var ajax = objetoAjax();;
            url = "../common/chequea_modelos_compliance.php?op=" + menu_opcion + "&sub=" + submenu_opcion + "&id=" + idEmpresas;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);

                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                var arrModelos = jsonData.modelos;
                                var cajaModelos = document.getElementById('documentos_compliance_set');
                                cajaModelos.innerHTML = "";
                                //Escribimos la fila
                                var cajaFilaH = document.createElement("div");
                                cajaFilaH.className = "conjuntos_documentos_fila";
                                var cajaCelda1H = document.createElement("div");
                                cajaCelda1H.className = "conjuntos_documentos_celda";
                                var label1 = document.createElement("label");
                                label1.innerHTML = "&nbsp;"
                                var cajaCelda2H = document.createElement("div");
                                cajaCelda2H.className = "conjuntos_documentos_celda";
                                var label2 = document.createElement("label");
                                label2.innerHTML = documento;
                                label2.className = "titulo force";

                                cajaCelda1H.appendChild(label1);
                                cajaCelda2H.appendChild(label2);
                                cajaFilaH.appendChild(cajaCelda1H);
                                cajaFilaH.appendChild(cajaCelda2H);

                                cajaModelos.appendChild(cajaFilaH);

                                for (var i = 0; i < arrModelos.length; i++) {
                                    //Para cada modelo escribimos una linea
                                    var cajaFila = document.createElement("div");
                                    cajaFila.className = "conjuntos_documentos_fila";
                                    var cajaCelda1 = document.createElement("div");
                                    cajaCelda1.className = "conjuntos_documentos_celda";
                                    var checkBx = document.createElement("input");
                                    checkBx.type = "checkbox"
                                    checkBx.name = "documentos_compliance_modelos[]";
                                    checkBx.id = "documentos_compliance_modelos";
                                    checkBx.value = arrModelos[i].id;
                                    cajaCelda1.appendChild(checkBx);
                                    cajaFila.appendChild(cajaCelda1);

                                    var cajaCelda2 = document.createElement("div");
                                    cajaCelda2.className = "conjuntos_documentos_celda";
                                    var labelNombre = document.createElement("label");
                                    labelNombre.innerHTML = arrModelos[i].nombre;
                                    cajaCelda2.appendChild(labelNombre);
                                    cajaFila.appendChild(cajaCelda2);

                                    cajaModelos.appendChild(cajaFila);

                                }


                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}


