/**
 * Funcion que cambia el rango de Estadisticas de fichajes
 *
 */
function cambiaRangoEstadisticas(menu_opcion, submenu_opcion, rangoEstadisticas, accion, idElemento) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && !isNaN(rangoEstadisticas)) {
        var formData = new FormData();
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        formData.append('rango', rangoEstadisticas);

        var url = "";
        var ajax = objetoAjax();;
        url = "../common/cambia_rango_estadisticas.php";
        ajax.open("POST", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        if (jsonData.estado == 1) {
                            showDialog(jsonData.mensaje);
                            return;
                        } else if (jsonData.estado == 2) {
                            showDialog(jsonData.mensaje);
                            flag_echar = true;
                        } else {
                            if (accion == accionLista) {
                                irAContenido(menu_activo, menu_opcion, submenu_opcion);
                            } else if (accion == accionFormulario) {
                                nuevoElemento(menu_opcion, submenu_opcion, null);
                            } else if (accion == accionEdicion) {
                                editaElemento(menu_opcion, submenu_opcion, idElemento);
                            } else if (accion == accionVista) {
                                verElemento(menu_opcion, submenu_opcion, idElemento);
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                    esperaRespuesta(false);
                }
                else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                    esperaRespuesta(false);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
    }
}

/**
 * Funcion que cambia el rango de Estadisticas de Bolsa pleno
 *
 */
function cambiaRangoEstadisticasPleno(menu_opcion, submenu_opcion, rangoEstadisticas, accion, idElemento) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && !isNaN(rangoEstadisticas)) {
        var formData = new FormData();
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        formData.append('rango', rangoEstadisticas);

        var url = "";
        var ajax = objetoAjax();;
        url = "../common/cambia_rango_estadisticas_pleno.php";
        ajax.open("POST", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        if (jsonData.estado == 1) {
                            showDialog(jsonData.mensaje);
                            return;
                        } else if (jsonData.estado == 2) {
                            showDialog(jsonData.mensaje);
                            flag_echar = true;
                        } else {
                            if (accion == accionLista) {
                                irAContenido(menu_activo, menu_opcion, submenu_opcion);
                            } else if (accion == accionFormulario) {
                                nuevoElemento(menu_opcion, submenu_opcion, null);
                            } else if (accion == accionEdicion) {
                                editaElemento(menu_opcion, submenu_opcion, idElemento);
                            } else if (accion == accionVista) {
                                verElemento(menu_opcion, submenu_opcion, idElemento);
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                    esperaRespuesta(false);
                }
                else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                    esperaRespuesta(false);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
    }
}

