/**
 * Funcion que gestion el archivado de los datos de facturación
 *
 */
function archivarValoresMaximos(menu_opcion, submenu_opcion, idEmpresas) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= 14 && !isNaN(submenu_opcion) && !isNaN(idEmpresas)) {

        var url = "";
        var ajax = objetoAjax();
        url = "../common/archiva_valores_maximos.php?id=" + idEmpresas;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                showDialog(jsonData.mensaje);
                                limpiarFiltros(menu_opcion, submenu_opcion, accionLista, null);
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        ajax.send(null);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}

