/**
 * Funcion visualizar la informacion por cada turnos
 *
 */


function visualizarTurnos(opcion) {

    var resultado = opcion.value;

    console.log(":0");

    var c = 0;
    for (i = resultado; i <= 12; i++) {
        if (i > resultado) {
            document.getElementById("turno" + i).removeAttribute("style");
            document.getElementById("turno" + i).style.display = "none";
            document.getElementById("nombre-Turno" + i).removeAttribute("required");
            document.getElementById("acronimo-Turno" + i).removeAttribute("required");

            for (j = 1; j <= 3; j++) {//tramos
                for (k = 0; k <= 6; k++) {//dias
                    if (document.getElementById("inicio_tramo_" + j + "-" + k + "-" + "Turno" + i) !== 'undefined') {
                        document.getElementById("inicio_tramo_" + j + "-" + k + "-" + "Turno" + i).value = '';
                    }
                    if (document.getElementById("fin_tramo_" + j + "-" + k + "-" + "Turno" + i) !== 'undefined') {
                        document.getElementById("fin_tramo_" + j + "-" + k + "-" + "Turno" + i).value = '';
                    }
                    if (document.getElementById("flex_inicio_" + j + "-" + k + "-" + "Turno" + i) !== 'undefined') {
                        document.getElementById("flex_inicio_" + j + "-" + k + "-" + "Turno" + i).checked = false;
                    }
                    if (document.getElementById("flex_fin_" + j + "-" + k + "-" + "Turno" + i) !== 'undefined') {
                        document.getElementById("flex_fin_" + j + "-" + k + "-" + "Turno" + i).checked = false;
                    }
                    if (document.getElementById("tramo_comida-" + k + "-" + "Turno" + i) !== 'undefined') {
                        document.getElementById("tramo_comida-" + k + "-" + "Turno" + i).value = '';
                    }
                    if (document.getElementById("total_dia-" + k + "-" + i) !== 'undefined') {
                        document.getElementById("total_dia-" + k + "-" + i).innerHTML = '';
                    }
                }
            }
        }
    }

    for (j = 1; j <= resultado; j++) {
        document.getElementById("turno" + j).removeAttribute("style");
        document.getElementById("turno" + j).style.display = "block";
        document.getElementById("nombre-Turno" + j).setAttribute("required", "");
        document.getElementById("acronimo-Turno" + j).setAttribute("required", "");
    }

    document.getElementById("turnos_revision").value = resultado;
}

