function detectarFechaFinMenor(e) {

    if (document.getElementById("fecha_inicio").value != null) {
        if (document.getElementById("fecha_inicio").value != "") {
            $fecha_inicio_array = document.getElementById("fecha_inicio").value.split("-");
            $fecha_inicio_day = parseInt($fecha_inicio_array[0]);
            $fecha_inicio_month = parseInt($fecha_inicio_array[1]);
            $fecha_inicio_year = parseInt($fecha_inicio_array[2]);
        }
    }
    if (e.value != "") {
        $fecha_fin_array = e.value.split("-");
        $fecha_fin_day = parseInt($fecha_fin_array[0]);
        $fecha_fin_month = parseInt($fecha_fin_array[1]);
        $fecha_fin_year = parseInt($fecha_fin_array[2]);
    }
    if ($fecha_inicio_day > 0) {
        if ($fecha_fin_year < $fecha_inicio_year) {
            document.getElementById("fecha_fin").value = document.getElementById("fecha_inicio").value;
        } else if ($fecha_fin_month < $fecha_inicio_month) {
            document.getElementById("fecha_fin").value = document.getElementById("fecha_inicio").value;
        } else if ($fecha_fin_day < $fecha_inicio_day) {
            document.getElementById("fecha_fin").value = document.getElementById("fecha_inicio").value;
        }
    }
}

/**
 * Funcion que genera los meses para el calendario mensual -JJG
 *
 */
function generadorMes(month = 0, direction = 0, element = null, flag_modulo_nuevo = null) {

    //validamos si pasamos el elemento
    if (element != null && element != 'undefined') {
        id = element.id;
    } else {
        var id = "";
    }

    //creamos el calendario
    var size = screen.height;
    var url = "";
    var ajax = objetoAjax();
    url = "../common/generador_mes_calendario.php?month=" + month + "&direction=" + direction + "&size=" + size + "&id=" + id + "&flag_modulo_nuevo=" + flag_modulo_nuevo;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);
                    if (jsonData.estado == 2) {
                        showDialog(jsonData.mensaje);
                        flag_echar = true;
                    } else {
                        if (jsonData.estado == 0) {
                            var calendar = document.getElementById('calendar-wrap');
                            calendar.innerHTML = jsonData.html;
                            monthPaintedSelection(month, jsonData.year, jsonData.id);
                        }
                    }
                } else {
                    alert("Error al llamar a la funcion generadora del mes");
                }
            } else if (ajax.status == 404) {
                alert(error404);
            } else if (ajax.status != 0) {
                alert("Error:" + ajax.status);
            }
        }
    };
    esperaRespuesta(true);
    ajax.send(null);
}

