/**
 * Funcion que pinta seleccion de los meses
 *
 */
function monthPaintedSelection(month, year, id) {
    if (id != "") {
        var clean_id = id.split("_");
        var num_id = parseInt(clean_id[1]);

        /** #CASO -seleccion por rango*/
        if (document.getElementById("calendar-wrap").dataset.selection_type == 0) {
            if (clean_id[0] == "next") {

                //#CASO
                console.log("1->");
                document.getElementById("calendar-wrap").dataset.final_day = clean_id[1];
                document.getElementById("calendar-wrap").dataset.final_month = month;
                document.getElementById("calendar-wrap").dataset.final_year = year;
                document.getElementById('day_' + num_id).dataset.status = "selected";
            } else if (parseInt(document.getElementById("calendar-wrap").dataset.initial_day) == 0 && clean_id[0] == "before") {

                //#CASO
                console.log("<-2");
                document.getElementById("calendar-wrap").dataset.initial_day = clean_id[1];
                document.getElementById("calendar-wrap").dataset.initial_month = month;
                document.getElementById("calendar-wrap").dataset.initial_year = year;

                //me aseguro de limpiar
                document.getElementById("calendar-wrap").dataset.final_day = 0;
                document.getElementById("calendar-wrap").dataset.final_month = 0;
                document.getElementById("calendar-wrap").dataset.final_year = 0;

                document.getElementById('day_' + num_id).dataset.status = "selected";
                alert("no esta permitido seleccionar fecha anteriores");
            } else if (clean_id[0] == "before") {

                //#CASO
                console.log("<-1");
                document.getElementById("calendar-wrap").dataset.initial_day = clean_id[1];
                document.getElementById("calendar-wrap").dataset.initial_month = month;
                document.getElementById("calendar-wrap").dataset.initial_year = year;

                //me aseguro de limpiar
                document.getElementById("calendar-wrap").dataset.final_day = 0;
                document.getElementById("calendar-wrap").dataset.final_month = 0;
                document.getElementById("calendar-wrap").dataset.final_year = 0;

                document.getElementById('day_' + num_id).dataset.status = "selected";
                alert("no esta permitido seleccionar fecha anteriores");
            }
        }
    }

    /** #CASO -seleccion por rango*/
    if (document.getElementById("calendar-wrap").dataset.selection_type == 0) {

        //verifico si existen los datos
        if (document.getElementById("calendar-wrap").dataset.initial_month != 0 &&
            document.getElementById("calendar-wrap").dataset.final_month != 0 &&
            document.getElementById("calendar-wrap").dataset.initial_year != 0 &&
            document.getElementById("calendar-wrap").dataset.final_year != 0) {

            /*** A-- DENTRO DEL MISMO AÑO */
            if (parseInt(document.getElementById("calendar-wrap").dataset.initial_year) == parseInt(document.getElementById("calendar-wrap").dataset.final_year)) {

                /*** 1-- si existe ya una seleccion se de fecha de inicio de un mes anterior y fin de un mes siguiente */
                if (parseInt(document.getElementById("calendar-wrap").dataset.initial_month) < month &&
                    parseInt(document.getElementById("calendar-wrap").dataset.final_month) > month) {

                    //#CASO
                    console.log("1A");

                    //pintamos todas las casillas del mes
                    for (var i = 1; i < 31; i++) {
                        if (document.getElementById('day_' + i) != 'undefined' && document.getElementById('day_' + i) != null) {
                            if (document.getElementById('day_' + i).dataset.year == year) {
                                document.getElementById('day_' + i).dataset.status = "selected";
                                document.getElementById('day_' + i).dataset.type = "days_range";
                            }
                        }
                    }
                }

                /*** 2-- si la fecha de inicio es de un mes anterior y la fecha de fin es del mes */
                if (parseInt(document.getElementById("calendar-wrap").dataset.initial_month) < month &&
                    parseInt(document.getElementById("calendar-wrap").dataset.final_month) == month) {

                    //#CASO
                    console.log("2A");

                    //seleccionamos
                    document.getElementById('day_' + parseInt(document.getElementById("calendar-wrap").dataset.final_day)).dataset.status = "selected";

                    //pinto la flecha final
                    document.getElementById('day_' + parseInt(document.getElementById("calendar-wrap").dataset.final_day)).dataset.type = "final_selected";

                    //pintamos las casillas del medio
                    for (var i = 1; i < parseInt(document.getElementById("calendar-wrap").dataset.final_day); i++) {
                        if (document.getElementById('day_' + i).dataset.year == year) {
                            document.getElementById('day_' + i).dataset.status = "selected";
                            document.getElementById('day_' + i).dataset.type = "days_range";
                        }
                    }
                }

                /*** 3-- si la fecha de inicio es del mes y la fecha de fin es del proximo mes */
                if (parseInt(document.getElementById("calendar-wrap").dataset.initial_month) == month &&
                    parseInt(document.getElementById("calendar-wrap").dataset.final_month) > month) {

                    //#CASO
                    console.log("3A");
                    //seleccionamos
                    document.getElementById('day_' + parseInt(document.getElementById("calendar-wrap").dataset.initial_day)).dataset.status = "selected";

                    //pinto la flecha inicial
                    document.getElementById('day_' + parseInt(document.getElementById("calendar-wrap").dataset.initial_day)).dataset.type = "initial_selected";

                    //pintamos las casillas del medio

                    //creamos una variable que incia a partir del dia sieguiente
                    var aux = parseInt(document.getElementById("calendar-wrap").dataset.initial_day) + 1;

                    for (var i = aux; i <= 31; i++) {
                        if (document.getElementById('day_' + i) != 'undefined' && document.getElementById('day_' + i) != null) {
                            console.log(document.getElementById('day_' + i).dataset.year);
                            if (document.getElementById('day_' + i).dataset.year == year) {
                                document.getElementById('day_' + i).dataset.status = "selected";
                                document.getElementById('day_' + i).dataset.type = "days_range";
                            }
                        }
                    }
                }

                /*** 4--si la fecha de inicio y fin es dentro del mismo mes */
                if (parseInt(document.getElementById("calendar-wrap").dataset.initial_month) == month &&
                    parseInt(document.getElementById("calendar-wrap").dataset.final_month) == month) {

                    //#CASO
                    console.log("4A");
                    //seleccionamos
                    document.getElementById('day_' + parseInt(document.getElementById("calendar-wrap").dataset.initial_day)).dataset.status = "selected";
                    document.getElementById('day_' + parseInt(document.getElementById("calendar-wrap").dataset.final_day)).dataset.status = "selected";

                    //pinto la flecha inicial
                    document.getElementById('day_' + parseInt(document.getElementById("calendar-wrap").dataset.initial_day)).dataset.type = "initial_selected";
                    //pinto la flecha final
                    document.getElementById('day_' + parseInt(document.getElementById("calendar-wrap").dataset.final_day)).dataset.type = "final_selected";

                    //pintamos las casillas del medio

                    //creamos una variable que incia a partir del dia sieguiente
                    var aux = parseInt(document.getElementById("calendar-wrap").dataset.initial_day) + 1;
                    for (var i = aux; i < parseInt(document.getElementById("calendar-wrap").dataset.final_day); i++) {
                        if (document.getElementById('day_' + i).dataset.year == year) {
                            document.getElementById('day_' + i).dataset.status = "selected";
                            document.getElementById('day_' + i).dataset.type = "days_range";
                        }
                    }
                }

                /*** B-- DE UN AÑO ANTERIOR A UNO SIGUIENTE */
            } else if (parseInt(document.getElementById("calendar-wrap").dataset.initial_year) < parseInt(document.getElementById("calendar-wrap").dataset.final_year)) {

                /*** 1-- si la seleccion es de un año menor al actual para un mayor*/
                if (parseInt(year) < parseInt(document.getElementById("calendar-wrap").dataset.final_year) &&
                    parseInt(year) > parseInt(document.getElementById("calendar-wrap").dataset.initial_year)) {

                    //#CASO
                    console.log("1B");
                    //pintamos todas las casillas del mes
                    for (var i = 1; i <= 31; i++) {
                        if (document.getElementById('day_' + i) != 'undefined' && document.getElementById('day_' + i) != null) {
                            document.getElementById('day_' + i).dataset.status = "selected";
                            document.getElementById('day_' + i).dataset.type = "days_range";
                        }
                    }

                    /*** 2-- si la fecha de fin esta dentro del año*/
                } else if (parseInt(year) == parseInt(document.getElementById("calendar-wrap").dataset.final_year) &&
                    parseInt(year) > parseInt(document.getElementById("calendar-wrap").dataset.initial_year)) {

                    //2.1-- si el mes continiene la fecha fin
                    if (month == parseInt(document.getElementById("calendar-wrap").dataset.final_month)) {

                        //#CASO
                        console.log("2.1B");

                        console.log(document.getElementById('day_' + parseInt(document.getElementById("calendar-wrap").dataset.final_day)));

                        //seleccionamos
                        document.getElementById('day_' + parseInt(document.getElementById("calendar-wrap").dataset.final_day)).dataset.status = "selected";

                        //pinto la flecha final
                        document.getElementById('day_' + parseInt(document.getElementById("calendar-wrap").dataset.final_day)).dataset.type = "final_selected";

                        //pintamos las casillas del medio
                        for (var i = 1; i < parseInt(document.getElementById("calendar-wrap").dataset.final_day); i++) {
                            document.getElementById('day_' + i).dataset.status = "selected";
                            document.getElementById('day_' + i).dataset.type = "days_range";
                        }

                        //2.2-- si el mes es menor al que contiene la fecha fin
                    } else if (month < parseInt(document.getElementById("calendar-wrap").dataset.final_month)) {

                        //#CASO
                        console.log("2.2B");
                        //pintamos todas las casillas del mes
                        for (var i = 1; i <= 31; i++) {
                            if (document.getElementById('day_' + i) != 'undefined' && document.getElementById('day_' + i) != null) {
                                document.getElementById('day_' + i).dataset.status = "selected";
                                document.getElementById('day_' + i).dataset.type = "days_range";
                            }
                        }
                    }
                    /*** 3-- si nos posicionamos en el mes inicial*/
                } else if (parseInt(year) < parseInt(document.getElementById("calendar-wrap").dataset.final_year) &&
                    parseInt(year) == parseInt(document.getElementById("calendar-wrap").dataset.initial_year)) {

                    //3.1-- si el mes continiene la fecha fin
                    if (month == parseInt(document.getElementById("calendar-wrap").dataset.initial_month)) {

                        //#CASO
                        console.log("3.1B");
                        //seleccionamos
                        document.getElementById('day_' + parseInt(document.getElementById("calendar-wrap").dataset.initial_day)).dataset.status = "selected";

                        //pinto la flecha final
                        document.getElementById('day_' + parseInt(document.getElementById("calendar-wrap").dataset.initial_day)).dataset.type = "initial_selected";

                        //creamos una variable que incia a partir del dia sieguiente
                        var aux = parseInt(document.getElementById("calendar-wrap").dataset.initial_day) + 1;
                        //pintamos las casillas del medio
                        for (var i = aux; i <= 31; i++) {
                            if (document.getElementById('day_' + i) != 'undefined' && document.getElementById('day_' + i) != null) {
                                document.getElementById('day_' + i).dataset.status = "selected";
                                document.getElementById('day_' + i).dataset.type = "days_range";
                            }
                        }

                        //3.2-- si el mes es menor al que contiene la fecha fin
                    } else if (month > parseInt(document.getElementById("calendar-wrap").dataset.initial_month)) {

                        //#CASO
                        console.log("3.2B");
                        //pintamos todas las casillas del mes
                        for (var i = 1; i <= 31; i++) {
                            if (document.getElementById('day_' + i) != 'undefined' && document.getElementById('day_' + i) != null) {
                                document.getElementById('day_' + i).dataset.status = "selected";
                                document.getElementById('day_' + i).dataset.type = "days_range";
                            }
                        }
                    }
                }
            }
        }

        /** #CASO -seleccion simple*/
    } else {
        //creamos un array con las selecciones realizadas y el tamaño
        var array_dates = document.getElementById("calendar-wrap").dataset.selected_dates.split(",");
        var num_array_dates = array_dates.length;
        var clean_date = 0;

        //recorremos el array
        for (var i = 0; i < num_array_dates; i++) {
            //reiniciamos
            clean_date = 0;

            //1- separamos los elementos de la fecha
            clean_date = array_dates[i].split("-");

            //2- validamos que sea el mismo mes y año
            if (document.getElementById('day_' + parseInt(clean_date[2])) != null && document.getElementById('day_' + parseInt(clean_date[2])) != undefined) {
                if (document.getElementById('day_' + parseInt(clean_date[2])).dataset.month == parseInt(clean_date[1])) {
                    if (document.getElementById('day_' + parseInt(clean_date[2])).dataset.year == parseInt(clean_date[0])) {
                        //3- pintamos
                        document.getElementById('day_' + parseInt(clean_date[2])).dataset.status = "selected";
                        document.getElementById('day_' + parseInt(clean_date[2])).dataset.type = "only_day_selected";
                    }
                }
            }
        }
    }
}

/**
 * Funcion que chequea la eliminacion de las reservas
 *
 */
function chequeaEliminacionReserva(menu_opcion, submenu_opcion, nro_puestos, centro_id) {

    //validamos que existan los datos necesarios
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= 14 && !isNaN(submenu_opcion)
        && !isNaN(nro_puestos) && nro_puestos > 0 && !isNaN(centro_id)) {

        //tomamos la cantidad de puestos que se estan solicitando
        var nuevaCantidadPuestos = document.getElementById("nro_puestos").value;

        var url = "";
        var ajax = objetoAjax();
        url = "../common/chequeaEliminacionReserva.php?nro_puestos=" + nro_puestos + "&new_nro_puestos=" + nuevaCantidadPuestos + "&id_centros=" + centro_id;

        ajax.open("GET", url, true);

        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                if (jsonData.chequeo == 1) {
                                    showConfirm(jsonData.mensaje, guardaElemento, menu_opcion, submenu_opcion);
                                } else {
                                    guardaElemento(menu_opcion, submenu_opcion);
                                }
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        ajax.send(null);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion que da formato a las fechas
 *
 */
function formatoFecha(fecha, formato) {
    const map = {
        dd: fecha.getDate(),
        mm: fecha.getMonth() + 1,
        yy: fecha.getFullYear().toString().slice(-2),
        yyyy: fecha.getFullYear()
    }

    return formato.replace(/dd|mm|yy|yyy/gi, matched => map[matched])
}

/**
 * Funcion que recarga las rutas al cambiar de empresa en generacion de perfiles (Perfiles HARDWARE)
 *
 */
function reloadRutasPlanesAcceso(selectBox, menu_opcion, submenu_opcion) {
    if (selectBox != null) {
        var empresa_id = selectBox.options[selectBox.selectedIndex].value;


        if (empresa_id != "") {
            var url = "";
            var ajax = objetoAjax();;
            url = "../common/recarga_lista_rutas.php?id=" + empresa_id + "&op=" + menu_opcion + "&sub=" + submenu_opcion;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);

                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                var arr_rutas = jsonData.lista_rutas;
                                var tableBodyRutas = document.getElementById("listado");
                                var tableBodyRutasSel = document.getElementById("listadoseltd");

                                if (tableBodyRutas != null) {
                                    tableBodyRutas.innerHTML = "";
                                    for (var key in arr_rutas) {

                                        if (arr_rutas.hasOwnProperty(key) && /^0$|^[1-9]\d*$/.test(key) && key <= 4294967294) {

                                            var fila = document.createElement("tr");
                                            var celdaInput = document.createElement("td");
                                            var inputCheck = document.createElement("input");
                                            inputCheck.type = "checkbox";
                                            inputCheck.name = "ruta_id[]";
                                            inputCheck.value = arr_rutas[key]['id'];
                                            inputCheck.dataset.ruta = arr_rutas[key]['nombre'];
                                            inputCheck.onclick = function () {
                                                if (this.checked) {
                                                    //alert(this.value);
                                                    var spanRuta = document.createElement("p");
                                                    spanRuta.setAttribute("id", this.value + "span");
                                                    spanRuta.textContent = this.dataset.ruta;
                                                    tableBodyRutasSel.appendChild(spanRuta);
                                                } else {
                                                    var spanRuta = document.getElementById(this.value + "span");
                                                    spanRuta.parentNode.removeChild(spanRuta);
                                                }
                                            };
                                            celdaInput.appendChild(inputCheck);
                                            fila.appendChild(celdaInput);
                                            var celdaNombre = document.createElement("td");
                                            celdaNombre.innerHTML = arr_rutas[key]['nombre'];
                                            fila.appendChild(celdaNombre);
                                            tableBodyRutas.appendChild(fila);


                                        }
                                    }
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    }
                    else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion que chequea si una ruta se selecciona o se deselecciona para añadirla o quitarla de las rutas seleccionadas (Perfiles HARDWARE)
 *
 */
function checkRutasSeleccionadas(chksel) {
    //alert(chksel.value);
    var tableBodyRutasSel = document.getElementById("listadoseltd");
    if (chksel.checked) {

        var spanRuta = document.createElement("p");
        spanRuta.setAttribute("id", chksel.value + "span");
        spanRuta.textContent = chksel.dataset.ruta;
        tableBodyRutasSel.appendChild(spanRuta);
    } else {
        var spanRuta = document.getElementById(chksel.value + "span");
        spanRuta.parentNode.removeChild(spanRuta);
    }

}



/**
 * Sumar los valores de valores diarias para dar un valor semanal.
 *
 */
function sumarDiarioContrato() {
    const total = document.getElementById('horas_semanales');
    let subtotal = 0;
    [...document.getElementsByClassName("monto")].forEach(function (element) {
        if (element.value !== '') {
            subtotal += parseFloat(element.value);
        }
    });
    total.value = subtotal;
}

/**
 * Divide el valor de horas semanales a diferentes imputs L-D para contratos.
 *
 */
function dividirDiarioContrato() {
    var horas = document.getElementById('horas_semanales').value;
    var c1 = document.getElementById("flag_diarias_lunes").checked;
    var c2 = document.getElementById("flag_diarias_martes").checked;
    var c3 = document.getElementById("flag_diarias_miercoles").checked;
    var c4 = document.getElementById("flag_diarias_jueves").checked;
    var c5 = document.getElementById("flag_diarias_viernes").checked;
    var c6 = document.getElementById("flag_diarias_sabado").checked;
    var c7 = document.getElementById("flag_diarias_domingo").checked;

    let checkeboxes = [c1, c2, c3, c4, c5, c6, c7];
    var cont = 0;
    checkeboxes.forEach(function (chec, index) {
        if (chec == true) {
            cont = cont + 1;
        }
    });


    var valorhoras = Math.round(horas / cont);

    if (c1 == true) {
        document.getElementById("diarias_lunes").value = valorhoras;
    } else {
        document.getElementById("diarias_lunes").value = "";
    }
    if (c2 == true) {
        document.getElementById("diarias_martes").value = valorhoras;
    } else {
        document.getElementById("diarias_martes").value = "";
    }
    if (c3 == true) {
        document.getElementById("diarias_miercoles").value = valorhoras;
    } else {
        document.getElementById("diarias_miercoles").value = "";
    }
    if (c4 == true) {
        document.getElementById("diarias_jueves").value = valorhoras;
    } else {
        document.getElementById("diarias_jueves").value = "";
    }
    if (c5 == true) {
        document.getElementById("diarias_viernes").value = valorhoras;
    } else {
        document.getElementById("diarias_viernes").value = "";
    }
    if (c6 == true) {
        document.getElementById("diarias_sabado").value = valorhoras;
    } else {
        document.getElementById("diarias_sabado").value = "";
    }
    if (c7 == true) {
        document.getElementById("diarias_domingo").value = valorhoras;
    } else {
        document.getElementById("diarias_domingo").value = "";
    }
}

/**
 * Divide el valor de horas anules para saber cuantas son mensuales
 *
 */
function dividirHorasAnuales() {
    var horas = document.getElementById('horas_anuales').value;
    var valorhoras = Math.round(horas / 12);
    var horas_sobrantes = (valorhoras * 12);
    var horas_restante = horas - horas_sobrantes

    document.getElementById("horas_enero").value = valorhoras;
    document.getElementById("horas_febrero").value = valorhoras;
    document.getElementById("horas_marzo").value = valorhoras;
    document.getElementById("horas_abril").value = valorhoras;
    document.getElementById("horas_mayo").value = valorhoras;
    document.getElementById("horas_junio").value = valorhoras;
    document.getElementById("horas_julio").value = valorhoras;
    document.getElementById("horas_agosto").value = valorhoras;
    document.getElementById("horas_septiembre").value = valorhoras;
    document.getElementById("horas_octubre").value = valorhoras;
    document.getElementById("horas_noviembre").value = valorhoras;
    document.getElementById("horas_diciembre").value = valorhoras + horas_restante;

}

