/**
 * Funcion para detectar el Url del seguimiento de reglas
 *
 */
function detectarUrl(e) {
    var element = e;
    e.value = "";

    var input_url_ce = "";
    var input_url_em = "";
    var url = "";
    var ajax = objetoAjax();

    url = "../common/obtener_url_seguimiento.php";
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {

        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                var html_txt = ajax.responseText;

                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);

                    if (jsonData.estado == 1) {
                        showDialog(jsonData.mensaje);
                        return;
                    } else if (jsonData.estado == 2) {
                        showDialog(jsonData.mensaje);
                        flag_echar = true;
                    } else {
                        if (jsonData.id != 0) {
                            input_url_ce = document.getElementById("url_seguimiento_centro");
                            input_url_em = document.getElementById("url_seguimiento_empleado");
                            if (jsonData.url != "") {
                                if (input_url_ce != null) {
                                    input_url_ce.value = jsonData.url;
                                } else if (input_url_em != null) {
                                    input_url_em.value = jsonData.url;
                                }
                            } else {
                                console.log("empty-url");
                            }
                        }
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            } else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status);
            }
        }
    };
    ajax.send(null);
}

