/**
 * Funcion que muestra un elemento detallado ya sea app como web pasando el objeto que deseamos.
 *
 */
function verElementoDetallado(menu_opcion, submenu_opcion, nombre) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && nombre != "") {
        var url = "";
        var ajax = objetoAjax();
        url = "../common/set_detalle_seguimiento.php?nombre=" + nombre;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            numeroPagina = 1;
                            irAContenido(menu_activo, menu_opcion, submenu_opcion);
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                }
                else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        ajax.send(null);
    }
}

/**
 * 
 * JJG
 */
function seguimientosDetallados(menu_opcion, submenu_opcion, objeto = "", tipo = "", fecha = "", empleado = "") {
    var url = "";
    var ajax = objetoAjax();
    url = "../common/set_espacio_caracteristicas.php?objeto=" + objeto + "&tipo=" + tipo + "&fecha=" + fecha + "&id_empleado=" + empleado;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var arr_aux = html_txt.split("|");
                    if (arr_aux[0] == 1) {
                    } else if (arr_aux[0] == 2) {
                        showDialog(arr_aux[1]);
                        flag_echar = true;
                    } else {
                        irAContenido(menu_activo, menu_opcion, submenu_opcion);
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            }
            else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status);
            }
        }
    };
    ajax.send(null);
    esperaRespuesta(true);
}

