/**
 * Funcion para la captacion del click en un plano para trabajarlo
 *
 */
function detectarClickPlano(event, element, id = 0, tipo = 0, cardinalidad = 0) {

    //inicializacion

    //vemos el tipo de elemento
    var acronimo_tipo = "";

    if (tipo == 1) {
        //puestos físicos
        acronimo_tipo = "pfi";
    } else if (tipo == 2) {
        //salas o espacios físicos
        acronimo_tipo = "esp";
    } else if (tipo == 3) {
        //plazas de parking
        acronimo_tipo = "prk";
    }

    //variable aux para traernos los elementos ya presentes en el div
    var elementosPresentes = "";

    //variables para tomar el ancho y el alto del mousemove
    var x = 0;
    var y = 0;

    //ancho y alto final y ya calibrado
    var eje_y = 0;
    var eje_x = 0;

    //variable que indica que puede ir tomando los valores con el mousemove
    var mouse_down = true;

    //variable aux display para ocultar el div cuando lo requeriremos
    var display = "";
    var flg_hidden = 0;

    /**NOTA: esta variable cubre 30px sumados de margins y padding sumados de elementos posteriores*/
    var calibrador_extra_css_elements = 30;

    elementosPresentes = document.getElementById("mapeo_plano").innerHTML;

    var eje_x = 0;
    var eje_y = 0;

    /** espacios*/
    if (acronimo_tipo == "esp" || acronimo_tipo == "prk") {

        //inicializamos con estos datos las coordenadas
        var x_inicial = event.offsetX;
        var x_final = event.offsetX;
        var y_inicial = event.offsetY;
        var y_final = event.offsetY;

        var y_inicial_aux = y_inicial;
        var extra_elements = ((document.getElementById("botonera_planos").offsetTop + document.getElementById("titulo_planos").offsetTop) + calibrador_extra_css_elements);

        //pintamos el sombreado en el plano
        var area = document.getElementById('area_seleccion_plano');

        //varibles para definir si mostrar el aera de seleccion o no
        area.hidden = true;
        mouse_down = true;

        //definimos el area
        area.style.position = "absolute";
        area.style.backgroundColor = "#4f8eb3ab";

        //si detectamos la posicion del evento
        if (event.offsetX > 0 && event.offsetY > 0) {

            if (flg_hidden == 0) {
                //definimos que ha tomado datos
                area.hidden = false;
            } else {
                area.hidden = true;
            }

            //tomamos los datos al mover el mouse
            $("#img_cargada").bind("mousemove", function (e) {

                //variable de control para visualizar que estamos tomando datos en esta funcion
                console.log(0);

                //mientras no se ha realizado el segundo click vamos tomando datos
                if (mouse_down) {


                    if (document.getElementById('draw_cod_link_' + acronimo_tipo + '_' + id) != null) {
                        document.getElementById('draw_cod_link_' + acronimo_tipo + '_' + id).style.display = "none";
                    }

                    //vamos tomando la posicion final en el eje (x) y (y)
                    x_final = e.offsetX;
                    y_final = e.offsetY;

                    if (x_final != x_inicial) {
                        var calculo_x = Math.min(x_inicial, x_final) + document.getElementById("botonera_planos").offsetLeft;
                        area.style.left = calculo_x + "px";
                        area.style.width = Math.max(x_inicial, x_final) - Math.min(x_inicial, x_final) + "px";
                        if (flg_hidden == 1) {
                            flg_hidden = 0;
                        }
                    }

                    if (y_final != y_inicial) {
                        var calculo_y = Math.min(y_inicial, y_final) + ((document.getElementById("botonera_planos").offsetTop + document.getElementById("titulo_planos").offsetTop) + calibrador_extra_css_elements);
                        area.style.top = calculo_y + "px";
                        area.style.height = Math.max(y_inicial, y_final) - Math.min(y_inicial, y_final) + "px";
                        if (flg_hidden == 1) {
                            flg_hidden = 0;
                        }
                    }
                }
            });
        }

        $("#img_cargada").bind("mouseup", function (e) {

            //variable de control para visualizar que estamos tomando datos en esta funcion
            console.log(1);

            area.hidden = true;
            mouse_down = false;

            x_final = e.pageX;

            // calculamos el ancho y el alto
            if (y_final > y_inicial) {

                y = y_final - y_inicial;
                x = (x_final - x_inicial);

                if (x < 0) {
                    x = x * (-1);
                }
            }

            if (x_inicial != 0 && x_final != 0) {
                if (x_inicial > x_final) {
                    eje_x = x + document.getElementById("botonera_planos").offsetLeft - 5;
                    x_inicial = x_inicial - eje_x - 5;
                } else {
                    eje_x = x - document.getElementById("botonera_planos").offsetLeft - 5;
                    x_inicial = x_inicial - 2;
                }
            }

            if (y_inicial != 0 && y_final != 0) {
                if (y_inicial > y_final) {
                    eje_y = y;
                    y_inicial = y_inicial - eje_y - 2;
                } else {
                    eje_y = y - 5;
                    y_inicial = y_inicial + extra_elements;
                }
            }

            //invertir la selección
            if (x_inicial > x_final) {
                var temp = x_inicial;
                x_inicial = x_final;
                x_final = temp;
            }

            /*if(y_inicial > y_final){
                var temp = y_inicial;
                y_inicial = y_final;
                y_final = temp;
            }*/

            if (eje_y < 0 && eje_x < 0) {
                area.hidden = true;
                flg_hidden = 1;

                area.style.left = x_inicial + "px";
                area.style.width = 0 + "px";
                area.style.top = y_inicial + "px";
                area.style.height = 0 + "px";
            }

            //se agrega el div para la visualizacion
            if (document.getElementById(acronimo_tipo + '_' + id) == null) {

                if (acronimo_tipo != "esp" && acronimo_tipo != "prk" && acronimo_tipo != "pfi") {
                    display = "none";
                } else {
                    display = "block";
                }

                if (display == "") {
                    display = "block";
                }

                document.getElementById("mapeo_plano").innerHTML = elementosPresentes + '<div id="' + acronimo_tipo + '_' + id + '">' + '<div id="draw_cod_link_' + acronimo_tipo + '_' + id + '"  style="display:' + display + ';width: ' + eje_x + 'px; height: ' + eje_y + 'px; border: 3px solid #5889d6;position:absolute;border-top-left-radius: 20px;border-top-right-radius: 20px;top:' + y_inicial + 'px;left:' + x_inicial + 'px;-ms-transform: rotate(' + cardinalidad + 'deg); -webkit-transform: rotate(' + cardinalidad + 'deg); transform: rotate(' + cardinalidad + 'deg);"></div>' + '</div>';
            } else {
                if (display == "") {
                    display = "block";
                }

                if (acronimo_tipo == "esp" || acronimo_tipo == "prk") {
                    document.getElementById("pln_eje_x").value = eje_x;
                    document.getElementById("pln_eje_y").value = eje_y;
                    cardinalidad = 0;
                } else {
                    if (acronimo_tipo != "pfi") {
                        display = "none";
                    }
                }
                document.getElementById(acronimo_tipo + '_' + id).innerHTML = '<div id="draw_cod_link_' + acronimo_tipo + '_' + id + '" style="display:' + display + '; width: ' + eje_x + 'px; height: ' + eje_y + 'px; border: 3px solid #5889d6;position:absolute;border-top-left-radius: 20px;border-top-right-radius: 20px;top:' + y_inicial + 'px;left:' + x_inicial + 'px;-ms-transform: rotate(' + cardinalidad + 'deg); -webkit-transform: rotate(' + cardinalidad + 'deg); transform: rotate(' + cardinalidad + 'deg);"></div>';
            }
        });

        y_inicial_aux = y_inicial_aux + extra_elements;

        //guardamos con ajax las posiciones en una variable de session
        var url = "";
        var ajax = objetoAjax();
        url = "../common/set_posicion_elemento.php?pln_eje_y=" + y_inicial_aux + "&pln_eje_x=" + x_inicial;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    //esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            var jsonData = JSON.parse(html_txt);
                        }
                    } else {
                        alert("Error al llamar a la funcion que detecta la seleccion del calendario mensual");
                    }
                } else if (ajax.status == 404) {
                    alert(error404);
                } else if (ajax.status != 0) {
                    alert("Error:" + ajax.status);
                }
            }
        };
        ajax.send(null);
        //esperaRespuesta(true);

        /** puestos físicos*/
    } else {

        /**NOTA: meterle mano*/
        var calibrador_extra_css_elements = 30;
        x_inicial = event.offsetX;
        y_inicial = event.offsetY + (document.getElementById("botonera_planos").offsetTop + document.getElementById("titulo_planos").offsetTop) + calibrador_extra_css_elements;

        //seteamos el campo de ancho y alto
        if (document.getElementById("pln_eje_y") != null) {
            eje_y = document.getElementById("pln_eje_y").value;
            eje_x = document.getElementById("pln_eje_x").value;
        }

        x_inicial = x_inicial - (eje_x / 2);
        y_inicial = y_inicial - (eje_y / 2);

        if (x_inicial <= 0 || y_inicial <= (document.getElementById("botonera_planos").offsetTop + document.getElementById("titulo_planos").offsetTop) + calibrador_extra_css_elements + 20) {
            display = "none";
        }

        //se agrega el div para la visualizacion
        if (document.getElementById(acronimo_tipo + '_' + id) == null) {
            if (acronimo_tipo != "esp" && acronimo_tipo != "prk" && acronimo_tipo != "pfi") {
                display = "none";
            } else {
                display = "block";
            }

            if (display == "") {
                display = "block";
            }

            document.getElementById("mapeo_plano").innerHTML = elementosPresentes + '<div id="' + acronimo_tipo + '_' + id + '">' + '<div id="draw_cod_link_' + acronimo_tipo + '_' + id + '"  style="display:' + display + ';width: ' + eje_x + 'px; height: ' + eje_y + 'px; border: 3px solid #5889d6;position:absolute;border-top-left-radius: 20px;border-top-right-radius: 20px;top:' + y_inicial + 'px;left:' + x_inicial + 'px;-ms-transform: rotate(' + cardinalidad + 'deg); -webkit-transform: rotate(' + cardinalidad + 'deg); transform: rotate(' + cardinalidad + 'deg);"></div>' + '</div>';
        } else {
            if (display == "") {
                display = "block";
            }

            if (acronimo_tipo == "esp" || acronimo_tipo == "prk") {
                document.getElementById("pln_eje_x").value = eje_x;
                document.getElementById("pln_eje_y").value = eje_y;
                cardinalidad = 0;
            } else {
                if (acronimo_tipo != "pfi") {
                    display = "none";
                }
            }
            document.getElementById(acronimo_tipo + '_' + id).innerHTML = '<div id="draw_cod_link_' + acronimo_tipo + '_' + id + '" style="display:' + display + '; width: ' + eje_x + 'px; height: ' + eje_y + 'px; border: 3px solid #5889d6;position:absolute;border-top-left-radius: 20px;border-top-right-radius: 20px;top:' + y_inicial + 'px;left:' + x_inicial + 'px;-ms-transform: rotate(' + cardinalidad + 'deg); -webkit-transform: rotate(' + cardinalidad + 'deg); transform: rotate(' + cardinalidad + 'deg);"></div>';
        }

        //guardamos con ajax las posiciones en una variable de session
        var url = "";
        var ajax = objetoAjax();
        url = "../common/set_posicion_elemento.php?pln_eje_y=" + y_inicial + "&pln_eje_x=" + x_inicial;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            var jsonData = JSON.parse(html_txt);
                        }
                    } else {
                        alert("Error al llamar a la funcion que detecta la seleccion del calendario mensual");
                    }
                } else if (ajax.status == 404) {
                    alert(error404);
                } else if (ajax.status != 0) {
                    alert("Error:" + ajax.status);
                }
            }
        };
        ajax.send(null);
        esperaRespuesta(true);
    }
}

/**
 * Funcion Seleccion rango de horas par el registro de una reserva
 *
 */
function detectarRangoHoras(hora_fin = 0, hora_inicio = 0, menu_opcion = 0, submenu_opcion = 0, min_hr = 0, max_hr = 0) {
    var flag_horas_incongruentes = 0

    var inicio = hora_inicio.value;
    var fin = hora_fin.value;

    var hr_ini = inicio.split(':');
    var hr_fin = fin.split(':');

    //comprobamos si las horas son congruentes
    if ((parseInt(hr_ini[0]) > parseInt(hr_fin[0])) || (parseInt(hr_ini[0]) == parseInt(hr_fin[0]))) {
        flag_horas_incongruentes = 1;
    }

    $flag_full_day = 0;

    var url = "";
    var ajax = objetoAjax();
    url = "../common/get_fechas_reservas.php?inicio=" + inicio + "&fin=" + fin + "&incongruencia=" + flag_horas_incongruentes + "&full_day=" + $flag_full_day + "&min_hr=" + min_hr + "&max_hr=" + max_hr;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                console.log(ajax.responseText);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);
                    if (jsonData.estado == 1) {
                        showDialog(jsonData.mensaje);
                        generatedViewCalendar(menu_opcion, submenu_opcion);
                    } else if (jsonData.estado == 2) {
                        showDialog(jsonData.mensaje);
                        flag_echar = true;
                    } else {
                        //recargo la pagina
                        if (menu_opcion > 0 && submenu_opcion > 0) {
                            generatedViewCalendar(menu_opcion, submenu_opcion);
                        }
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            } else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status);
            }
        }
    };
    ajax.send(null);
    esperaRespuesta(true);
}

/**
 * 
 * Funcion para detectar que ha chequeado el checkbox de tipo de puesto
 *
 */
function chequearTipoPuesto(e) {
    if (e.checked == true) {
        document.getElementById("div_icono").style.display = "block";
        document.getElementById("div_color").style.display = "block";
        document.getElementById("div_width").style.display = "block";
        document.getElementById("div_height").style.display = "block";
        document.getElementById("div_tipo_parking").style.display = "block";
    } else {
        document.getElementById("div_icono").style.display = "none";
        document.getElementById("div_color").style.display = "none";
        document.getElementById("div_width").style.display = "none";
        document.getElementById("div_height").style.display = "none";
        document.getElementById("div_tipo_parking").style.display = "none";
    }
}

/**
 * 
 * Funcion para captar la seleccion del dia completo
 *
 */
function setearFullDay(checkbox, inicio = "", fin = "", menu_opcion = 0, submenu_opcion = 0, $flag_full_day = 0) {

    if (checkbox.checked == true) {
        var hora_inicio = "";
        var hora_fin = "";

        if (inicio != "" && fin != "") {
            var hora_inicio_array = inicio.split(":");
            var hora_fin_array = fin.split(":");

            hora_inicio = hora_inicio_array[0] + ':' + hora_inicio_array[1];
            hora_fin = hora_fin_array[0] + ':' + hora_fin_array[1];
        }

        if (menu_opcion > 0 && submenu_opcion > 0) {
            if ($flag_full_day == 0) {
                $flag_full_day = 1;
            }
        } else {
            if ($flag_full_day == 0) {
                $flag_full_day = 1;
            }
            document.getElementById("hora_inicio").value = hora_inicio;
            document.getElementById("hora_fin").value = hora_fin;
            document.getElementById("hora_inicio").setAttribute("disabled", true);
            document.getElementById("hora_fin").setAttribute("disabled", true);
        }
    } else {
        if (menu_opcion > 0 && submenu_opcion > 0) {
            if ($flag_full_day == 1) {
                $flag_full_day = 0;
            }
        } else {
            if ($flag_full_day == 1) {
                $flag_full_day = 0;
            }
            document.getElementById("hora_inicio").value = "";
            document.getElementById("hora_fin").value = "";
            document.getElementById("hora_inicio").removeAttribute("disabled");
            document.getElementById("hora_fin").removeAttribute("disabled");
        }
    }

    min_hr = inicio;
    max_hr = fin;

    var flag_horas_incongruentes = 0;

    var url = "";
    var ajax = objetoAjax();
    url = "../common/get_fechas_reservas.php?inicio=" + hora_inicio + "&fin=" + hora_fin + "&incongruencia=" + flag_horas_incongruentes + "&full_day=" + $flag_full_day + "&min_hr=" + min_hr + "&max_hr=" + max_hr;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);
                    if (jsonData.estado == 1) {
                        showDialog(jsonData.mensaje);
                        return;
                    } else if (jsonData.estado == 2) {
                        showDialog(jsonData.mensaje);
                        flag_echar = true;
                    } else {
                        //recargo la pagina
                        if (menu_opcion > 0 && submenu_opcion > 0) {

                            generatedViewCalendar(menu_opcion, submenu_opcion);
                        }
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            } else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status);
            }
        }
    };
    ajax.send(null);
    esperaRespuesta(true);
}

/**
 * 
 * Funcion para captar el puesto
 *
 */
function setPuestoFisico(menu_opcion = 0, submenu_opcion = 0, id, e, tipo_reserva = 0, modulo_ubicaciones = 0) {
    var url = "";
    var ajax = objetoAjax();
    url = "../common/get_puesto_fisico.php?id=" + id + "&modulo_ubicacione=" + modulo_ubicaciones;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);
                    if (jsonData.estado == 1) {
                        showDialog(jsonData.mensaje);
                        return;
                    } else if (jsonData.estado == 2) {
                        showDialog(jsonData.mensaje);
                        flag_echar = true;
                    } else {
                        //recargo la pagina
                        if (menu_opcion > 0 && submenu_opcion > 0) {
                            if (e.dataset.estado == "selected") {
                                e.dataset.estado = "deselected";
                            } else {
                                e.dataset.estado = "selected";
                            }
                            if (tipo_reserva == 1) {
                                generatedViewGraphicForm(menu_opcion, submenu_opcion);
                            } else {
                                relationsSetsCharacteristics(menu_opcion, submenu_opcion);
                            }
                        }
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            }
        }
    };
    ajax.send(null);
    esperaRespuesta(true);
}

