/**
 * 
 * Funcion para captar la caracteristica
 *
 */
function setSetCaracteristica(menu_opcion = 0, submenu_opcion = 0, id, e, status, id_elemento) {

    var url = "";
    var ajax = objetoAjax();
    url = "../common/get_set_caracteristicas.php?id=" + id + "&status=" + status;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);
                    if (jsonData.estado == 1) {
                        showDialog(jsonData.mensaje);
                        return;
                    } else if (jsonData.estado == 2) {
                        showDialog(jsonData.mensaje);
                        flag_echar = true;
                    } else {
                        //recargo la pagina
                        if (menu_opcion > 0 && submenu_opcion > 0) {
                            if (e.dataset.estado == "selected") {
                                e.dataset.estado = "deselected";
                            } else {
                                e.dataset.estado = "selected";
                            }
                            editaElemento(menu_opcion, submenu_opcion, id_elemento, accionEdicion);
                        }
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            }
        }
    };
    ajax.send(null);
    esperaRespuesta(true);
}


/**
 * 
 * Funcion para captar la caracteristica
 * setCaracteristicaDetailsOn
 */
function setCaracteristicaDetailsOn(e, e2, c = 0) {

    for (var i = 1; i <= c; i++) {
        document.getElementById('set_simple_' + i).style.display = "flex";
    }

    for (var i = 1; i <= c; i++) {
        if (e2 != 'set_details_' + i) {
            document.getElementById('set_details_' + i).style.display = "none";
        }
    }

    if (e.style.display == "flex") {
        e.style.display = "none";
        document.getElementById(e2).style.display = "flex";
    }
}

/**
 * 
 * Funcion para captar la caracteristica
 * setCaracteristicaDetailsOff
 */
function setCaracteristicaDetailsOff(e, e2, c = 0) {

    for (var i = 1; i <= c; i++) {
        document.getElementById('set_simple_' + i).style.display = "flex";
    }

    if (e.style.display == "flex") {
        e.style.display = "none";
    }
}

/**
 * 
 * Funcion para captar el espacio
 *
 */
function setOpcionParking(menu_opcion = 0, submenu_opcion = 0, e, tipo_reserva = 0, tipo = 0) {
    var borrar = 0;
    if (e != null) {
        if (e.checked == true) {
            borrar = 0;
        } else {
            console.log("borrar");
            borrar = 1;
        }
    }
    var url = "";
    var ajax = objetoAjax();
    url = "../common/get_opcion_parking.php?borrar=" + borrar + "&tipo=" + tipo;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);
                    if (jsonData.estado == 1) {
                        showDialog(jsonData.mensaje);
                        return;
                    } else if (jsonData.estado == 2) {
                        showDialog(jsonData.mensaje);
                        flag_echar = true;
                    } else {
                        //recargo la pagina
                        if (menu_opcion > 0 && submenu_opcion > 0) {

                            if (tipo_reserva == 1) {
                                generatedViewGraphicForm(menu_opcion, submenu_opcion);
                            } else if (tipo_reserva == 2) {
                                generatedViewCalendar(menu_opcion, submenu_opcion);
                            } else {
                                relationsSetsCharacteristics(menu_opcion, submenu_opcion);
                            }
                        }
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            } else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status);
            }
        }
    };
    ajax.send(null);
    esperaRespuesta(true);
}

