/**
 * 
 * Funcion para guardar los elementos del calendario sin salir
 *
 */
function guardaElementosPlano(menu_opcion, submenu_opcion) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var formulario = document.getElementById("nuevo_elemento");
        var longitudFormulario = formulario.elements.length;
        var formData = new FormData();
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        for (var i = 0; i <= (longitudFormulario - 1); i++) {
            if (formulario.elements[i].required == true && formulario.elements[i].value == "") {
                showDialog(mensaje_faltan_campos);
                formulario.elements[i].classList.add("requerido");
                return false;
            }
            if (formulario.elements[i].type != 'file' && formulario.elements[i].value != '') {
                formData.append(formulario.elements[i].name, formulario.elements[i].value);
            } else if (formulario.elements[i].value != '') {
                var files = formulario.elements[i].files;
                formData.append(formulario.elements[i].name, files[0], files[0].name);
            }
        }

        var url = "";
        var ajax = objetoAjax();;
        url = "../common/save_elements_plane.php";
        ajax.open("POST", url, true);
        //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            showDialog(arr_aux[1]);

                            //irAContenido(menu_activo,menu_opcion,submenu_opcion);
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}

function siguiente_pantalla(elemento_id) {
    var estado = document.getElementById("horario_ciclo");
    var horario_id = estado.options[estado.selectedIndex].value;
    var dia = document.getElementById("primer_dia_ciclo");
    var primer_dia = dia.options[dia.selectedIndex].value;
    var dias_ciclo = document.getElementById("dias_ciclo").value;
    var empleados_ciclo = document.getElementById("empleados_ciclo").value;
    var ciclo_id = document.getElementById("ciclo_id").value;
    var url = "";
    var ajax = objetoAjax();
    if (ciclo_id == "") {
        url = "../common/crea_ciclos.php?hor_id=" + horario_id + "&primer_dia=" + primer_dia + "&dc=" + dias_ciclo + "&ec=" + empleados_ciclo + "&eid=" + elemento_id;
    } else {
        url = "../common/crea_ciclos.php?hor_id=" + horario_id + "&primer_dia=" + primer_dia + "&dc=" + dias_ciclo + "&ec=" + empleados_ciclo + "&eid=" + elemento_id + "&ciclo_id=" + ciclo_id;
    }
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;

                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);
                    if (jsonData.estado == 0) {
                        //insertamos el cuadro
                        var tabla = document.getElementById("armar_ciclos");
                        tabla.innerHTML = jsonData.ciclo;
                        tabla.style.display = "block";
                        var continuar = document.getElementById("boton_continuar");
                        continuar.style.display = "none";
                        var guardar = document.getElementById("boton_guardar");
                        guardar.style.display = "block";
                    }
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            }
            else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status);
            }
        }
    };
    esperaRespuesta(true);
    ajax.send(null);
}

function reduce_centros(elemento_id) {
    var ciclos = document.getElementById("id_ciclo");
    var ciclo_id = ciclos.options[ciclos.selectedIndex].value;
    var datos = {
        "ciclo_id": ciclo_id,
        "elemento_id": elemento_id
    }

    var url = "";
    url = "../common/reduce_departamentos.php";
    esperaRespuesta(true);
    $.post(url, datos, function (data) {
        esperaRespuesta(false);
        if (data != "") {

            var jsonData = JSON.parse(data);
            if (jsonData.estado == "ok") {
                document.getElementById("div_centros_turnos").innerHTML = jsonData.centro;
                document.getElementById("div_centros_turnos").style.display = "block";
                document.getElementById("div_departamentos_turnos").innerHTML = jsonData.Depto;
                document.getElementById("div_departamentos_turnos").style.display = "block";
                document.getElementById("div_empleados_turnos").innerHTML = jsonData.empleado;
                document.getElementById("div_empleados_turnos").style.display = "block";

                $(function () {
                    $("#departamentos").pqSelect({
                        multiplePlaceholder: seleccionar_departamento,
                        displayText: mensaje_filtro_seleccionados,
                        deselect: true,
                        selectallText: seleccionar_todos,
                        checkbox: true,
                        maxDisplay: 6,
                        search: true
                    }).on("change", function (evt) {
                        var val = $(this).val();
                        //console.log(val);
                        $("#departamento_ids").val(val);
                        reduce_empleados(elemento_id, val);
                    });
                });
                $(function () {
                    $("#empleados").pqSelect({
                        multiplePlaceholder: seleccionar_empleado,
                        displayText: mensaje_filtro_seleccionados,
                        deselect: true,
                        selectallText: seleccionar_todos,
                        checkbox: true,
                        maxDisplay: 6,
                        search: true
                    }).on("change", function (evt) {
                        var val = $(this).val();
                        $("#empleado_ids").val(val);
                    });
                });
            }
        }

    });

}


function reduce_empleados(elemento_id, departamentos) {

    if (departamentos === null) {
        reduce_centros(elemento_id);
    } else {
        var datos = {
            "depo_ids": departamentos,
            "elemento_id": elemento_id
        }
        var url = "";
        url = "../common/reduce_empleados.php";
        esperaRespuesta(true);
        $.post(url, datos, function (data) {
            esperaRespuesta(false);
            if (data != "") {

                var jsonData = JSON.parse(data);
                if (jsonData.estado == "ok") {
                    document.getElementById("div_empleados_turnos").innerHTML = jsonData.selector;
                    document.getElementById("div_empleados_turnos").style.display = "block";
                    $(function () {
                        $("#empleados").pqSelect({
                            multiplePlaceholder: seleccionar_empleado,
                            displayText: mensaje_filtro_seleccionados,
                            deselect: true,
                            selectallText: seleccionar_todos,
                            checkbox: true,
                            maxDisplay: 6,
                            search: true
                        }).on("change", function (evt) {
                            var val = $(this).val();
                            $("#empleado_ids").val(val);
                        });
                    });

                }
            }

        });
    }
}

function valida_continuar_turnos(seccion_id, elemento_id, id) {
    var nombre_turno = document.getElementById("nombre_turno").value;
    var estado = document.getElementById("ciclo");
    var ciclo_id = estado.options[estado.selectedIndex].value;
    var fecha_inicio = document.getElementById("fecha_inicial").value;
    var fecha_final = document.getElementById("fecha_final").value;

    var error = 0;
    var errores = '';

    if (nombre_turno.length == 0) {
        error = 1;
        errores += '- Debe darle un nombre al turno<br>';
    }
    if (ciclo_id == -1) {
        error = 1;
        errores += '- Debe seleccionar un ciclo<br>';
    } else {
        var departamento_ids = document.getElementById("departamento_ids").value;
        var empleado_ids = document.getElementById("empleado_ids").value;
        if (empleado_ids.length == 0 && departamento_ids == 0) {
            error = 1;
            errores += '- Debe seleccionar al menos un empleado o un departamento del selector<br>';
        }
    }
    if (fecha_inicio.length == 0) {
        error = 1;
        errores += '- Debe seleccionar una fecha de inicio<br>';
    }
    if (fecha_final.length == 0) {
        error = 1;
        errores += '- Debe seleccionar una fecha de fin<br>';
    }
    if (fecha_inicio.length != 0 && fecha_final.length != 0 && fecha_inicio > fecha_final) {
        error = 1;
        errores += '- La fecha inicio no puede ser mayor que fecha fin<br>';
    }
    var fecha_actual = Date.now();
    var fecha_inicio_temp = new Date(fecha_inicio);
    if (fecha_inicio.length != 0 && fecha_inicio_temp < fecha_actual) {
        error = 1;
        errores += '- La fecha inicio no puede ser menor que la fecha actual<br>';
    }
    if (error == 0) {
        if (seccion_id == 0) {
            checkNone();
            siguiente_pantalla_turnos(elemento_id);
        } else {
            aplicar_planes_turnos(seccion_id, elemento_id, true, id);
        }
    } else if (error == 1) {
        showDialog(errores);
    }
}

