function guarda_turno(menu_id, elemento_id, flag_edicion) {
    var nombre_turno = document.getElementById("nombre_turno").value;
    var estado = document.getElementById("ciclo");
    var ciclo_id = estado.options[estado.selectedIndex].value;
    var centro_id = document.getElementById("centro_id").value;
    var fecha_inicio = document.getElementById("fecha_inicial").value;
    var fecha_final = document.getElementById("fecha_final").value;
    var departamento_ids = document.getElementById("departamento_ids").value;
    var empleado_ids = document.getElementById("empleado_ids").value;
    var turno_id = document.getElementById("turnos_id").value;
    var empleados = document.getElementsByName("id");

    var cuadrante = {};
    var empleados_id = {};
    var y = 0;
    for (j = 0; j < empleados.length; j++) {
        if (empleados[j].checked == true) {
            var empleado_id = empleados[j].value;
            empleados_id[y] = empleados[j].value;
            cuadrante[empleado_id] = {};
            var empleado_dias = document.getElementById("empleado-" + empleado_id);
            var num_dias = empleado_dias.dataset.totalfecha;
            for (i = 1; i <= num_dias; i++) {
                var emp = document.getElementById(empleado_id + "-" + i);
                cuadrante[empleado_id][emp.dataset.fecha] = emp.dataset.id;
            }
            y++;
        }
    }
    cuadrante = JSON.stringify(cuadrante);
    empleados_id = JSON.stringify(empleados_id);
    checkNone();
    if (cuadrante.length != 2) {

        //var dias = document.getElementById("empleado-"+).value;
        if (turno_id == "") {
            var datos = {
                "op": menu_id,
                "sub": elemento_id,
                "fe": flag_edicion,
                "nombre_turno": nombre_turno,
                "ciclo_id": ciclo_id,
                "departamento_ids": departamento_ids,
                "empleado_ids": empleados_id,
                "fecha_inicio": fecha_inicio,
                "fecha_fin": fecha_final,
                "cuadrante": cuadrante
            }
        } else {
            var datos = {
                "op": menu_id,
                "sub": elemento_id,
                "fe": flag_edicion,
                "nombre_turno": nombre_turno,
                "ciclo_id": ciclo_id,
                "departamento_ids": departamento_ids,
                "empleado_ids": empleados_id,
                "fecha_inicio": fecha_inicio,
                "fecha_fin": fecha_final,
                "turno_id": turno_id,
                "cuadrante": cuadrante
            }
        }
        var url = "";
        url = "../common/grabar_turno.php";
        esperaRespuesta(true);
        $.post(url, datos, function (data) {
            esperaRespuesta(false);
            var arr_aux = data.split("|");
            if (arr_aux[0] == 0) {
                showDialog(arr_aux[1]);
            }
            irAContenido(menu_activo, menu_id, elemento_id);
        });
    } else {
        showDialog("Debe seleccionar al menos un empleado para poder guardar la simulación");
    }
}

/**
 * 
 * Funcion para captar el puesto
 *
 */
function setFechaTicketsPedidos(seccion_id, elemento_id, informe_id) {
    //inicializamos
    var date = "";
    var url = "";
    var ajax = objetoAjax();
    date = document.getElementById("fecha_fin").value;
    url = "../common/get_fecha_pedidos.php?date=" + date;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);
                    if (jsonData.estado == 1) {
                        showDialog(jsonData.mensaje);
                        return;
                    } else if (jsonData.estado == 2) {
                        showDialog(jsonData.mensaje);
                        flag_echar = true;
                    } else {
                        //recargo la pagina
                        if (seccion_id > 0 && elemento_id > 0 && informe_id) {
                            verElemento(seccion_id, elemento_id, informe_id);
                            document.getElementById("fecha_fin").value = jsonData.final_date;
                        }
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            }
        }
    };
    ajax.send(null);
    esperaRespuesta(true);
}

