function getIPsElemento(menu_opcion, submenu_opcion, empresas_id, elemIdIPs, accion) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var url = "";
        var ajax = objetoAjax();
        var arrInput = document.getElementsByTagName('input');
        tarjetas = new Array();
        roles = new Array();
        let elementoId = null;
        for (var i = 0; i < arrInput.length; i++) {
            if (arrInput[i].type == 'checkbox' && arrInput[i].name == 'id' && arrInput[i].checked == true) {
                elementoId = arrInput[i].value;
                break;
            }
        }
        if (empresas_id != null) {
            url = "../common/get_ip.php?op=" + menu_opcion + "&sub=" + submenu_opcion + "&id=" + elemIdIPs + (accion != null ? "&accion=" + accion : "");

            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 1) {
                                showDialog(arr_aux[1]);
                            } else if (arr_aux[0] == 2) {
                                showDialog(arr_aux[1]);
                                flag_echar = true;
                            } else {
                                const respuesta = JSON.parse(arr_aux[1]);
                                // showDialog(respuesta);
                                $('#idip').val(respuesta.idip);
                                $('#ip_1').val(respuesta.ip_1);
                                $('#ip_2').val(respuesta.ip_2);
                                $('#ip_3').val(respuesta.ip_3);
                                $('#ip_4').val(respuesta.ip_4);
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    } else if (ajax.status == 500) {
                        showDialog("Error code");
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);

        } else {
            showDialog("Debe seleccionar una empresa");
        }
    } else {
        showDialog(invalidOption);
    }
}

