function actualizarIP(menu_opcion, submenu_opcion, elemento_id, elemIdIPs, accion, flag_mobil = 0) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var formulario = document.getElementById("nuevo_elemento");
        var longitudFormulario = formulario.elements.length;
        var formData = new FormData();
        var jsonObj = {};

        const requeridos = formulario.getElementsByClassName('iprequi');
        const longitudRequeridos = requeridos.length;
        var faltan = false;
        for (var i = 0; i <= (longitudRequeridos - 1); i++) {
            if (requeridos[i].value == "") {
                faltan = true;
            }
        }
        if (!faltan) {
            if (flag_mobil == undefined || flag_mobil == 0) {
                formData.append('op', menu_opcion);
                formData.append('sub', submenu_opcion);
            } else {
                jsonObj.op = menu_opcion;
                jsonObj.sub = submenu_opcion;
            }
            const id_empresas = document.getElementById("id_empresas");
            if (id_empresas != null) {
                formData.append(id_empresas.id, id_empresas.value);
            }
            const idip = document.getElementById("idip");
            if (idip != null) {
                formData.append(idip.id, idip.value);
            }
            const ip1 = document.getElementById("ip_1");
            if (ip1 != null && ip1.value != "") {
                formData.append(ip1.id, ip1.value);
            } else {
                showDialog(mensaje_error_dato_no_valido);
                return;
            }
            const ip2 = document.getElementById("ip_2");
            if (ip2 != null && ip2.value != "") {
                formData.append(ip2.id, ip2.value);
            } else {
                showDialog(mensaje_error_dato_no_valido);
                return;
            }
            const ip3 = document.getElementById("ip_3");
            if (ip3 != null && ip3.value != "") {
                formData.append(ip3.id, ip3.value);
            } else {
                showDialog(mensaje_error_dato_no_valido);
                return;
            }
            const ip4 = document.getElementById("ip_4");
            if (ip4 != null && ip4.value != "") {
                formData.append(ip4.id, ip4.value);
            } else {
                showDialog(mensaje_error_dato_no_valido);
                return;
            }
            var url = "";
            var ajax = objetoAjax();
            url = "../common/save_ips.php";
            ajax.open("POST", url, true);
            //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        informeProcess = 0;
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 1) {
                                showDialog(arr_aux[1]);
                            } else if (arr_aux[0] == 2) {
                                showDialog(arr_aux[1]);
                                flag_echar = true;
                            } else {
                                hideDialog();
                                showDialog(arr_aux[1]);
                            }
                        } else {
                            showDialog(noResults);
                        }

                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                    //irAContenido(menu_activo,menu_opcion,submenu_opcion);
                    //genIPsForm(menu_opcion,submenu_opcion,elemento_id,null,'ips_lista');
                    editaElemento(menu_opcion, submenu_opcion, elemento_id);

                }
            };
            informeProcess = 1;
            if (flag_mobil == undefined || flag_mobil == 0) {
                ajax.send(formData);
            } else {
                ajax.send(JSON.stringify(jsonObj));
            }
            esperaRespuesta(true);
        } else {
            showDialog('Faltan Cargar Datos Requeridos');
        }
    } else {
        showDialog(invalidOption);
    }
}


/**
 * Valida la fucha que no se menor a un numer especifivo
 *
 */
function validatedDateTickets(e) {
    var fecha_fin_centro_coste = e.value;
    var fecha_aux = fecha_fin_centro_coste.split("-");
    var dia = fecha_aux[0];
    var mes = fecha_aux[1];
    var anno = fecha_aux[2];
    if (fecha_aux[2] <= 2021) {
        if (fecha_aux[2] == 2021) {
            if (fecha_aux[1] < 12) {
                alert(mensaje_error_knorr_inf_centro_coste);
                e.value = "01-12-2021";
            }
        }
    } else if (fecha_aux[2] < 2021) {
        if (fecha_aux[1] < 12) {
            e.value = "01-12-2021";
        }
    }
}

