/**
 * Funcion que quita centros a la lista de asignados para que sean despues guardados
 *
 */
function removeCentroFromFichaje(menu_opcion, submenu_opcion, idEmpleados, accion) {
    if (idEmpleados != "") {
        var formData = new FormData();
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        formData.append('id_empleados', idEmpleados);

        var arrInput = document.getElementsByTagName('input');
        var arrIdSeleccionado = new Array();
        if (arrInput != null) {
            for (var i = 0; i < arrInput.length; i++) {
                if (arrInput[i].type == "checkbox" && arrInput[i].name == "id_centro_asignado" && arrInput[i].checked == true) {
                    //if(arrInput[i].type == "checkbox"  && arrInput[i].id == "id_centro_asignado" && arrInput[i].checked == true){
                    //Es un centro seleccionado
                    arrIdSeleccionado.push(arrInput[i].value);
                }
            }
            if (arrIdSeleccionado.length > 0) {
                //Centro almacenados enviamos a background para tenerlos disponibles en sesion
                var jsonIdSeleccionado = JSON.stringify(arrIdSeleccionado);

                var url = "";
                var ajax = objetoAjax();
                url = "../common/asignacion_centros.php?op=del&ce=" + jsonIdSeleccionado + '&me=' + menu_opcion + '&sub=' + submenu_opcion;
                ajax.open("GET", url, true);
                ajax.onreadystatechange = function () {
                    if (ajax.readyState == 4) {
                        if (ajax.status == 200) {
                            esperaRespuesta(false);
                            var html_txt = ajax.responseText;
                            if (html_txt != "") {
                                var jsonData = JSON.parse(html_txt);
                                if (jsonData.estado == 1) {
                                    showDialog(jsonData.mensaje);
                                    return;
                                } else if (jsonData.estado == 2) {
                                    showDialog(jsonData.mensaje);
                                    flag_echar = true;
                                } else {
                                    if (accion == accionLista) {
                                        irAContenido(menu_activo, menu_opcion, submenu_opcion);
                                    } else if (accion == accionFormulario) {
                                        nuevoElemento(menu_opcion, submenu_opcion, null);
                                    } else if (accion == accionEdicion) {
                                        editaElemento(menu_opcion, submenu_opcion, idEmpleados);
                                    }
                                }
                            } else {
                                showDialog(noResults);
                            }
                        } else if (ajax.status == 404) {
                            showDialog(error404);
                        } else if (ajax.status != 0) {
                            showDialog("Error:" + ajax.status);
                        }
                    }
                };
                esperaRespuesta(true);
                ajax.send(null);
            }
        }
    } else {
        showDialog(invalidOption);
    }

}

