function getImageUpload(obj, idfichero) {

    var files = obj.files;
    var fileContent = document.getElementById(idfichero);
    if (files.length === 0) {
        console.log('No files selected');
        return;
    }

    var reader = new FileReader();
    reader.onload = function (event) {
        fileContent.value = event.target.result;
    };
    reader.readAsDataURL(files[0]);
}
function editDisplay(cont, button) {
    var b = button;
    var id = "edit" + cont;
    var x = document.getElementById(id);

    if (b.innerHTML == 'Cancelar') {
        b.innerHTML = 'Editar';
        b.className = "botonRellena";
    } else {
        b.innerHTML = 'Cancelar';
        b.className = "botonRellenaCancelar";
    }

    if (x.style.display === "none") {
        x.style.display = "block";
    } else {
        x.style.display = "none";
    }
}

function rellenaTrabajo(menu_opcion, submenu_opcion, elemento_id) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && elemento_id != "") {
        var url = "";
        var ajax = objetoAjax();
        tarjetas = new Array();
        url = "../common/gen_rellena_trabajo.php?op=" + menu_opcion + "&sub=" + submenu_opcion + '&id=' + elemento_id;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            if (arr_aux[2] === undefined) {

                                document.getElementById("content").innerHTML = arr_aux[1];
                            } else {
                                document.getElementById("content").innerHTML = arr_aux[1];
                                //console.log(arr_aux[1]);                                  
                                $("#acordeon").accordion({
                                    heightStyle: "content",
                                    collapsible: true,
                                    active: parseInt(arr_aux[2])
                                });
                            }

                            //$("#acordeon" ).accordion();
                        }
                    } else {
                        showDialog("No se han encontrado resultados con los parametros introducidos");
                    }
                } else if (ajax.status == 404) {
                    showDialog("La pagina no existe");
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }

            }
        };
        esperaRespuesta(true);
        ajax.send(null);
    } else {
        showDialog("No es una opción válida");
    }
}
