function guarda_turno_horario(menu_id, elemento_id, flag_edicion = 0, msg_error_required = "") {

    //inicializacion
    let null_required_imputs = 0;
    let info_array = {};

    info_array["tipo_horario"] = "tramos";

    info_array["nombre"] = document.getElementById("nombre").value;
    info_array["nocturnas_comienzo"] = document.getElementById("nocturnas_comienzo").value;
    info_array["nocturnas_fin"] = document.getElementById("nocturnas_fin").value;
    info_array["margen_extras"] = document.getElementById("margen_extras").value;
    info_array["margen_inicio_dia"] = document.getElementById("margen_inicio_dia").value;
    info_array["margen_fin_dia"] = document.getElementById("margen_fin_dia").value;
    info_array["entrada_flexible"] = document.getElementById("entrada_flexible").value;

    if (document.getElementById("descripcion") !== 'undefined') {
        info_array["descripcion"] = document.getElementById("descripcion").value;
    }

    if (info_array["tipo_horario"] == "tramos") {
        info_array["acronimo"] = document.getElementById("acronimo").value;
        info_array["turnos_revision"] = document.getElementById("turnos_revision").value;
        info_array["turnos"] = document.getElementById("turnos").value;
        info_array["hora_inicio_dia"] = document.getElementById("hora_inicio_dia").value;
        info_array["salida_flexible"] = document.getElementById("salida_flexible").value;
        info_array["margen_retraso"] = document.getElementById("margen_retraso").value;

        if (document.getElementById("nombre").value == "" ||
            document.getElementById("nombre").value == 'undefined') {
            null_required_imputs = 1;
        }

        if (document.getElementById("acronimo").value == "" ||
            document.getElementById("acronimo").value == 'undefined') {

            null_required_imputs = 1;
        }

        if (flag_edicion == 1) {
            info_array["id"] = document.getElementById("id").value;
            info_array["id_centros"] = document.getElementById("id_centros").value;
        } else {

            //validamos los campos requeridos
            if (document.getElementById("empresas_single").value == "" ||
                document.getElementById("empresas_single").value == 'undefined') {

                null_required_imputs = 1;
            }

            //validamos los campos requeridos
            if (document.getElementById("centros").value == "" ||
                document.getElementById("centros").value == 'undefined') {

                null_required_imputs = 1;
            }

            info_array["empresas"] = document.getElementById("empresas_single").value;
            info_array["centros"] = document.getElementById("centros").value;
        }

        for (let t = 0; t <= document.getElementById("turnos").value; t++) {
            if (t > 0) {
                for (let i = 0; i < 7; i++) {
                    for (let j = 1; j <= 3; j++) {

                        if (document.getElementById("flex_inicio_" + j + "-" + i + "-Turno" + t).checked == true) {
                            info_array["flex_inicio_" + j + "-" + i + "-Turno" + t] = "1";
                        } else {
                            info_array["flex_inicio_" + j + "-" + i + "-Turno" + t] = "0";
                        }

                        if (document.getElementById("flex_fin_" + j + "-" + i + "-Turno" + t).checked == true) {
                            info_array["flex_fin_" + j + "-" + i + "-Turno" + t] = "1";
                        } else {
                            info_array["flex_fin_" + j + "-" + i + "-Turno" + t] = "0";
                        }

                        info_array["inicio_tramo_" + j + "-" + i + "-Turno" + t] = document.getElementById("inicio_tramo_" + j + "-" + i + "-Turno" + t).value;
                        info_array["fin_tramo_" + j + "-" + i + "-Turno" + t] = document.getElementById("fin_tramo_" + j + "-" + i + "-Turno" + t).value;
                    }
                    info_array["tramo_comida-" + i + "-Turno" + t] = document.getElementById("tramo_comida-" + i + "-Turno" + t).value;
                }

                if (document.getElementById("nombre-Turno" + t).required == true) {
                    if (document.getElementById("nombre-Turno" + t).value == 'undefined' ||
                        document.getElementById("nombre-Turno" + t).value == '') {

                        null_required_imputs = 1;
                    }
                }

                if (document.getElementById("acronimo-Turno" + t).required == true) {
                    if (document.getElementById("acronimo-Turno" + t).value == 'undefined' ||
                        document.getElementById("acronimo-Turno" + t).value == '') {

                        null_required_imputs = 1;
                    }
                }
                info_array["nombre-Turno" + t] = document.getElementById("nombre-Turno" + t).value;
                info_array["acronimo-Turno" + t] = document.getElementById("acronimo-Turno" + t).value;
            }
        }
    }

    var data = JSON.stringify(info_array);

    var datos = {
        "op": menu_id,
        "sub": elemento_id,
        "fe": flag_edicion,
        "datos": data
    }

    if (null_required_imputs == 1) {
        showDialog(msg_error_required);
    } else {
        var url = "";
        url = "../common/grabar_turno_horario.php";
        esperaRespuesta(true);

        $.post(url, datos, function (data) {

            esperaRespuesta(false);
            var arr_aux = data.split("|");

            if (arr_aux[0] == 0) {
                showDialog(arr_aux[1]);
                irAContenido(menu_activo, menu_id, elemento_id);
            }
            if (arr_aux[0] == 1) {
                showDialog(arr_aux[1]);
            }
        });
    }
}

/**
 * Funcion que valida si hay saldo para compensar en la bolsa jornada de DRAGADOS
 *
 */
function compruebaBolsas2(menu_opcion, submenu_opcion, id_empleado) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && id_empleado != "") {
        var url = "";
        var ajax = objetoAjax();;
        url = "../common/compensacion_bolsa2_dragados.php?op=" + menu_opcion + "&sub=" + submenu_opcion + '&id=' + id_empleado;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    informeProcess = 0;
                    var html_txt = ajax.responseText.trim();
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        if (jsonData.estado == "ok") {
                            if (jsonData.extras > 0 && jsonData.auto < 0) {
                                showConfirm(jsonData.mensaje, compensaBolsas2, menu_opcion, submenu_opcion, id_empleado, jsonData.extras, jsonData.auto);
                            } else if (jsonData.extras == 0) {
                                showDialog(noExtra);
                            } else if (jsonData.auto == 0) {
                                showDialog(noAuto);
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        ajax.send(null);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion que compensa la bolsa de jornada de DRAGADOS
 *
 */
function compensaBolsas2(menu_opcion, submenu_opcion, id_empleado, extras, auto) {
    if (extras >= -auto) {
        //compensamos TODO auto
        var comp = -auto;
    } else {
        //compensamos TODO extras
        var comp = extras;
    }

    var url = "";
    var ajax = objetoAjax();;
    url = "../common/compensacion_bolsa2_dragados_guardar.php?op=" + menu_opcion + "&sub=" + submenu_opcion + '&id=' + id_empleado + '&comp=' + comp;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                informeProcess = 0;
                var html_txt = ajax.responseText.trim();
                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);
                    if (jsonData.estado == "ok") {
                        showDialog(CompOK);
                    } else if (jsonData.estado == "error") {
                        showDialog(CompError1);
                    } else if (jsonData.estado == "error2") {
                        showDialog(CompError2);
                    }
                    irAContenido(menu_activo, menu_opcion, submenu_opcion);
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            } else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status);
            }
        }
    };
    ajax.send(null);
    esperaRespuesta(true);
}

