        document.getElementById("ocultarCuestionario").removeAttribute("style");
        document.getElementById("ocultarCuestionario").style.display = "block";
        document.getElementById("ocultarMensaje").removeAttribute("style");
        document.getElementById("ocultarMensaje").style.display = "none";
