function seleccionarArea(event) {
    //quitar el background de los td de hoy pq se sobrepone a la selección
    var hoy = document.getElementsByClassName("hoy");
    for (var i = 0; i < hoy.length; i++) {
        hoy[i].style.backgroundColor = "transparent";
    }
    //coordenadas donde comienza el evento
    var x_inicial = event.pageX;
    var y_inicial = event.pageY;
    var x_final = event.pageX;
    var y_final = event.pageY;
    var mouse_down = true;
    var area = document.getElementById('area_seleccion');
    area.hidden = false;
    $(".calendarios").bind("mousemove", function (e) {
        if (mouse_down) {
            x_final = e.pageX;
            y_final = e.pageY;
            area.style.left = Math.min(x_inicial, x_final) + "px";
            area.style.top = Math.min(y_inicial, y_final) + "px";
            area.style.width = Math.max(x_inicial, x_final) - Math.min(x_inicial, x_final) + "px";
            area.style.height = Math.max(y_inicial, y_final) - Math.min(y_inicial, y_final) + "px";
        }
    });

    $(".calendarios").bind("mouseup", function (e) {
        //devolverle el backgroud a hoy
        for (var i = 0; i < hoy.length; i++) {
            hoy[i].style.backgroundColor = "#f5f5f5";
        }
        area.hidden = true;
        mouse_down = false;
        //tomar las coordenadas finales
        seleccionDias = [];
        x_final = e.pageX;
        y_final = e.pageY;

        //invertir la selección
        if (x_inicial > x_final) {
            var temp = x_inicial;
            x_inicial = x_final;
            x_final = temp;
        }
        if (y_inicial > y_final) {
            var temp = y_inicial;
            y_inicial = y_final;
            y_final = temp;
        }
        //tomar todas las posiciones de los td del dom
        var elem = document.querySelectorAll('td');
        var cuadrante = [];
        for (var i = 0; i < elem.length; i++) {
            if (elem[i].id != "") {
                var rect = elem[i].getBoundingClientRect();
                cuadrante.push({ id: elem[i].id, x_inicial: rect.left + window.scrollX, y_inicial: rect.top + window.scrollY, x_final: rect.right + window.scrollX, y_final: rect.bottom + window.scrollY });
            }
        }
        //tomar los td que estén dentro de la selección
        for (var i = 0; i < cuadrante.length; i++) {
            document.getElementById(cuadrante[i].id).style.border = "none";
            //selección mayor que el td
            if ((x_inicial <= cuadrante[i].x_inicial && x_final >= cuadrante[i].x_inicial) || (x_inicial <= cuadrante[i].x_final && x_final >= cuadrante[i].x_final) || (cuadrante[i].x_inicial <= x_inicial && cuadrante[i].x_final >= x_final)) {
                if ((y_inicial <= cuadrante[i].y_inicial && y_final >= cuadrante[i].y_inicial) || (y_inicial <= cuadrante[i].y_final && y_final >= cuadrante[i].y_final) || (cuadrante[i].y_inicial <= y_inicial && cuadrante[i].y_final >= y_final)) {
                    seleccionDias.push(cuadrante[i].id);
                    document.getElementById(cuadrante[i].id).style.border = "solid";
                    document.getElementById(cuadrante[i].id).style.borderColor = "#5889d6";
                }
            }
        }
    });
}

