/*
 * Vacía los input de centros quiron si se marca como no quiron o marca como quiron si se llenan estos.
 */
function esQuiron(elemento, indice) {
    let centro_quiron = document.getElementById('centro_quiron' + indice);
    let contrato_quiron = document.getElementById('contrato_quiron' + indice);
    let sincronizador = document.getElementById('sincronizador' + indice);

    setTimeout(function () {
        if (elemento == null) {
            if (centro_quiron.value != "" && contrato_quiron.value != "") {
                let flag_quiron = document.getElementById('flag_quiron' + indice);
                flag_quiron.value = 1;
                flag_quiron.checked = true;
                flag_quiron.disabled = false;
                sincronizador.hidden = false;
            } else {
                let flag_quiron = document.getElementById('flag_quiron' + indice);
                flag_quiron.checked = false;
                flag_quiron.disabled = true;
                flag_quiron.value = 0;
                sincronizador.hidden = true;
            }
        } else {
            if (elemento.checked == true) {
                sincronizador.hidden = false;
                elemento.value = 1;
            } else {
                elemento.value = 0;
                centro_quiron.value = "";
                contrato_quiron.value = "";
                elemento.disabled = true;
                sincronizador.hidden = true;
            }
        }
    }, 100
    );
}

