/**
 * Funcion que checkea que el largo de un input de tipo número no sea mayor a su máximo
 *
 */
function validaTelefono(input) {
    if (input.value.length > input.max.length) {
        input.value = input.value.slice(0, input.max.length);
        showDialog("Solo se admiten " + input.max.length + " dígitos");
    }
}

/**
 * Funcion que guarda los empleados que tenga una empresa en sus centros quirón en el sistema de quirón.
 *
 */
function sincronizaEmpleadosQuiron(seccion_id, elemento_id, id_centro) {
    var formData = new FormData();
    formData.append('op', seccion_id);
    formData.append('sub', elemento_id);
    formData.append('id_centro', id_centro);

    var url = "";
    var ajax = objetoAjax();
    url = "../common/sinc_empleados_quiron.php";
    ajax.open("POST", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var arr_aux = html_txt.split("|");
                    if (arr_aux[0] == 1) {
                        showDialog(arr_aux[1]);
                    } else if (arr_aux[0] == 2) {
                        showDialog(arr_aux[1]);
                        flag_echar = true;
                    } else {
                        showDialog(arr_aux[1]);
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            } else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status);
            }
        }
    };
    ajax.send(formData);
    esperaRespuesta(true);
}
//funciones nuevo modulo cursos
//añadir Alumno
function addAlumno(id) {
    var lista_alumnos_con = document.getElementById("lista-alumnos-con");
    disableAddAlumno(id);
    var idDelete = id.replace('btn-add-a-', '');
    var p_elemento_alumno = document.getElementById("p-a-" + idDelete);
    var string_p = p_elemento_alumno.innerHTML;
    var array_p = string_p.split(", ");
    var divA = document.createElement("div");
    var atrib = document.createAttribute("class");
    atrib.value = "cursos-elemento-lista";
    divA.setAttributeNode(atrib);
    atrib = document.createAttribute("id");
    atrib.value = "alumno-" + idDelete;
    divA.setAttributeNode(atrib);
    var iH = document.createElement("input");
    atrib = document.createAttribute("name");
    atrib.value = "alumno-" + idDelete;
    iH.setAttributeNode(atrib);
    atrib = document.createAttribute("type");
    atrib.value = "hidden";
    iH.setAttributeNode(atrib);
    atrib = document.createAttribute("value");
    atrib.value = idDelete;
    iH.setAttributeNode(atrib);
    var pA = document.createElement("p");
    var textoA = document.createTextNode(array_p[0] + ", " + array_p[1] + ", " + array_p[2]);
    pA.appendChild(textoA);
    var bA = document.createElement("div");
    atrib = document.createAttribute("class");
    atrib.value = "cursos-lista-boton";
    bA.setAttributeNode(atrib);
    atrib = document.createAttribute("id");
    atrib.value = "btn-delete-a-" + idDelete;
    bA.setAttributeNode(atrib);
    bA.setAttribute('onclick', 'deleteAlumno(' + idDelete + ');');
    textoA = document.createTextNode("Eliminar");
    bA.appendChild(textoA);
    lista_alumnos_con.appendChild(divA);
    divA.appendChild(iH);
    divA.appendChild(pA);
    divA.appendChild(bA);
}
