//deshabilitar añadir alumno
function disableAddAlumno(id) {
    var idClean = id.replace('btn-add-a-', '');
    var testId = !!document.getElementById("btn-add-p-" + idClean);
    document.getElementById(id).parentNode.classList.remove("cursos-elemento-lista-visible");
    document.getElementById(id).parentNode.classList.add("cursos-elemento-lista-oculto");
    if (testId == true) {
        document.getElementById("btn-add-p-" + idClean).parentNode.classList.remove("cursos-elemento-lista-visible");
        document.getElementById("btn-add-p-" + idClean).parentNode.classList.add("cursos-elemento-lista-oculto");
    }
}
