//filtrar alumno
function filtraAlumnos() {
    const inputValue = document.getElementById("filtroAlumno").value;
    const professorsList = document.getElementById("lista-alumnos-sin");
    if (!professorsList) return;
    const alumnosElements = Array.from(professorsList.querySelectorAll(".cursos-elemento-lista-visible"));
    alumnosElements.forEach(element => {
        const name = element.querySelector("p").innerText.toLowerCase();
        if (!name.includes(inputValue)) {
            element.classList.add("cursos-busqueda-filtro");
        } else {
            element.classList.remove("cursos-busqueda-filtro");
        }
    });
}
//filtrar profesor
function filtraProfesores() {
    const inputValue = document.getElementById("filtroProfesor").value;
    const professorsList = document.getElementById("lista-profesores-sin");
    if (!professorsList) return;
    const profesoresElements = Array.from(professorsList.querySelectorAll(".cursos-elemento-lista-visible"));
    profesoresElements.forEach(element => {
        const name = element.querySelector("p").innerText.toLowerCase();
        if (!name.includes(inputValue)) {
            element.classList.add("cursos-busqueda-filtro");
        } else {
            element.classList.remove("cursos-busqueda-filtro");
        }
    });
}

//Cursos Horarios
function setDateCursos() {
    var indice = document.getElementById("id_cursos").selectedIndex;
    var selectValue = document.getElementById("id_cursos").options[indice].text;
    var arrayDeCadenas = selectValue.split("(");
    var fecha = arrayDeCadenas[1].substr(0, arrayDeCadenas[1].length - 1);
    var arrayFechas = fecha.split("/");
    var prevSpan = document.getElementById("prevSpan");
    prevSpan.innerHTML = arrayFechas[0];
    var nextSpan = document.getElementById("nextSpan");
    nextSpan.innerHTML = arrayFechas[1];
}

function verificarFranjaHoraria() {
    var cont = document.getElementsByClassName("fila_horario").length;
    for (j = 0; j < cont; j++) {
        if (j == 0) {
            var listInputInicio = document.getElementsByClassName("hora_inicio");
            var listInputFin = document.getElementsByClassName("hora_fin");
            var diasSemana = document.getElementsByClassName("dias_semana");
            var profesor = document.getElementById("profesor");
        } else {
            var listInputInicio = document.getElementsByClassName("hora_inicio" + j);
            var listInputFin = document.getElementsByClassName("hora_fin" + j);
            var diasSemana = document.getElementsByClassName("dias_semana" + j);
            var profesor = document.getElementById("profesor" + j);
        }
    }
    for (i = 0; i < listInputInicio.length; i++) {
        if (listInputInicio[i].value == '') {
            alert("complete los campos");
            return false;
        }
        if (listInputFin[i].value == '') {
            alert("complete los campos");
            return false;
        }
    }
    if (profesor.value == '') {
        alert("complete los campos");
        return false;
    }
    for (i = 0; i < diasSemana.length; i++) {
        if (diasSemana[i].checked === true) {
            return true;
        } else if (diasSemana[i].checked === false && i == diasSemana.length - 1) {
            alert("complete los campos");
            return false;
        }
    }
    return true;

}

