/**
 * validar respuestas de preguntas del acordeon
 */
function validaRespuestasEncuestaWeb(menu_opcion, submenu_opcion) {
    var array_exist_tr = [];
    var index = $("#id_tipo option:selected").index();
    var arrList = document.querySelectorAll('.tabla_listado tbody');
    //validar respuestas
    for (var i = 0; i < arrList.length; i++) {
        let exist_tr = arrList[i].querySelector("tr");
        if (!arrList[i].hasChildNodes() || exist_tr == null) {
            $("#acordeon").accordion({
                heightStyle: "content",
                collapsible: true,
                active: parseInt(i),
            });
            $(".ui-accordion-header.ui-state-active ").css("background", "#E84343");
            if (index == 0) {
                mensaje_encuesta = mensaje_error_pregunta_no_valida; //No se ha insertado la pregunta
            } else if (index == 1) {
                mensaje_encuesta = mensaje_error_respuesta_no_valida;  //No se ha insertado la respuesta
            }
            showDialog(mensaje_encuesta);
            return;
        };
    }
    //validar preguntas
    let acordeon = $('#acordeon');
    x = acordeon.find('h3');
    if (x.length == 0) {
        showDialog(mensaje_error_encuesta_web_vacia); // No se ha insertado los registros en la encuesta
        return;
    }
    //validar que la encuesta tipo seleccion tenga almenos 2 respuestas
    let index_select = $("#id_tipo option:selected").index();
    if (index_select == 1) {
        for (var j = 0; j < arrList.length; j++) {
            let exist_tr = arrList[j].querySelectorAll("tr");
            if (exist_tr != null) {
                array_exist_tr.push([j, exist_tr]);
            };
        }
        for (var k = 0; k < array_exist_tr.length; k++) {
            if (array_exist_tr[k][1].length < 2) {
                $("#acordeon").accordion({
                    heightStyle: "content",
                    collapsible: true,
                    active: k,
                });
                $(".ui-accordion-header.ui-state-active ").css("background", "#E84343");
                showDialog(mensaje_error_dos_registros_encuesta_web); //Cada pregunta debe tener dos respuestas
                return;
            };
        }
    }
    showConfirm(guardar_encuesta_web, guardaElemento, menu_opcion, submenu_opcion);
}
