/**Funcion para agregar plan en tabla de form plan de evaluaciones */
function agregarPlanEvalWeb() {

    var anoescolar = $('#id_empresas_anoescolar').val();
    var grado = $('#gradoinput').val();
    var materia = $('#materiainput').val();
    var lapso = $('#lapsoinput').val();

    if (anoescolar == "" || grado == "" || materia == "" || lapso == "") {

        showDialog(mensaje_faltancampos_planevaluacion, "AVISO");

    } else {

        $.ajax({
            method: "POST",
            url: "../common/chequea_plan_evaluacionweb.php",
            data: { 0: anoescolar, 1: grado, 2: lapso, 3: materia },
            success: function (data) {

                resultado = data.replace(/ /g, "");

                if (resultado == 0) {
                    $('#anoescolar').attr('disabled', 'disabled');
                    $('#gradoinput').attr('disabled', 'disabled');
                    $('#materiainput').attr('disabled', 'disabled');
                    $('#lapsoinput').attr('disabled', 'disabled');
                    $('#boton_tabla').attr('disabled', 'disabled');

                    $('#tabla').removeAttr("style");
                    $('.botonera').removeAttr("style");
                    $('#plan_detalle').removeAttr("style");
                    //creamos primer campo para cargar detalles del plan
                    CrearCampoPlanEvalWeb();
                } else {

                    showDialog(mensaje_existe_planevaluacion, "AVISO");

                }

            }
        });
    }
}

/**Funcion para agregar plan en tabla de form plan de evaluaciones */
contador = 0;
function CrearCampoPlanEvalWeb() {
    var htmlTags = '<tr id="fila' + contador + '">' +
        '<input type="hidden" >' +
        '<td><textarea placeholder="Ingrese tema" style="display:block; text-align:justify; line-height:10px; margin:4px;" name="nombre[]"  cols="80"></textarea></td>' +
        '<td><input placeholder="Ingrese tipo de evaluacion" style="display:block;" type="text" name="tipo_evaluacion[]"></td>' +
        '<td><input placeholder="Ingrese fecha" style="display:block;" class="fecha_exp" type="text" name="fecha[]" ></td>' +
        '<td><input placeholder="Ingrese ponderacion" maxlength="2" min="1" step="1" max="25" size="5" style="display: block; line-height: 22px; margin: 4px;text-align: center; padding: 0 5px; border: 1px solid #949494;" onchange="calculanotaplaneval()" type="number" name="ponderacion[]"></td>' +
        '<td></td>' +
        '<td> <span class="tabla_accion" id="boton_tabla" onclick="javascript:confirmaborrafilaplanevalweb(' + contador + ')" >Borrar</span> </td>' +
        '</tr>';
    $('#tablacuerpo').append(htmlTags);

    $.datepicker.setDefaults($.datepicker.regional[idiomaNavegador]);
    $(".fecha_exp").datepicker({
        firstDay: 1,
        minDate: new Date(),
        dateFormat: "dd-mm-yy"
    });

    var cantidad = $('#tablacuerpo')[0].children.length;

    if (cantidad == 6) {

        showDialog(mensaje_cantidadevaluaciones_planevaluacion, "AVISO");

    }

    $('#cantidadplaneval')[0].textContent = ": " + cantidad + " / " + cantidad;
    contador++;
}




/**Funcion para calcular nota de evaluacion segun nota maxima ingresada */
function calculanotaplaneval() {
    var notabase = 20;
    var cantidad = $('#tablacuerpo')[0].children.length;
    var maximaponderacion = 25;
    var minimoponderacion = 5;

    for (i = 0; i < cantidad; i++) {

        var porcentaje = $('#tablacuerpo')[0].children[i].children[4].children[0].value;

        if (porcentaje > maximaponderacion) {
            var porcentaje = $('#tablacuerpo')[0].children[i].children[4].children[0].value = maximaponderacion;
        }

        if (porcentaje < minimoponderacion) {
            var porcentaje = $('#tablacuerpo')[0].children[i].children[4].children[0].value = minimoponderacion;
        }

        var n = notabase * porcentaje;
        var valor = n / 100;
        if (valor < 10) {
            valor = '0' + valor;
        }
        $('#tablacuerpo')[0].children[i].children[5].textContent = valor;

    }
}

//funcion para confirmar borrar fila de tabla de input de evaluaciones
function confirmaborrafilaplanevalweb(id) {
    showConfirm('Debe confirmar la acción ¿Desea continuar?', borrafilaplanevalweb, id); //Seguro que desea borrar este registro
}

//funcion que borrar fila de tabla de input de evaluaciones
function borrafilaplanevalweb(id) {
    var valueinput = $('#detalle' + id).val();
    var htmlTags = '<input type="hidden" name="iddetalleborrado[]" value="' + valueinput + '">';
    $('#nuevo_elemento').append(htmlTags);

    $('#fila' + id).remove();

    var cantidad = $('#tablacuerpo')[0].children.length;

    $('#cantidadplaneval')[0].textContent = ": " + cantidad + " / " + cantidad;
}

//funcion para itinerarios en el modulo de cursos habilitar el select cursos
function ableCursos() {
    //flags para esconder o mostrar si todos son 1
    var flag_inicio = 0;
    var flag_fin = 0;
    var flag_rango = 0;
    //recupero fecha_inicio del input y la transformo a tipo date
    var fecha_inicio = document.getElementById("fecha_inicio").value;
    console.log(fecha_inicio);
    if (fecha_inicio != "") {
        flag_inicio = 1;
    }
    fecha_inicio = fecha_inicio.split("-");
    var ano = fecha_inicio[2];
    var mes = fecha_inicio[1] - 1;
    var dia = fecha_inicio[0];
    fecha_inicio = new Date(ano, mes, dia);
    //recupero fecha_fin del input y la transformo a tipo date
    var fecha_fin = document.getElementById("fecha_fin").value;
    console.log(fecha_fin);
    if (fecha_fin != "") {
        flag_fin = 1;
    }
    fecha_fin = fecha_fin.split("-");
    var ano = fecha_fin[2];
    var mes = fecha_fin[1] - 1;
    var dia = fecha_fin[0];
    fecha_fin = new Date(ano, mes, dia);
    var select_cursos = document.getElementById("cursos");
    for (var i = 0; i < select_cursos.length; i++) {
        var opt = select_cursos[i];
        var text = opt.innerText;
        var regExp = "/\(([^)]+)\)/";
        var matches = regExp.exec(text);
        var arrayDate = matches[1].split("/");
        for (var j = 0; j < arrayDate.length; j++) {
            var fecha_curso = arrayDate[j].split(" ");
            var ano = fecha_curso[0];
            var mes = fecha_curso[1] - 1;
            var dia = fecha_curso[2];
            fecha_curso = new Date(ano, mes, dia);
            if (j == 0) {
                if (fecha_curso > fecha_inicio) {
                    flag_rango = 1;
                } else {
                    flag_rango = 0;
                }
            }
            if (j == 1) {
                if (fecha_curso < fecha_fin) {
                    flag_rango = 1;
                } else {
                    flag_rango = 0;
                }
            }

        }
        console.log(flag_inicio);
        console.log(flag_fin);
        console.log(flag_rango);
        if (flag_rango == 1 && flag_inicio == 1 && flag_fin == 1) {
            opt.style.display = "block";
        } else {
            opt.style.display = "none";
        }
    }
}

function guardaAsignacion(menu_opcion, submenu_opcion) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var formulario = document.getElementById("nuevo_elemento");
        var longitudFormulario = formulario.elements.length;
        var formData = new FormData();
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        var re = "/^\w+$/";
        //var re2 = /(?=.*\d)(?=.*[a-z])(?=.*[A-Z]).{6,}/;
        for (var i = 0; i <= (longitudFormulario - 1); i++) {
            if (formulario.elements[i].required == true && formulario.elements[i].value == "") {
                showDialog(mensaje_faltan_campos);
                formulario.elements[i].classList.add("requerido");
                return false;
            } else if (formulario.elements[i].name == "name" && !re.test(formulario.elements[i].value)) {
                showDialog(formulario.elements[i].name + mensaje_error_caracteres);
                return false;
            }
            if (formulario.elements[i].type != 'file') {
                if (formulario.elements[i].type == "checkbox") {
                    if (formulario.elements[i].checked == true) {
                        formData.append(formulario.elements[i].name, formulario.elements[i].value);
                    }
                } else {
                    formData.append(formulario.elements[i].name, formulario.elements[i].value);
                }
            } else if (formulario.elements[i].value != '') {
                var files = formulario.elements[i].files;
                formData.append(formulario.elements[i].name, files[0], files[0].name);
            }
        }
        var url = "";
        var ajax = objetoAjax();;
        url = "../common/save_asignacion.php";
        ajax.open("POST", url, true);
        //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    informeProcess = 0;
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                            console.log(arr_aux);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                            console.log(arr_aux);
                        } else {
                            tab_activo = null;
                            if (notificar == false) {
                                showDialog(arr_aux[1]);
                                limpiarFiltros(menu_opcion, submenu_opcion, accionLista, null);
                                console.log(arr_aux);
                                //irAContenido(menu_activo,menu_opcion,submenu_opcion);
                            } else {
                                console.log(arr_aux);
                                var jsonData = JSON.parse(arr_aux[0]);
                                if (jsonData.notificacion == null || jsonData.notificacion == true) {
                                    if (jsonData.id_notificaciones == null) {
                                        if (jsonData.lista_empleados != null) {
                                            var listaNotificar = document.getElementById("lista_empleados");
                                            listaNotificar.value = jsonData.lista_empleados.join();
                                        }
                                        idSeleccionadas = new Array();
                                        enviaNotificacion(menu_opcion, submenu_opcion, jsonData.mensaje, accionLista, null, viewEmpleado, arr_aux[1], jsonData.asunto);
                                    } else {
                                        enviaNotificacionTabla(menu_opcion, submenu_opcion, jsonData.id_notificaciones, accionLista);
                                    }
                                } else {
                                    showDialog(arr_aux[1]);
                                    limpiarFiltros(menu_opcion, submenu_opcion, accionLista, null);
                                }
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion muestra un showConfirmPlanevaluacion
 *
 */
function showConfirmPlanevalmodal(texto, mensaje_exito) {
    var caja = document.getElementById('openModal');
    if (caja != null) {
        caja.appendChild(genContenidoComfirmPlanEval(texto, mensaje_exito));
        caja.style.opacity = 1;
        caja.style.pointerEvents = "auto";
    }
}

/**
 * Funcion que genera el contenido para la caja de showConfirmPlanevalmodal
 *
 */
function genContenidoComfirmPlanEval(texto, mensaje_exito) {
    var divElement = document.createElement('div');
    var anchorElement = document.createElement('a');
    anchorElement.innerHTML = 'X';
    anchorElement.title = 'Close';
    anchorElement.className = 'close';
    anchorElement.onclick = function () {
        hideDialog();
    };
    divElement.appendChild(anchorElement);
    var okButton = document.createElement('a');
    okButton.innerHTML = aceptar.toUpperCase();
    okButton.title = 'Ok';
    okButton.className = 'button';
    okButton.onclick = function () {
        esperaRespuesta(true);

        mensaje = $("#mensaje_objeto_plan_eval").val();
        correo = $("#correo_docente").val();
        ano_seccion = $("#ano_seccion_plan").val();
        materia = $("#materia_docente").val();

        if (mensaje != "") {

            hideDialog();
            $.ajax({
                method: "POST",
                url: "../common/envio_mail_plan_evaluacion_objetado.php",
                data: { mensaje: mensaje, correo: correo, ano_seccion: ano_seccion, materia: materia },
                success: function (data) {

                    $("#mensaje_objeto_plan_eval").val('');
                    esperaRespuesta(false);
                    showDialog(mensaje_exito, "AVISO");

                }
            });
        } else {
            showDialog(mensaje_faltancampos_planevaluacion, "AVISO");
            esperaRespuesta(false);
        }
    };
    var cancelButton = document.createElement('a');
    cancelButton.innerHTML = cancela.toUpperCase();
    cancelButton.title = 'No';
    cancelButton.className = 'button';
    cancelButton.onclick = function () {
        hideDialog();
        paginasImpresion = 0;
    };

    html = ' <textarea id="mensaje_objeto_plan_eval" style="width: 75%; height: 171px; text-align:left;resize:none;padding: 1%;"></textarea>';
    var h2Element = document.createElement('h2');
    h2Element.innerHTML = texto;
    var pElement = document.createElement('p');
    pElement.innerHTML = html;
    divElement.appendChild(h2Element);
    divElement.appendChild(pElement);
    divElement.appendChild(okButton);
    divElement.appendChild(cancelButton);
    return divElement;
}

/**
 * Funcion que verifica check de inasistencia en carga  de notas
 *
 */
function CheckChangeNotasCarga(event, id, flag_numerico) {

    campooculto = document.getElementById('id_carga_notas');

    campovalor = document.getElementById('flag_in' + id);

    if (campooculto == null) {

        if (event.currentTarget.checked) {
            campovalor.value = 1;
            $("#nota_numerica" + id).attr('disabled', 'disabled');
            $("#nota_numerica" + id).val('');
            $("#nota_remedial" + id).val('');

        } else {
            campovalor.value = 0;
            $("#nota_numerica" + id).removeAttr('disabled');
        }
    } else {

        if (event.currentTarget.checked) {
            campovalor.value = 1;
            if (flag_numerico == 1) {
                $("#nota_numerica" + id).attr('disabled', 'disabled');
                $("#nota_remedial" + id).attr('disabled', 'disabled');
                $("#nota_numerica" + id).val('');
                $("#nota_remedial" + id).val('');
            } else {
                $("#nota_texto" + id).attr('disabled', 'disabled');
                $("#nota_texto" + id).val('');
            }
        } else {
            campovalor.value = 0;
            if (flag_numerico == 1) {
                $("#nota_numerica" + id).removeAttr('disabled');
                $("#nota_remedial" + id).removeAttr('disabled');
            } else {
                $("#nota_texto" + id).removeAttr('disabled');
            }

        }
    }

}

//obtener checbox de materia pendiente para inasistencia
function materiapendientevalueid(event, id) {

    if (event.currentTarget.checked == true) {
        $(id).attr('disabled', 'disabled');
    }

    if (event.currentTarget.checked == false) {
        $(id).removeAttr('disabled');
    }
    $(id).val('');
}


/**
 * Funcion que chequea que el dia y solo debe habilitado los lunes de cada semana
 *
 */
function my_check(in_date) {
    if (in_date.getDay() != 1) {
        return [false, "", 'Not Available'];
    } else {
        return [true, "", "Available"];
    }
}
/**
* Funcion que chequea que el dia y solo debe habilitado los domingo de cada semana
*
*/
function my_check_sunday(in_date) {
    if (in_date.getDay() != 0) {
        return [false, "", 'Not Available'];
    } else {
        return [true, "", "Available"];
    }
}

