/**
 * Funcion para mostrar la condición del estudiante
 *
 */
function verCondicionEstudiante(menu_opcion, submenu_opcion, id_condicion, titulo) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && menu_opcion > 0 && !isNaN(id_condicion) && !isNaN(id_condicion)) {
        var url = "";
        var ajax = objetoAjax();;
        url = "../common/ver_condicion_estudiantes.php?op=" + menu_opcion + "&sub=" + submenu_opcion + '&id=' + id_condicion;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            showDialog(arr_aux[1]);
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }
            }
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        if (jsonData.estado == 1) {
                            showDialog(jsonData.mensaje);
                            return;
                        } else if (jsonData.estado == 2) {
                            showDialog(jsonData.mensaje);
                            flag_echar = true;
                        } else {
                            showDialog(jsonData.html, titulo);
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                    esperaRespuesta(false);
                }
                else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                    esperaRespuesta(false);
                }
            }
        };
        ajax.send(null);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}

