/**
* Funcion que muestra dialog con input para 
* cambiar las horas max de vacaciones de un empleado
*/
function showInput(seccion, elemento, idEmpleados, previousValue, year) {
    var caja = document.getElementById('openModal');
    if (caja != null) {
        var divElement = document.createElement('div');
        var anchorElement = document.createElement('a');
        anchorElement.innerHTML = 'X';
        anchorElement.title = 'Close';
        anchorElement.className = 'close';
        anchorElement.onclick = function () {
            hideDialog();
            if (flag_echar == true) {
                window.location = "../inc/salir.php";
                flag_echar = false;
            } else if (flag_recarga == true) {
                window.location.reload();
                flag_recarga = false;
            }
        };

        var h2Element = document.createElement('h2');
        h2Element.innerHTML = "Editar Máximo Vacaciones Por Horas";

        var labelElement = document.createElement('label');
        labelElement.innerHTML = "Máximo Vacaciones Por Horas";

        var inputElement = document.createElement('input');
        inputElement.setAttribute("type", "number");
        inputElement.setAttribute("min", "0");
        inputElement.setAttribute("step", "0.1");
        inputElement.setAttribute("value", (previousValue / 60).toFixed(2));
        inputElement.setAttribute("class", "dialogInput");

        var okButton = document.createElement('a');
        okButton.innerHTML = aceptar.toUpperCase();
        okButton.title = 'Guardar';
        okButton.className = 'button';
        okButton.onclick = function () {
            hideDialog();
            changeMaxVacEmpleado(seccion, elemento, idEmpleados, inputElement.value, year);
        };

        var cancelButton = document.createElement('a');
        cancelButton.innerHTML = cancela.toUpperCase();
        cancelButton.title = 'Cancelar';
        cancelButton.className = 'button';
        cancelButton.onclick = function () {
            hideDialog();
            paginasImpresion = 0;
        };

        divElement.appendChild(anchorElement);
        divElement.appendChild(h2Element);
        divElement.appendChild(labelElement);
        divElement.appendChild(inputElement);
        divElement.appendChild(okButton);
        divElement.appendChild(cancelButton);
        hideDialog();
        caja.appendChild(divElement);
        caja.style.opacity = 1;
        caja.style.pointerEvents = "auto";
    }
}

