/**
 * Procedimiento para agregar la cantidad de posibles respuesta a una pregunta
 */
function fnAgregarRespCuestionario(e) {

    let elem = e.target;
    let pregunta = elem.closest('tr').querySelector('td:first-child input[type="hidden"]');
    let respuesta = elem.closest('tr').querySelector('td:first-child input[name="respuesta"]');
    let tablaResp = elem.closest('table').querySelector('tbody');

    pregunta.value = escapeHTML(pregunta.value);
    respuesta.value = escapeHTML(respuesta.value);

    if (respuesta.value.trim().length > 0) {
        let fila = '<tr>' +
            '<td>' + respuesta.value + '<input type="hidden" name="preguntas[' + pregunta.value + '][]" value="' + respuesta.value + '"></td>' +
            '<td><span class="tabla_accion tabla_borrar_cuestionario">' + borrar + '</span></td>' +
            '</tr>';

        tablaResp.innerHTML += fila;
        respuesta.value = '';
        $(".ui-state-active, .ui-widget-content .ui-state-active, .ui-widget-header .ui-state-active, a.ui-button:active, .ui-button:active, .ui-button.ui-state-active:hover ").css("background", "#5889D6");
        document.querySelectorAll('.tabla_borrar_cuestionario').forEach(elem => elem.addEventListener('click', borrarFilaCuestionario));
    } else {
        showDialog(mensaje_error_dato_no_valido);
    }
}

/**
 * Borrar pregunta
 */
function borrarPreguntaCuestionario(e) {
    //obtener valor del atributo que se usará dicho elemento del html del DOM
    let clase = e.target.getAttribute('data-class');
    mensaje_cuestionario = borrar_pregunta_cuestionario;  //seguro que desea borrar esta pregunta
    showConfirm(mensaje_cuestionario, borrarPreguntaConfirmarCuestionario, clase);
}

function borrarPreguntaConfirmarCuestionario(clase) {

    $('.' + clase).remove();
    //cantidad de preguntas
    let x = 0;
    let acordeon = $('#acordeon');
    x = acordeon.find('h3');
    let index = $("#id_tipo option:selected").index();

    $("#acordeon").accordion("refresh");
    $("#acordeon").accordion({
        active: false
    });
}

/**
 * Borrar fila de tabla
 */
function borrarFilaCuestionario(e) {
    showConfirm(borrar_registro_cuestionario, borrarFilaConfirmarCuestionario, e); //Seguro que desea borrar este registro
}

function borrarFilaConfirmarCuestionario(e) {
    e.target.closest('tr').remove();
}

/**
 * validar respuestas de preguntas del acordeon
 */
function validaRespuestasCuestionario(menu_opcion, submenu_opcion) {
    var array_exist_tr = [];
    var arrList = document.querySelectorAll('.tabla_listado tbody');

    //validar respuestas
    for (var i = 0; i < arrList.length; i++) {
        let exist_tr = arrList[i].querySelector("tr");
        if (!arrList[i].hasChildNodes() || exist_tr == null) {
            $("#acordeon").accordion({
                heightStyle: "content",
                collapsible: true,
                active: parseInt(i),
            });
            $(".ui-accordion-header.ui-state-active ").css("background", "#E84343");
            mensaje_cuestionario = mensaje_error_pregunta_no_valida; //No se ha insertado la pregunta
            showDialog(mensaje_cuestionario);
            return;
        };
    }
    //validar preguntas
    let acordeon = $('#acordeon');
    x = acordeon.find('h3');
    if (x.length == 0) {
        showDialog(mensaje_error_cuestionario_web_vacia); // No se ha insertado los registros en la encuesta
        return;
    }

    for (var j = 0; j < arrList.length; j++) {
        let exist_tr = arrList[j].querySelectorAll("tr");
        if (exist_tr != null) {
            array_exist_tr.push([j, exist_tr]);
        };
    }
    for (var k = 0; k < array_exist_tr.length; k++) {
        if (array_exist_tr[k][1].length < 2) {
            $("#acordeon").accordion({
                heightStyle: "content",
                collapsible: true,
                active: k,
            });
            $(".ui-accordion-header.ui-state-active ").css("background", "#E84343");
            showDialog(mensaje_error_dos_registros_cuestionario);
            return;
        };
    }
    showConfirm(guardar_cuestionario, guardaElemento, menu_opcion, submenu_opcion);
}

