/**
 * Funcion que muestra el formulario para importar elementos
 *
 */
function importarPlanes(menu_opcion, submenu_opcion, accion) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var formData = new FormData();
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        if (accion != null && !isNaN(accion)) {
            formData.append('accion', accion);
        }
        var url = "";
        var ajax = objetoAjax();;
        url = "../common/import_planes.php";
        ajax.open("POST", url, true);
        //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    informeProcess = 0;
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            var jsonData = JSON.parse(arr_aux[1]);
                            showDialog(jsonData.mensaje);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            var jsonData = JSON.parse(arr_aux[1]);
                            document.getElementById("content").innerHTML = jsonData.contenido;
                            $(function () {
                                $("#filtro_empresas").pqSelect({
                                    multiplePlaceholder: seleccionar_empresa,
                                    displayText: mensaje_filtro_seleccionados,
                                    deselect: true,
                                    selectallText: seleccionar_todos,
                                    checkbox: true,
                                    maxDisplay: 6,
                                    search: true
                                }).on("change", function (evt) {
                                    var val = $(this).val();
                                    var idEmpresas = document.getElementById("select_empresas");
                                    if (idEmpresas != null) {
                                        idEmpresas.value = val;
                                    }
                                });
                            });
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
        informeProcess = 1;
    } else {
        showDialog(invalidOption);
    }
}

