function info_pago_servicio(value) {
    //verificar si el checkbox esta activado
    if (value.checked) {
        showConfirmPago(info_pago, value);
    }
}

function showConfirmPago(texto, value) {
    var caja = document.getElementById('openModal');
    if (caja != null) {
        caja.appendChild(genContenidoComfirmPago(texto, value));
        caja.style.opacity = 1;
        caja.style.pointerEvents = "auto";
    }
}

function genContenidoComfirmPago(texto, value) {
    var divElement = document.createElement('div');
    var anchorElement = document.createElement('a');
    anchorElement.innerHTML = 'X';
    anchorElement.title = 'Close';
    anchorElement.className = 'close';
    anchorElement.onclick = function () {
        hideDialog();
    };
    divElement.appendChild(anchorElement);
    var okButton = document.createElement('a');
    okButton.innerHTML = aceptar.toUpperCase();
    okButton.title = 'Ok';
    okButton.className = 'button';
    okButton.onclick = function () {
        hideDialog();
        if (value.id == 'flag_dpr') {
            document.getElementById('flag_dpr').checked = true;
        } else if (value.id == 'flag_denuncia_activa') {
            document.getElementById('flag_denuncia_activa').checked = true;
        }
    };
    var cancelButton = document.createElement('a');
    cancelButton.innerHTML = cancela.toUpperCase();
    cancelButton.title = 'No';
    cancelButton.className = 'button';
    cancelButton.onclick = function () {
        hideDialog();
        if (value.id == 'flag_dpr') {
            document.getElementById('flag_dpr').checked = false;
        } else if (value.id == 'flag_denuncia_activa') {
            document.getElementById('flag_denuncia_activa').checked = false;
        }
        paginasImpresion = 0;
    };
    var h2Element = document.createElement('h2');
    h2Element.innerHTML = aviso;
    var pElement = document.createElement('p');
    pElement.innerHTML = texto;
    divElement.appendChild(h2Element);
    divElement.appendChild(pElement);
    divElement.appendChild(okButton);
    divElement.appendChild(cancelButton);
    return divElement;
}

/**
 * Funcion que recarga la lista de Puestos PRL en Empleados 
 *
 */
function CargaPuestosPRL(selectBox) {
    if (selectBox != null) {
        if (selectBox.id == "sector_prl") {
            var sector = selectBox.options[selectBox.selectedIndex].value;

            var SelectPuestos = document.getElementById("id_job_prl");
            SelectPuestos.options.length = 0;
        }

        if (sector != "") {
            var url = "";
            var ajax = objetoAjax();
            url = "../common/recarga_puestos_normalizados.php?sector=" + sector + "&tipo=1";
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 1) {
                                showDialog(arr_aux[1]);
                            } else if (arr_aux[0] == 2) {
                                showDialog(arr_aux[1]);
                                flag_echar = true;
                            } else {
                                const jsonData = JSON.parse(arr_aux[1]);
                                for (const item of jsonData) {
                                    const option = document.createElement('option');
                                    option.value = item.id;
                                    option.text = item.name;
                                    SelectPuestos.appendChild(option);
                                }
                                $("#id_job_prl").pqSelect("refreshData");
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}


