/**
 * Funcion que agregar y elimina imput de urls de omboarding
 *
 */
function addUrlField() {
    let count = document.querySelectorAll("input[name=\'url_video[]\']").length;
    let newDiv = document.createElement("div");
    newDiv.id = "url_field_" + count;

    let newField = document.createElement("input");
    newField.type = "text";
    newField.className = "input_tabla";
    newField.maxLength = "100";
    newField.size = "30";
    newField.id = "url_video_" + count;
    newField.name = "url_video[]";
    newField.value = "https://";

    let removeButton = document.createElement("button");
    removeButton.type = "button";
    removeButton.textContent = "Quitar";
    removeButton.onclick = function () { removeUrlField(newDiv.id); };

    let br = document.createElement("br");

    newDiv.appendChild(newField);
    newDiv.appendChild(removeButton);
    newDiv.appendChild(br);

    let button = document.querySelector("button[onclick=\'addUrlField()\']");
    button.parentNode.insertBefore(newDiv, button);
}

function removeUrlField(id) {
    let field = document.getElementById(id);
    if (field) {
        field.remove();
    }
}

