function ServicioExternoUpdate(selectBox) {
    if (selectBox != null) {
        if (selectBox.id == "id_servicios_externos") {
            var ServicioExterno = selectBox.options[selectBox.selectedIndex].value;
            $("#ContenedorFecha, #ContenedorCantidad").hide();
            var InputFechaFin = document.getElementById("fecha_fin");
            var InputCantidad = document.getElementById("cantidad");
            InputFechaFin.value = '';
            InputCantidad.value = '';
        }

        if (ServicioExterno != "") {
            var url = "";
            var ajax = objetoAjax();
            url = "../common/consulta_servicios_externos.php?id_servicio=" + ServicioExterno;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 1) {
                                showDialog(arr_aux[1]);
                            } else if (arr_aux[0] == 2) {
                                showDialog(arr_aux[1]);
                                flag_echar = true;
                            } else {
                                var Servicios = arr_aux[1].split(";");
                                var Cantidad = Servicios[0];
                                var Fecha = Servicios[1];
                                var ContenedorFecha = document.getElementById("ContenedorFecha");
                                var ContenedorCantidad = document.getElementById("ContenedorCantidad");

                                if (Fecha == 1 && Cantidad == 1) {
                                    ContenedorFecha.removeAttribute("style");
                                    ContenedorCantidad.removeAttribute("style");
                                }
                                if (Fecha == 1 && Cantidad == 0) {
                                    ContenedorFecha.removeAttribute("style");
                                    ContenedorCantidad.style.display = "none";
                                }
                                if (Fecha == 0 && Cantidad == 1) {
                                    ContenedorFecha.style.display = "none";
                                    ContenedorCantidad.removeAttribute("style");
                                }

                                InputFechaFin.value = '';
                                InputCantidad.value = '';

                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}


