function MiPrestamosValue(selectBox) {
    if (selectBox != null) {

        var Prestamo = selectBox.options[selectBox.selectedIndex].value;
        var InputCuotas = document.getElementById("cuota_mes");
        InputCuotas.value = '';

        var LabelCuotas = document.getElementById("LabelCuotas");

        var LabelTasaInteres = document.getElementById("LabelTasaInteres");
        var LabelMontoCuota = document.getElementById("LabelMontoCuota");
        var InputTasaInteres = document.getElementById("InputTasaInteres");
        var InputMontoCuota = document.getElementById("InputMontoCuota");
        var InputMontoSolicitado = document.getElementById("monto_solicitado");

        if (Prestamo != "") {
            var url = "";
            var ajax = objetoAjax();
            url = "../common/consulta_opciones_prestamos.php?id_prestamo=" + Prestamo;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 1) {
                                showDialog(arr_aux[1]);
                            } else if (arr_aux[0] == 2) {
                                showDialog(arr_aux[1]);
                                flag_echar = true;
                            } else {
                                const Data = JSON.parse(arr_aux[1]);
                                let Cuota = 0;
                                let Interes = 0;
                                Interes = (Number(Data['monto_maximo']) * Number(Data['tasa'])) / 100;
                                Cuota = (Number(Data['monto_maximo']) + Interes) / Number(Data['cuotas']);

                                LabelTasaInteres.innerHTML = LabelTasaInteres_txt + ': ' + Data['tasa'] + ' %';
                                LabelMontoCuota.innerHTML = LabelMontoCuota_txt + ': ' + Cuota;
                                InputTasaInteres.value = Data['tasa'];
                                InputMontoCuota.value = Cuota;


                                LabelCuotas.innerHTML = 'Max. ' + Data['cuotas'];

                                InputCuotas.value = Data['cuotas'];

                                const slider = document.getElementById("loanSlider");
                                const amountDisplay = document.getElementById("loanAmount");

                                // Configuración inicial del slider
                                slider.max = Data['monto_maximo'];
                                slider.value = 0;
                                amountDisplay.textContent = slider.value;

                                // Actualización del valor mostrado cada vez que se mueva el slider
                                slider.addEventListener("input", function () {
                                    InputCuotas = document.getElementById("cuota_mes");
                                    InputMontoSolicitado = document.getElementById("monto_solicitado");

                                    amountDisplay.textContent = slider.value;
                                    InputMontoSolicitado.value = slider.value;
                                    Interes = (Number(slider.value) * Number(InputTasaInteres.value)) / 100;
                                    Cuota = (Number(slider.value) + Interes) / Number(InputCuotas.value);
                                    LabelMontoCuota.innerHTML = LabelMontoCuota_txt + ': ' + Cuota;

                                });
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}

function CuotasChange() {

    var InputCuotas = document.getElementById("cuota_mes");
    var InputTasaInteres = document.getElementById("InputTasaInteres");

    var LabelTasaInteres = document.getElementById("LabelTasaInteres");
    var LabelMontoCuota = document.getElementById("LabelMontoCuota");
    const slider = document.getElementById("loanSlider");
    const monto_aprobado = document.getElementById("monto_aprobado");
    InputMontoSolicitado = document.getElementById("monto_solicitado");


    if (slider !== null) {
        Interes = (Number(slider.value) * Number(InputTasaInteres.value)) / 100;
        Cuota = (Number(slider.value) + Interes) / Number(InputCuotas.value);
        LabelMontoCuota.innerHTML = LabelMontoCuota_txt + ': ' + Cuota;
        InputMontoSolicitado.value = slider.value;
    } else {
        Interes = (Number(monto_aprobado.value) * Number(InputTasaInteres.value)) / 100;
        Cuota = (Number(monto_aprobado.value) + Interes) / Number(InputCuotas.value);
        LabelMontoCuota.innerHTML = LabelMontoCuota_txt + ': ' + Cuota;
    }

}

function MontoAprobadoChange() {

    var InputCuotas = document.getElementById("cuota_mes");
    var InputTasaInteres = document.getElementById("InputTasaInteres");

    var LabelTasaInteres = document.getElementById("LabelTasaInteres");
    var LabelMontoCuota = document.getElementById("LabelMontoCuota");
    const monto_aprobado = document.getElementById("monto_aprobado");
    InputMontoSolicitado = document.getElementById("monto_solicitado");
    Interes = (Number(monto_aprobado.value) * Number(InputTasaInteres.value)) / 100;
    Cuota = (Number(monto_aprobado.value) + Interes) / Number(InputCuotas.value);
    LabelMontoCuota.innerHTML = LabelMontoCuota_txt + ': ' + Cuota;

}


