function SavePagosPrestamos(menu_opcion, submenu_opcion, PagoId) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && !isNaN(PagoId)) {

        let InputReferencia = document.getElementById("referencia");
        let Referencia = InputReferencia ? InputReferencia.value.trim() : '';

        let fileInput = document.getElementById("doc_adjunto");
        let file = fileInput ? fileInput.files[0] : null;

        if (!Referencia) {
            showDialog("El campo 'Referencia' es obligatorio.");
            return;
        }

        if (!file) {
            showDialog("Debe adjuntar un documento.");
            return;
        }

        let formData = new FormData();
        formData.append("op", menu_opcion);
        formData.append("sub", submenu_opcion);
        formData.append("id", PagoId);
        formData.append("referencia", Referencia);
        formData.append("doc_adjunto", file);

        var ajax = objetoAjax();
        var url = "../common/save_pagos_prestamos.php";
        ajax.open("POST", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                esperaRespuesta(false);
                if (ajax.status == 200) {
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            showDialog(arr_aux[1]);
                            irAContenido(menu_activo, menu_opcion, submenu_opcion);
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                } else {
                    showDialog("Error:" + ajax.status);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
    }
}

