//Gestion de Roles
function SelectEmpleadoGestionRol(menu_opcion, submenu_opcion, empleadoId) {
    esperaRespuesta(true);
    idEmpleadoGestioRoles = empleadoId;

    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && !isNaN(empleadoId)) {
        var checked = "";
        var url = "";
        var ajax = objetoAjax();
        url = "../common/get_info_gestion_roles.php?op=" + menu_opcion + "&sub=" + submenu_opcion + "&id=" + empleadoId;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            let gestion_roles = procesarDatosGestionRoles(arr_aux[1]);
                            let select = document.getElementById("Gestion_Roles_Select");
                            select.innerHTML = '<option value="0">Seleccionar Rol</option>';
                            if (!Array.isArray(gestion_roles.roles) || gestion_roles.roles.length === 0) {
                                let option = document.createElement("option");
                                option.value = "0";
                                option.textContent = "No hay roles disponibles";
                                select.appendChild(option);
                            } else {
                                gestion_roles.roles.forEach((rol) => {
                                    if (rol.nombre == 'rolDelegacion' ||
                                        rol.nombre == 'rolRRHH' || rol.nombre == 'rolInspeccion') {
                                        let option = document.createElement("option");
                                        option.value = rol.id;
                                        option.textContent = rol.nombre;
                                        select.disabled = false;
                                        select.appendChild(option);
                                    }
                                });
                            }

                            //Proceso y Coloco las Delegaciones.
                            let tbody_delegacion = document.querySelector("#Tabla_Delegacion tbody");
                            tbody_delegacion.innerHTML = "";
                            let tbody_empleados_delegacione = document.querySelector("#Tabla_Delegacion_Empleados tbody");
                            tbody_empleados_delegacione.innerHTML = "";

                            if (!Array.isArray(gestion_roles.delegaciones) || gestion_roles.delegaciones.length === 0) {
                                let row = document.createElement("tr");
                                row.innerHTML = `<td><input type="checkbox"/></td> <td colspan="3" style="text-align: center;">No hay delegaciones disponibles</td>`;
                                tbody_delegacion.appendChild(row);
                            } else {
                                gestion_roles.delegaciones.forEach((delegacion, index) => {
                                    let valorDelegacion = delegacion.replace("D-", "");
                                    let row = document.createElement("tr");
                                    row.innerHTML = `
                                        <td>
                                            <input type="checkbox" id="delegacion_${index}" value="${valorDelegacion}"/>
                                        </td>
                                        <td>${delegacion}</td>
                                    `;
                                    tbody_delegacion.appendChild(row);
                                    let checkbox_delegacion = row.querySelector(`#delegacion_${index}`);
                                    checkbox_delegacion.addEventListener("change", function () {
                                        Empleados_Gestion_Roles(this.value, 1);
                                    });
                                });
                            }

                            //Proceso y Coloco las Cotizaciones.
                            let tbody_cotizaciones = document.querySelector("#Tabla_Cotizaciones tbody");
                            tbody_cotizaciones.innerHTML = "";
                            let tbody_empleados_cotizaciones = document.querySelector("#Tabla_Cotizacion_Empleados tbody");
                            tbody_empleados_cotizaciones.innerHTML = "";

                            if (!Array.isArray(gestion_roles.cotizaciones) || gestion_roles.cotizaciones.length === 0) {
                                let row = document.createElement("tr");
                                row.innerHTML = `<td><input type="checkbox"/></td> <td colspan="3" style="text-align: center;">No hay cotizaciones disponibles</td>`;
                                tbody_cotizaciones.appendChild(row);
                            } else {
                                gestion_roles.cotizaciones.forEach((cotizacion, index) => {
                                    let valorcotizaciones = cotizacion.replace("C-", "");
                                    let row = document.createElement("tr");
                                    row.innerHTML = `
                                        <td>
                                            <input type="checkbox" id="cotizacion${index}" value="${valorcotizaciones}" />
                                        </td>
                                        <td>${cotizacion}</td>
                                    `;
                                    tbody_cotizaciones.appendChild(row);

                                    let checkbox_cotizaciones = row.querySelector(`#cotizacion${index}`);
                                    checkbox_cotizaciones.addEventListener("change", function () {
                                        Empleados_Gestion_Roles(this.value, 2);
                                    });
                                });
                            }

                            //Proceso y Coloco a los Empleados
                            let tbody_empleados_seleccionados = document.querySelector("#Tabla_Empleados_Seleccionados tbody");
                            let tbody_empleados = document.querySelector("#Tabla_Empleados tbody");
                            tbody_empleados_seleccionados.innerHTML = "";
                            tbody_empleados.innerHTML = "";
                            if (!Array.isArray(gestion_roles.empleados) || gestion_roles.empleados.length === 0) {
                                let row = document.createElement("tr");
                                row.innerHTML = `<td><input type="checkbox"/><td colspan="3" style="text-align: center;">No hay empleados disponibles</td><td></td>`;
                                tbody_empleados.appendChild(row);
                                return;
                            }
                            gestion_roles.empleados.forEach((empleado, index) => {
                                let row = document.createElement("tr");
                                row.innerHTML = `
                                    <td>
                                        <input type="checkbox" id="empleado_${index}" value="${empleado.id}" />
                                    </td>
                                    <td>${empleado.nombreCompleto}</td>
                                    <td>${empleado.centroDepartamento}</td>
                                `;
                                tbody_empleados.appendChild(row);
                                let checkbox_empleados = row.querySelector(`#empleado_${index}`);
                                checkbox_empleados.addEventListener("change", function () {
                                    if (this.checked) {
                                        AgregarEmpleadoTablaDestino(empleado, tbody_empleados_seleccionados);
                                    } else {
                                        EliminarEmpleadoTablaDestino(empleado.id, tbody_empleados_seleccionados);
                                    }
                                });
                            });
                            esperaRespuesta(false);
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                    esperaRespuesta(false);
                }
                else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                    esperaRespuesta(false);
                }
            }
        };
        ajax.send(null);
        esperaRespuesta(true);
    }
}

function CheckRolGestionEmpleado(menu_opcion, submenu_opcion, empleadoId) {

    $.ajax({
        url: "../common/consulta_info_gestion_roles.php",
        type: "POST",
        data: {
            op: menu_opcion,
            sub: submenu_opcion,
            id: empleadoId
        },
        dataType: "text",
        success: function (response) {
            try {
                let jsonResponse = JSON.parse(response);
                if (jsonResponse.estado === 0) {
                    document.getElementById('Btn_Edit').style.display = "block";
                    document.getElementById('Btn_Add').style.display = "none";
                    CargaDatosRoles(menu_opcion, submenu_opcion, jsonResponse.Empleado, jsonResponse.Informacion, empleadoId);
                } else {
                    document.getElementById('Btn_Add').style.display = "block";
                    document.getElementById('Btn_Edit').style.display = "none";
                    SelectEmpleadoGestionRol(menu_opcion, submenu_opcion, empleadoId);
                }
            } catch (error) {
                showDialog(`Error al procesar la respuesta JSON: ${error.message}`);
                esperaRespuesta(false);
            }
        },
        error: function (xhr, status, error) {
            showDialog(`Error en la petición: ${xhr.statusText} (${xhr.status})`);
            esperaRespuesta(false);
        }
    });
}

function CargaDatosRoles(menu_opcion, submenu_opcion, Empleado, Informacion, empleadoId) {

    esperaRespuesta(true);
    idEmpleadoGestioRoles = empleadoId;
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && !isNaN(empleadoId)) {
        var checked = "";
        var url = "";
        var ajax = objetoAjax();
        url = "../common/get_info_gestion_roles.php?op=" + menu_opcion + "&sub=" + submenu_opcion + "&id=" + empleadoId;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {

                            //Gestiono los Roles de Empleados
                            let gestion_roles = procesarDatosGestionRoles(arr_aux[1]);
                            let select = document.getElementById("Gestion_Roles_Select");
                            select.innerHTML = '';
                            let option = document.createElement("option");
                            option.value = Empleado.roles.id;
                            option.textContent = Empleado.roles.nombre;
                            select.disabled = true;
                            select.appendChild(option);


                            //Proceso y Coloco las Delegaciones Tabla 1.
                            let tbody_delegacion = document.querySelector("#Tabla_Delegacion tbody");
                            let tbody_empleados_delegacione = document.querySelector("#Tabla_Delegacion_Empleados tbody");
                            tbody_delegacion.innerHTML = "";
                            tbody_empleados_delegacione.innerHTML = "";
                            let delegacionesUnicas = new Set();
                            let CheckDelegaciones = "";

                            if (Array.isArray(Informacion.Delegaciones) && Informacion.Delegaciones.length > 0) {
                                Informacion.Delegaciones.forEach((delegacion) => {
                                    if (delegacion.cod_centro && delegacion.cod_centro.includes("·")) {
                                        let valorDelegacion = delegacion.cod_centro.split("·")[1];
                                        delegacionesUnicas.add(valorDelegacion);
                                    }
                                });
                            }
                            if (!Array.isArray(gestion_roles.delegaciones) || gestion_roles.delegaciones.length === 0) {
                                let row = document.createElement("tr");
                                row.innerHTML = `<td colspan="4" style="text-align: center;">No hay delegaciones disponibles</td>`;
                                tbody_delegacion.appendChild(row);
                            } else {
                                gestion_roles.delegaciones.forEach((delegacion, index) => {
                                    let valorDelegacion = delegacion.replace("D-", "");
                                    let CheckDelegaciones = delegacionesUnicas.has(valorDelegacion) ? "checked" : "";
                                    let row = document.createElement("tr");
                                    row.innerHTML = `
                                        <td>
                                            <input type="checkbox" ${CheckDelegaciones} id="delegacion_${index}" value="${valorDelegacion}"/>
                                        </td>
                                        <td>${delegacion}</td>
                                    `;

                                    tbody_delegacion.appendChild(row);
                                    let checkbox_delegacion = row.querySelector(`#delegacion_${index}`);
                                    checkbox_delegacion.addEventListener("change", function () {
                                        Empleados_Gestion_Roles(this.value, 1);
                                    });
                                });
                            }


                            //Proceso y Coloco las Cotizaciones Tabla 1.
                            let tbody_cotizaciones = document.querySelector("#Tabla_Cotizaciones tbody");
                            let tbody_empleados_cotizaciones = document.querySelector("#Tabla_Cotizacion_Empleados tbody");
                            tbody_empleados_cotizaciones.innerHTML = "";
                            tbody_cotizaciones.innerHTML = "";

                            let cotizacionesUnicas = new Set();
                            let CheckCotizaciones = "";

                            if (Array.isArray(Informacion.Cotizaciones) && Informacion.Cotizaciones.length > 0) {
                                Informacion.Cotizaciones.forEach((cotizacion) => {
                                    if (cotizacion.tipo_empleado) {
                                        cotizacionesUnicas.add(cotizacion.tipo_empleado);
                                    }
                                });
                            }

                            if (!Array.isArray(gestion_roles.cotizaciones) || gestion_roles.cotizaciones.length === 0) {
                                let row = document.createElement("tr");
                                row.innerHTML = `<td><input type="checkbox"/></td> <td colspan="3" style="text-align: center;">No hay cotizaciones disponibles</td>`;
                                tbody_cotizaciones.appendChild(row);
                            } else {
                                gestion_roles.cotizaciones.forEach((cotizacion, index) => {
                                    let valorcotizaciones = cotizacion.replace("C-", "");
                                    //Coloco el Check de las Cotizaciones
                                    // let CheckCotizaciones = cotizacionesUnicas.has(valorcotizaciones) ? "checked" : "";
                                    let row = document.createElement("tr");
                                    row.innerHTML = `
                                        <td>
                                            <input type="checkbox" ${CheckCotizaciones} id="cotizacion${index}" value="${valorcotizaciones}" />
                                        </td>
                                        <td>${cotizacion}</td>
                                    `;
                                    tbody_cotizaciones.appendChild(row);

                                    let checkbox_cotizaciones = row.querySelector(`#cotizacion${index}`);
                                    checkbox_cotizaciones.addEventListener("change", function () {
                                        Empleados_Gestion_Roles(this.value, 2);
                                    });
                                });
                            }

                            //Proceso y Coloco a los Empleados Tabla 1
                            let tbody_empleados_seleccionados = document.querySelector("#Tabla_Empleados_Seleccionados tbody");
                            let tbody_empleados = document.querySelector("#Tabla_Empleados tbody");
                            tbody_empleados_seleccionados.innerHTML = "";
                            tbody_empleados.innerHTML = "";
                            let CheckEmpleados = "";
                            if (!Array.isArray(gestion_roles.empleados) || gestion_roles.empleados.length === 0) {
                                let row = document.createElement("tr");
                                row.innerHTML = `<td><input type="checkbox"/><td colspan="3" style="text-align: center;">No hay empleados disponibles</td><td></td>`;
                                tbody_empleados.appendChild(row);
                                return;
                            }
                            gestion_roles.empleados.forEach((empleado, index) => {
                                let row = document.createElement("tr");
                                row.innerHTML = `
                                    <td>
                                        <input type="checkbox" ${CheckEmpleados} id="empleado_${index}" value="${empleado.id}" />
                                    </td>
                                    <td>${empleado.nombreCompleto}</td>
                                    <td>${empleado.centroDepartamento}</td>
                                `;
                                tbody_empleados.appendChild(row);
                                let checkbox_empleados = row.querySelector(`#empleado_${index}`);
                                checkbox_empleados.addEventListener("change", function () {
                                    if (this.checked) {
                                        AgregarEmpleadoTablaDestino(empleado, tbody_empleados_seleccionados);
                                    } else {
                                        EliminarEmpleadoTablaDestino(empleado.id, tbody_empleados_seleccionados);
                                    }
                                });
                            });

                            // Agrupar primero por delegación y luego por departamento dentro de cada delegación
                            Object.entries(Empleado.delegaciones).forEach(([delegacion, codigo]) => {
                                // Fila de encabezado para la delegación
                                let headerRow = document.createElement("tr");
                                headerRow.innerHTML = `
                                    <td colspan="2" style="background: #f5f5f5;" class="titulo_seleccionar">
                                        <span><strong>D-${codigo}</strong></span>
                                    </td>
                                `;
                                tbody_empleados_delegacione.appendChild(headerRow);

                                // Filtrar empleados que pertenecen a esta delegación
                                let empleadosDelegacion = Informacion.Delegaciones.filter((empleado) => {
                                    let codCentroSplit = empleado.cod_centro.split("·");
                                    return codCentroSplit[1] === codigo;
                                });

                                if (empleadosDelegacion.length > 0) {
                                    // Agrupar empleados de esta delegación por departamento
                                    let empleadosPorDepartamento = {};
                                    empleadosDelegacion.forEach((empleado) => {
                                        let departamento = empleado.nombre_departamento || 'Sin departamento';
                                        if (!empleadosPorDepartamento[departamento]) {
                                            empleadosPorDepartamento[departamento] = [];
                                        }
                                        empleadosPorDepartamento[departamento].push(empleado);
                                    });

                                    // Recorrer los departamentos dentro de la delegación
                                    Object.entries(empleadosPorDepartamento).forEach(([departamento, empleados]) => {
                                        // Generar un ID único para este departamento dentro de esta delegación
                                        const deptoID = `${codigo}_${departamento}`.replace(/[^a-zA-Z0-9_]/g, '_');

                                        // Fila de encabezado del departamento con checkbox
                                        let deptHeaderRow = document.createElement("tr");
                                        deptHeaderRow.innerHTML = `
                                            <td colspan="2" style="background: #f5f5f5; padding-left: 12%;" class="titulo_seleccionar">
                                                <input type="checkbox" id="select_depto_${deptoID}" onclick="toggleDepartamento('${deptoID}', this.checked)" checked />
                                                <strong>${departamento}</strong>
                                            </td>
                                        `;
                                        tbody_empleados_delegacione.appendChild(deptHeaderRow);

                                        // Agregar los empleados del departamento
                                        empleados.forEach((empleado, index) => {
                                            let isChecked = Empleado.empleados.includes(empleado.id) ? "checked" : "";
                                            let row = document.createElement("tr");
                                            row.innerHTML = `
                                                <td>
                                                    <input type="checkbox" class="empleado_checkbox_${deptoID} CheckEmpleado" id="empleado_seleccionado_${codigo}_${index}" value="${empleado.id}" ${isChecked} onchange="verificaDepartamento('${deptoID}')"/>
                                                </td>
                                                <td class="px-[1%] py-[.5%]">${empleado.nombre} ${empleado.apellidos}</td>
                                            `;
                                            tbody_empleados_delegacione.appendChild(row);
                                        });
                                        verificaDepartamento(deptoID);
                                    });

                                } else {
                                    // Si no hay empleados en la delegación
                                    let noEmpleadoRow = document.createElement("tr");
                                    noEmpleadoRow.innerHTML = `
                                        <td class="px-[1%] py-[.5%]" colspan="2" style="text-align: center;">No hay empleados en esta delegación</td>
                                    `;
                                    tbody_empleados_delegacione.appendChild(noEmpleadoRow);
                                }
                            });
                            esperaRespuesta(false);
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404);
                    esperaRespuesta(false);
                }
                else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status);
                    esperaRespuesta(false);
                }
            }
        };
        ajax.send(null);
        esperaRespuesta(true);
    }
}

function procesarDatosGestionRoles(jsonData) {

    let data = JSON.parse(jsonData);

    let roles = [];
    for (let key in data.roles) {
        roles.push({ id: key, nombre: data.roles[key] });
    }

    let empleados = Array.isArray(data.empleados) && data.empleados.length > 0
        ? data.empleados[0].map((empleado) => ({
            id: empleado.id,
            nombreCompleto: `${empleado.nombre} ${empleado.apellidos}`,
            centroDepartamento: `Delegacion: ${empleado.centro} - Centro: ${empleado.departamento}`,
        }))
        : [];

    let delegaciones = Array.isArray(data.delegacion) && data.delegacion.length > 0
        ? Object.values(data.delegacion[0])
        : [];

    let cotizaciones = Array.isArray(data.cotizaciones) && data.cotizaciones.length > 0
        ? data.cotizaciones[0]
        : [];

    return {
        roles,
        empleados,
        delegaciones,
        cotizaciones,
    };
}

