function getDelegacionesSeleccionadas() {
    let checkboxes = document.querySelectorAll("#Tabla_Delegacion tbody input[type='checkbox']");
    let seleccionadas = [];
    checkboxes.forEach((checkbox) => {
        if (checkbox.checked) {
            seleccionadas.push(checkbox.value);
        }
    });
    return seleccionadas;
}

function getCotizacionesSeleccionadas() {
    let checkboxes = document.querySelectorAll("#Tabla_Cotizaciones tbody input[type='checkbox']");
    let seleccionadas = [];
    checkboxes.forEach((checkbox) => {
        if (checkbox.checked) {
            seleccionadas.push(checkbox.value);
        }
    });
    return seleccionadas;
}

function ProcesoDatosEmpleados(jsonData, opcion) {
    let data = JSON.parse(jsonData);

    let empleado_obtenidos = {};
    
    if (opcion === 1) {
        if (!Array.isArray(data.empleados) || data.empleados.length === 0) {
            console.warn("No hay empleados disponibles en el JSON.");
            return {};
        }
    
        return data.empleados.reduce((acc, empleado) => {
            let delegacion = `${empleado.cod_centro.split('·')[1]}`;
            let departamento = empleado.nombre_departamento ? empleado.nombre_departamento : "Sin Departamento";
        
            if (!acc[delegacion]) {
                acc[delegacion] = {}; 
            }
            if (!acc[delegacion][departamento]) {
                acc[delegacion][departamento] = []; 
            }
            acc[delegacion][departamento].push({
                id: empleado.id,
                nombreCompleto: `${empleado.nombre} ${empleado.apellidos}`,
            });
        
            return acc;
        }, {});
        
    } else if (opcion === 2) {
        if (!Array.isArray(data.empleados) || data.empleados.length === 0) {
            console.warn("No hay empleados disponibles en el JSON.");
            return {};
        }
    
        return data.empleados.reduce((acc, empleado) => {
            let cotizacion = `${empleado.tipo_empleado}`;
            let departamento = empleado.nombre_departamento ? empleado.nombre_departamento : "Sin Departamento";
        
            if (!acc[cotizacion]) {
                acc[cotizacion] = [];
            }
            if (!acc[cotizacion][departamento]) {
                acc[cotizacion][departamento] = []; 
            }
            acc[cotizacion][departamento].push({
                id: empleado.id,
                nombreCompleto: `${empleado.nombre} ${empleado.apellidos}`,
            });
        
            return acc;
        }, {});
    }

    return empleado_obtenidos;
}

function AgregarEmpleadoTablaDestino(empleado, tbody_empleados_seleccionados) {
    let row = document.createElement("tr");
    row.setAttribute("id", `seleccionado_${empleado.id}`);
    row.innerHTML = `
        <td>
            <input type="checkbox" class="CheckEmpleado" id="empleado_seleccionado_${empleado.id}" value="${empleado.id}" checked />
        </td>
        <td>${empleado.nombreCompleto}</td>
        <td>${empleado.centroDepartamento}</td>
    `;
    tbody_empleados_seleccionados.appendChild(row);

    let checkbox_destino = row.querySelector(`#empleado_seleccionado_${empleado.id}`);
    checkbox_destino.addEventListener("change", function () {
        if (!this.checked) {
            EliminarEmpleadoTablaDestino(empleado.id);
            let checkbox_origen = document.querySelector(`#empleado_${empleado.id}`);
            if (checkbox_origen) {
                checkbox_origen.checked = false;
            }
        }
    });
}

function EliminarEmpleadoTablaDestino(empleadoId, tbody_empleados_seleccionados) {
    let row = document.querySelector(`#seleccionado_${empleadoId}`);
    if (row) {
        row.remove();
    }
}

function GuardaGestionRoles(menu_opcion, submenu_opcion) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        let id_empleados = obtenerEmpleadosSeleccionados();
        let select = document.getElementById('Gestion_Roles_Select');
        let rol_empleado = select.value;

        let radio = document.querySelector('input[name="id"]:checked');
        let id = radio ? radio.value : null;

        if (rol_empleado != 0) {
            var url = "";
            var ajax = objetoAjax();
            url = "../common/save_gestion_rol.php?op=" + menu_opcion + "&sub=" + submenu_opcion + "&id_empleados=" + id_empleados + "&id_rol=" + rol_empleado + "&id=" + id;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 1) {
                                showDialog(arr_aux[1]);
                            } else if (arr_aux[0] == 2) {
                                showDialog(arr_aux[1]);
                                flag_echar = true;
                            } else {
                                showDialog(arr_aux[1]);
                                irAContenido(menu_activo, menu_opcion, submenu_opcion);
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                        esperaRespuesta(false);
                    }
                    else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                        esperaRespuesta(false);
                    }
                }
            };
            ajax.send(null);
            esperaRespuesta(true);
        } else {
            showDialog("Error: Debe Seleccionar un Rol");
        }
    }
}

