function obtenerEmpleadosSeleccionados() {
    let empleadosSeleccionados = [];
    let tablas = [
        'Tabla_Delegacion_Empleados',
        'Tabla_Cotizacion_Empleados',
        'Tabla_Empleados_Seleccionados'
    ];
    tablas.forEach(tablaId => {
        let tabla = document.getElementById(tablaId);
        if (tabla) {
            let checkboxes = tabla.querySelectorAll('input[type="checkbox"].CheckEmpleado:checked');
            checkboxes.forEach(checkbox => {
                empleadosSeleccionados.push(checkbox.value);
            });
        }
    });

    return empleadosSeleccionados;
}



function verificaDepartamento(deptoID) {
    const checkboxes = document.querySelectorAll(`.empleado_checkbox_${deptoID}`);
    const deptoCheckbox = document.getElementById(`select_depto_${deptoID}`);

    const total = checkboxes.length;
    const marcados = Array.from(checkboxes).filter(cb => cb.checked).length;

    if (marcados === total) {
        deptoCheckbox.checked = true;
        deptoCheckbox.indeterminate = false;
    } else if (marcados === 0) {
        deptoCheckbox.checked = false;
        deptoCheckbox.indeterminate = false;
    } else {
        deptoCheckbox.checked = false;
        deptoCheckbox.indeterminate = true;
    }
}


// Función global para marcar o desmarcar empleados del departamento
function toggleDepartamento(deptoID, isChecked) {
    document.querySelectorAll(`.empleado_checkbox_${deptoID}`).forEach(chk => {
        chk.checked = isChecked;
    });
}

// Extendemos la Session del Usuario Respondiendo Encuentas
function ExtSession() {
    var url = "";
    var ajax = objetoAjax();
    url = "../common/Sesion_Ext.php";
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
            } else if (ajax.status == 404) {
                showDialog(error404);
            }
            else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status);
            }
        }
    };
    ajax.send(null);
}

function verModalWidget(menu_opcion, submenu_opcion, elemento_id) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && elemento_id != "") {
        var url = "";
        var ajax = objetoAjax();
        tarjetas = new Array();
        dispositivos_comunicacion = new Array();
        url = "../common/gen_view_elem.php?op=" + menu_opcion + "&sub=" + submenu_opcion + '&id=' + elemento_id;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1], 1);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            if (arr_aux[2] === undefined) {
                                showDialogWidget(arr_aux[1]);
                            } else {
                                showDialogWidget(arr_aux[1]);
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        esperaRespuesta(true);
        ajax.send(null);
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion muestra un dialogo para Tarea
 *
 */
function showDialogWidget(contenido) {
    var caja = document.getElementById('openModal');
    if (caja != null) {
        hideDialog();
        caja.appendChild(genContenidoDialogoWidget(contenido));
        caja.style.opacity = 1;
        caja.style.pointerEvents = "auto";
    }
}

function genContenidoDialogoWidget(texto) {
    var divElement = document.createElement('div');
    divElement.className = 'custom-style';
    var anchorElement = document.createElement('div');
    //anchorElement.innerHTML = '<i class="ti ti-x custom-icon"></i>';
    anchorElement.innerHTML = '<span> X </span>';
    anchorElement.title = 'Close';
    anchorElement.id = 'botonPrincipal';
    anchorElement.className = 'custom-anchor';
    anchorElement.onclick = function () {
        hideDialog();
        if (flag_echar == true) {
            window.location = "../inc/salir.php";
            flag_echar = false;
        } else if (flag_recarga == true) {
            window.location.reload();
            flag_recarga = false;
        }
    };
    var pElement = document.createElement('p');
    pElement.innerHTML = texto;
    // Seleccionar y ocultar el div con la clase "botonera"
    var botonera = pElement.querySelector('.botonera');
    if (botonera) {
        botonera.style.display = 'none';
    }
    var divContent = document.createElement('div');
    divContent.className = 'custom-div-content';
    var divButtons = document.createElement('div');
    divButtons.className = 'custom-div-buttons';
    var headerModal = pElement.querySelector('#headerModalNoticias');
    headerModal.appendChild(anchorElement)
    divContent.appendChild(pElement);
    divElement.appendChild(divContent);
    return divElement;
}


