function toggleContenido() {
    var checkboxVacaciones = document.getElementById("flag_vacaciones");
    var contenidoVacaciones = document.getElementById("contenido_vacaciones");
    var contenidoPermisos = document.getElementById("contenido_permisos");
    var campoDias = document.getElementById("campo_dias");
    var campoFechaCaducidad = document.getElementById("campo_fecha_caducidad");
    var btnAplicarATodos = document.getElementById("btn_aplicar_a_todos");
    
    if (checkboxVacaciones) {
        if (contenidoVacaciones && contenidoPermisos) {
            if (checkboxVacaciones.checked) {
                contenidoVacaciones.style.display = "block";
                contenidoPermisos.style.display = "none";
            } else {
                contenidoVacaciones.style.display = "none";
                contenidoPermisos.style.display = "block";
            }
        }
        
        if (campoDias) {
            campoDias.style.display = checkboxVacaciones.checked ? "none" : "block";
        }
        
        if (campoFechaCaducidad) {
            campoFechaCaducidad.style.display = checkboxVacaciones.checked ? "none" : "block";
        }
        
        if (btnAplicarATodos) {
            btnAplicarATodos.style.display = checkboxVacaciones.checked ? "none" : "block";
        }
    }
}
document.addEventListener("DOMContentLoaded", function() {  
    toggleContenido();    
    var checkboxVacaciones = document.getElementById("flag_vacaciones");
    if (checkboxVacaciones) {
        checkboxVacaciones.addEventListener("change", toggleContenido);
    }
});

function aplicarFiltrosCombinados(filtros) {
    const tabla = document.getElementById("tcd_cursos");
    const filas = tabla.getElementsByTagName("tr");

    for (let i = 1; i < filas.length; i++) {
        let mostrar = true;

        filtros.forEach(filtro => {
            const celda = filas[i].getElementsByTagName("td")[filtro.columna];
            const valorCelda = celda?.textContent.toLowerCase() || "";

            let valorFiltro = "";
            if (filtro.tipo === 'select') {
                valorFiltro = document.getElementById(filtro.id).value.toLowerCase();
                if (valorFiltro && valorCelda !== valorFiltro) {
                    mostrar = false;
                }
            } else if (filtro.tipo === 'input') {
                valorFiltro = document.getElementById(filtro.id).value.toLowerCase();
                if (valorFiltro && !valorCelda.includes(valorFiltro)) {
                    mostrar = false;
                }
            }
        });

        filas[i].style.display = mostrar ? "" : "none";
    }

    actualizarContadorCursos("tcd_cursos", "contador_cursos");
}

function actualizarContadorCursos(tablaId, contadorId) {
    const tabla = document.getElementById(tablaId);
    const filas = tabla.getElementsByTagName("tr");
    let visibles = 0;

    for (let i = 1; i < filas.length; i++) {
        const esFila = filas[i].getElementsByTagName("td").length > 0;
        if (esFila && filas[i].style.display !== "none") {
            visibles++;
        }
    }

    document.getElementById(contadorId).textContent = visibles;
    document.getElementById("total_cursos").textContent = visibles;
}

function ordenarTablaPorColumna(tablaId, columnaIndex, ascendente = true) {
    const tabla = document.getElementById(tablaId);
    const filas = Array.from(tabla.querySelectorAll("tr")).slice(1); // Ignora encabezado

    filas.sort((a, b) => {
        const celdaA = a.cells[columnaIndex]?.textContent.trim().toLowerCase() || "";
        const celdaB = b.cells[columnaIndex]?.textContent.trim().toLowerCase() || "";
        return ascendente ? celdaA.localeCompare(celdaB) : celdaB.localeCompare(celdaA);
    });

    const cuerpo = tabla.tBodies[0];
    filas.forEach(fila => cuerpo.appendChild(fila));
}

function aplicarFiltroMultiple(idInput, columnas, tablaId) {
    const filtroValor = document.getElementById(idInput).value.trim().toLowerCase();
    const tabla = document.getElementById(tablaId);
    const filas = tabla.getElementsByTagName("tr");

    for (let i = 1; i < filas.length; i++) {
        let mostrar = false;

        columnas.forEach(col => {
            const celda = filas[i].getElementsByTagName("td")[col];
            const valorCelda = celda?.innerText.trim().toLowerCase() || "";

            // Aquí imprimimos para depurar
            console.log(`Columna ${col}: Valor = "${valorCelda}"`);

            if (valorCelda.includes(filtroValor)) {
                mostrar = true;
            }
        });

        filas[i].style.display = mostrar ? "" : "none";
    }
    actualizarContadorCursos("tcd_cursos", "contador_cursos");
}



